pub fn path2_native_projection_preimage_da_v1_bytes(
    bundle: &Path2NativeProjectionBundleV1,
) -> Result<Vec<u8>, String> {
    let mut out = Vec::new();
    out.extend_from_slice(PATH2_NATIVE_PROJECTION_PREIMAGE_DA_DOMAIN.as_bytes());
    append_frame(
        &mut out,
        b"context_projection",
        &path2_native_context_projection_v1_bytes(&bundle.context)?,
    );
    append_frame(
        &mut out,
        b"account_projection",
        &path2_native_account_projection_v1_bytes(&bundle.account),
    );
    append_frame(
        &mut out,
        b"spend_projection",
        &path2_native_spend_projection_v1_bytes(&bundle.spend)?,
    );
    append_frame(
        &mut out,
        b"lifecycle_projection",
        &path2_native_lifecycle_projection_v1_bytes(&bundle.lifecycle),
    );
    append_frame(
        &mut out,
        b"state_projection",
        &path2_native_state_projection_v1_bytes(&bundle.state),
    );
    append_frame(
        &mut out,
        b"obstruction_flags_digest",
        &bundle.obstruction_flags_digest,
    );
    append_frame(&mut out, b"message_digest", &bundle.message_digest);
    append_frame(
        &mut out,
        b"current_state_digest",
        &bundle.current_state_digest,
    );
    append_frame(&mut out, b"proof_commitment", &bundle.proof_commitment);
    Ok(out)
}

pub fn path2_native_projection_preimage_da_digest_v1(
    bundle: &Path2NativeProjectionBundleV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_native_projection_preimage_da_v1_bytes(bundle)?).into())
}

pub fn path2_native_boundary_v1_digest(
    p_context_digest: &[u8; DIGEST_BYTES],
    p_account_digest: &[u8; DIGEST_BYTES],
    p_spend_digest: &[u8; DIGEST_BYTES],
    p_lifecycle_digest: &[u8; DIGEST_BYTES],
    p_state_digest: &[u8; DIGEST_BYTES],
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    frame.extend_from_slice(PATH2_NATIVE_BOUNDARY_DOMAIN.as_bytes());
    for digest in [
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_state_digest,
    ] {
        frame.extend_from_slice(digest);
    }
    Sha256::digest(frame).into()
}

pub fn path2_native_no_obstruction_flags_digest() -> [u8; DIGEST_BYTES] {
    Sha256::digest(PATH2_NATIVE_NO_OBSTRUCTION_FLAGS_DOMAIN.as_bytes()).into()
}

fn path2_native_derive_boundary_frame_v1(
    bundle: &Path2NativeProjectionBundleV1,
) -> Result<
    (
        Path2NativeTranscriptProjectionV1,
        Path2NativeCheckedCoreFrameV1,
    ),
    String,
> {
    let p_context_digest = path2_native_context_projection_v1_digest(&bundle.context)?;
    let p_account_digest = path2_native_account_projection_v1_digest(&bundle.account);
    let p_spend_digest = path2_native_spend_projection_v1_digest(&bundle.spend)?;
    let p_lifecycle_digest = path2_native_lifecycle_projection_v1_digest(&bundle.lifecycle);
    let p_state_digest = path2_native_state_projection_v1_digest(&bundle.state);
    let native_boundary_digest = path2_native_boundary_v1_digest(
        &p_context_digest,
        &p_account_digest,
        &p_spend_digest,
        &p_lifecycle_digest,
        &p_state_digest,
    );
    let checked_core_frame_domain_digest: [u8; DIGEST_BYTES] =
        Sha256::digest(PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes()).into();
    let transcript_projection = Path2NativeTranscriptProjectionV1 {
        native_boundary_digest,
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_state_digest,
        checked_core_frame_domain_digest,
        aggregation_mode: bundle.context.aggregation_mode,
    };
    let p_transcript_digest = path2_native_transcript_projection_v1_digest(&transcript_projection)?;
    let checked_core_frame = Path2NativeCheckedCoreFrameV1 {
        native_boundary_version: bundle.context.native_boundary_version,
        parameter_set_id: bundle.context.parameter_set_id,
        verifier_family_id: bundle.context.verifier_family_id,
        account_creation_domain_digest: bundle.context.account_creation_domain_digest,
        spend_verifier_domain_digest: bundle.context.spend_verifier_domain_digest,
        chain_or_application_domain_digest: bundle.context.chain_or_application_domain_digest,
        fork_or_epoch_scope_digest: bundle.context.fork_or_epoch_scope_digest,
        aggregation_mode: bundle.context.aggregation_mode,
        native_boundary_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_transcript_digest,
        p_state_digest,
        message_digest: bundle.message_digest,
        current_state_digest: bundle.current_state_digest,
        proof_commitment: bundle.proof_commitment,
    };
    Ok((transcript_projection, checked_core_frame))
}

fn path2_native_public_prevalidation_failed_v1() -> String {
    PATH2_NATIVE_SIGNER_PUBLIC_PREVALIDATION_REJECTION_CODE.to_string()
}

pub fn path2_native_signer_prevalidated_public_input_v1(
    bundle: Path2NativeProjectionBundleV1,
) -> Result<Path2NativeSignerPrevalidatedPublicInputV1, String> {
    let p_context_digest = path2_native_context_projection_v1_digest(&bundle.context)
        .map_err(|_| path2_native_public_prevalidation_failed_v1())?;
    let p_account_digest = path2_native_account_projection_v1_digest(&bundle.account);
    let p_spend_digest = path2_native_spend_projection_v1_digest(&bundle.spend)
        .map_err(|_| path2_native_public_prevalidation_failed_v1())?;
    let p_lifecycle_digest = path2_native_lifecycle_projection_v1_digest(&bundle.lifecycle);
    let p_state_digest = path2_native_state_projection_v1_digest(&bundle.state);
    if bundle.context.verifier_family_id != bundle.spend.spend_verifier_family_id {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.context.aggregation_mode != bundle.spend.aggregation_mode {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.context.spend_verifier_domain_digest != bundle.spend.spend_domain_separator_digest {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.account.public_key_identity != bundle.spend.public_key_identity {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    let expected_public_key_identity = path2_native_public_key_identity_digest_v1(
        bundle.spend.spend_verifier_family_id,
        bundle.spend.checked_core_verifier_handle_digest,
    )
    .map_err(|_| path2_native_public_prevalidation_failed_v1())?;
    if bundle.account.public_key_identity != expected_public_key_identity {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.spend.allowed_state_transition_class_digest
        != bundle.state.consumed_successor_state_class
    {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.lifecycle.live_status_marker != bundle.state.live_state_requirement {
        return Err(path2_native_public_prevalidation_failed_v1());
    }
    if bundle.obstruction_flags_digest != path2_native_no_obstruction_flags_digest() {
        return Err(path2_native_public_prevalidation_failed_v1());
    }

    let (transcript_projection, checked_core_frame) =
        path2_native_derive_boundary_frame_v1(&bundle)
            .map_err(|_| path2_native_public_prevalidation_failed_v1())?;
    validate_path2_native_checked_core_frame_v1(&checked_core_frame)
        .map_err(|_| path2_native_public_prevalidation_failed_v1())?;
    let projection_preimage_da_digest = path2_native_projection_preimage_da_digest_v1(&bundle)
        .map_err(|_| path2_native_public_prevalidation_failed_v1())?;

    Ok(Path2NativeSignerPrevalidatedPublicInputV1 {
        schema: PATH2_NATIVE_SIGNER_PREVALIDATED_PUBLIC_INPUT_SCHEMA,
        bundle,
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_state_digest,
        p_transcript_digest: checked_core_frame.p_transcript_digest,
        native_boundary_digest: transcript_projection.native_boundary_digest,
        projection_preimage_da_digest,
    })
}

pub fn assemble_path2_native_boundary_v1(
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
) -> Result<Path2NativeBoundaryAssemblyV1, String> {
    if bundle.context.verifier_family_id != bundle.spend.spend_verifier_family_id {
        return Err("Path 2 native assembly verifier family mismatch".to_string());
    }
    if bundle.context.aggregation_mode != bundle.spend.aggregation_mode {
        return Err("Path 2 native assembly aggregation mode mismatch".to_string());
    }
    if bundle.context.spend_verifier_domain_digest != bundle.spend.spend_domain_separator_digest {
        return Err("Path 2 native assembly spend domain mismatch".to_string());
    }
    if bundle.account.public_key_identity != bundle.spend.public_key_identity {
        return Err("Path 2 native assembly public-key identity mismatch".to_string());
    }
    let expected_public_key_identity = path2_native_public_key_identity_digest_v1(
        bundle.spend.spend_verifier_family_id,
        bundle.spend.checked_core_verifier_handle_digest,
    )?;
    if bundle.account.public_key_identity != expected_public_key_identity {
        return Err("Path 2 native assembly public-key identity is not bound to checked-core verifier handle".to_string());
    }
    if bundle.spend.allowed_state_transition_class_digest
        != bundle.state.consumed_successor_state_class
    {
        return Err("Path 2 native assembly spend-state transition mismatch".to_string());
    }
    if bundle.lifecycle.live_status_marker != bundle.state.live_state_requirement {
        return Err("Path 2 native assembly lifecycle-state live marker mismatch".to_string());
    }
    if bundle.obstruction_flags_digest != path2_native_no_obstruction_flags_digest() {
        return Err("Path 2 native assembly obstruction flags are not cleared".to_string());
    }

    let (transcript_projection, checked_core_frame) =
        path2_native_derive_boundary_frame_v1(bundle)?;
    let p_context_digest = transcript_projection.p_context_digest;
    let p_account_digest = transcript_projection.p_account_digest;
    let p_spend_digest = transcript_projection.p_spend_digest;
    let p_lifecycle_digest = transcript_projection.p_lifecycle_digest;
    let p_state_digest = transcript_projection.p_state_digest;
    let p_transcript_digest = checked_core_frame.p_transcript_digest;
    let native_boundary_digest = checked_core_frame.native_boundary_digest;
    path2_native_checked_core_accept_v1(
        &checked_core_frame,
        &bundle.spend.checked_core_verifier_handle_digest,
        checked_core_proof_bytes,
    )?;
    let account_view = public_native_account_view_v1(
        bundle.context.native_boundary_version,
        bundle.context.parameter_set_id,
        bundle.context.verifier_family_id,
        bundle.context.aggregation_mode,
        native_boundary_digest,
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_transcript_digest,
        p_state_digest,
        bundle.lifecycle.live_status_marker,
        bundle.state.account_state_root_before,
        bundle.obstruction_flags_digest,
    )?;
    let spend_view = public_native_spend_view_v1(&checked_core_frame, checked_core_proof_bytes)?;
    Ok(Path2NativeBoundaryAssemblyV1 {
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_state_digest,
        p_transcript_digest,
        native_boundary_digest,
        transcript_projection,
        checked_core_frame,
        account_view,
        spend_view,
    })
}

pub fn path2_native_consensus_carrier_v1_from_assembly(
    assembly: &Path2NativeBoundaryAssemblyV1,
    projection_preimage_da_digest: [u8; DIGEST_BYTES],
) -> Path2NativeConsensusCarrierV1 {
    Path2NativeConsensusCarrierV1 {
        carrier_version: PATH2_NATIVE_CONSENSUS_CARRIER_VERSION,
        native_boundary_version: assembly.account_view.native_boundary_version,
        parameter_set_id: assembly.account_view.parameter_set_id,
        verifier_family_id: assembly.account_view.verifier_family_id,
        aggregation_mode: assembly.account_view.aggregation_mode,
        public_lifecycle_marker: assembly.account_view.public_lifecycle_marker,
        native_boundary_digest: assembly.native_boundary_digest,
        p_context_digest: assembly.p_context_digest,
        p_account_digest: assembly.p_account_digest,
        p_spend_digest: assembly.p_spend_digest,
        p_lifecycle_digest: assembly.p_lifecycle_digest,
        p_state_digest: assembly.p_state_digest,
        p_transcript_digest: assembly.p_transcript_digest,
        public_state_root: assembly.account_view.public_state_root,
        obstruction_flags_digest: assembly.account_view.obstruction_flags_digest,
        projection_preimage_da_digest,
    }
}

pub fn validate_path2_native_consensus_carrier_v1(
    carrier: &Path2NativeConsensusCarrierV1,
) -> Result<(), String> {
    if carrier.carrier_version != PATH2_NATIVE_CONSENSUS_CARRIER_VERSION {
        return Err(format!(
            "Path 2 native consensus carrier version mismatch: got {}, expected {}",
            carrier.carrier_version, PATH2_NATIVE_CONSENSUS_CARRIER_VERSION
        ));
    }
    validate_path2_native_context_fields(
        carrier.native_boundary_version,
        carrier.parameter_set_id,
        carrier.verifier_family_id,
        carrier.aggregation_mode,
    )
}

pub fn path2_native_consensus_carrier_v1_bytes(
    carrier: &Path2NativeConsensusCarrierV1,
) -> Result<Vec<u8>, String> {
    validate_path2_native_consensus_carrier_v1(carrier)?;
    let mut out = Vec::with_capacity(PATH2_NATIVE_CONSENSUS_CARRIER_BYTES);
    out.extend_from_slice(PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN.as_bytes());
    out.extend_from_slice(&carrier.carrier_version.to_le_bytes());
    out.extend_from_slice(&carrier.native_boundary_version.to_le_bytes());
    out.extend_from_slice(&carrier.parameter_set_id.to_le_bytes());
    out.extend_from_slice(&carrier.verifier_family_id.to_le_bytes());
    out.push(carrier.aggregation_mode);
    out.push(carrier.public_lifecycle_marker);
    for digest in [
        &carrier.native_boundary_digest,
        &carrier.p_context_digest,
        &carrier.p_account_digest,
        &carrier.p_spend_digest,
        &carrier.p_lifecycle_digest,
        &carrier.p_state_digest,
        &carrier.p_transcript_digest,
        &carrier.public_state_root,
        &carrier.obstruction_flags_digest,
        &carrier.projection_preimage_da_digest,
    ] {
        out.extend_from_slice(digest);
    }
    debug_assert_eq!(out.len(), PATH2_NATIVE_CONSENSUS_CARRIER_BYTES);
    Ok(out)
}

pub fn path2_native_consensus_carrier_v1_digest(
    carrier: &Path2NativeConsensusCarrierV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_native_consensus_carrier_v1_bytes(carrier)?).into())
}

pub fn decode_path2_native_consensus_carrier_v1(
    bytes: &[u8],
) -> Result<Path2NativeConsensusCarrierV1, String> {
    if bytes.len() != PATH2_NATIVE_CONSENSUS_CARRIER_BYTES {
        return Err(format!(
            "Path 2 native consensus carrier has {} bytes, expected {}",
            bytes.len(),
            PATH2_NATIVE_CONSENSUS_CARRIER_BYTES
        ));
    }
    if !bytes.starts_with(PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN.as_bytes()) {
        return Err("Path 2 native consensus carrier domain mismatch".to_string());
    }
    let mut offset = PATH2_NATIVE_CONSENSUS_CARRIER_DOMAIN.len();
    let carrier_version = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let native_boundary_version = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let parameter_set_id = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let verifier_family_id = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
    offset += 2;
    let aggregation_mode = bytes[offset];
    offset += 1;
    let public_lifecycle_marker = bytes[offset];
    offset += 1;
    let native_boundary_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_context_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_account_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_spend_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_lifecycle_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_state_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let p_transcript_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let public_state_root = read_path2_native_checked_core_digest(bytes, &mut offset);
    let obstruction_flags_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    let projection_preimage_da_digest = read_path2_native_checked_core_digest(bytes, &mut offset);
    debug_assert_eq!(offset, PATH2_NATIVE_CONSENSUS_CARRIER_BYTES);

    let carrier = Path2NativeConsensusCarrierV1 {
        carrier_version,
        native_boundary_version,
        parameter_set_id,
        verifier_family_id,
        aggregation_mode,
        public_lifecycle_marker,
        native_boundary_digest,
        p_context_digest,
        p_account_digest,
        p_spend_digest,
        p_lifecycle_digest,
        p_state_digest,
        p_transcript_digest,
        public_state_root,
        obstruction_flags_digest,
        projection_preimage_da_digest,
    };
    validate_path2_native_consensus_carrier_v1(&carrier)?;
    Ok(carrier)
}

pub fn verify_path2_native_consensus_carrier_v1_against_bundle(
    carrier: &Path2NativeConsensusCarrierV1,
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
) -> Result<Path2NativeBoundaryAssemblyV1, String> {
    validate_path2_native_consensus_carrier_v1(carrier)?;
    let assembly = assemble_path2_native_boundary_v1(bundle, checked_core_proof_bytes)?;
    let projection_preimage_da_digest = path2_native_projection_preimage_da_digest_v1(bundle)?;
    let expected =
        path2_native_consensus_carrier_v1_from_assembly(&assembly, projection_preimage_da_digest);
    if carrier != &expected {
        return Err("Path 2 native consensus carrier does not match projection bundle".to_string());
    }
    Ok(assembly)
}

pub fn path2_native_consensus_carrier_preflight_report_v1(
    carrier: &Path2NativeConsensusCarrierV1,
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
) -> Path2NativeConsensusCarrierPreflightReportV1 {
    let carrier_digest = path2_native_consensus_carrier_v1_digest(carrier).ok();
    let mut accepted = false;
    let mut rejection_code = None;
    let mut recomputed_native_boundary_digest = None;

    if validate_path2_native_consensus_carrier_v1(carrier).is_err() {
        rejection_code = Some("reject_invalid_carrier_context");
    } else {
        match assemble_path2_native_boundary_v1(bundle, checked_core_proof_bytes) {
            Ok(assembly) => {
                recomputed_native_boundary_digest = Some(assembly.native_boundary_digest);
                match path2_native_projection_preimage_da_digest_v1(bundle) {
                    Ok(projection_preimage_da_digest) => {
                        let expected = path2_native_consensus_carrier_v1_from_assembly(
                            &assembly,
                            projection_preimage_da_digest,
                        );
                        if carrier == &expected {
                            accepted = true;
                        } else {
                            rejection_code = Some("reject_carrier_bundle_mismatch");
                        }
                    }
                    Err(_) => {
                        rejection_code = Some("reject_projection_preimage_da_noncanonical");
                    }
                }
            }
            Err(_) => {
                rejection_code = Some("reject_projection_bundle_inconsistent");
            }
        }
    }

    Path2NativeConsensusCarrierPreflightReportV1 {
        schema: PATH2_NATIVE_CONSENSUS_PREFLIGHT_REPORT_SCHEMA,
        accepted,
        rejection_code,
        carrier_digest,
        recomputed_native_boundary_digest,
        native_boundary_digest: carrier.native_boundary_digest,
        p_context_digest: carrier.p_context_digest,
        p_account_digest: carrier.p_account_digest,
        p_spend_digest: carrier.p_spend_digest,
        p_lifecycle_digest: carrier.p_lifecycle_digest,
        p_state_digest: carrier.p_state_digest,
        p_transcript_digest: carrier.p_transcript_digest,
        public_state_root: carrier.public_state_root,
        obstruction_flags_digest: carrier.obstruction_flags_digest,
        projection_preimage_da_digest: carrier.projection_preimage_da_digest,
    }
}

