#[inline(never)]
fn path2_native_zeroize_bytes_v1(buf: &mut [u8]) {
    for byte in buf {
        unsafe {
            ptr::write_volatile(byte, 0);
        }
    }
    compiler_fence(Ordering::SeqCst);
}

#[inline(never)]
fn path2_native_zeroize_u16s_v1(buf: &mut [u16]) {
    for word in buf {
        unsafe {
            ptr::write_volatile(word, 0);
        }
    }
    compiler_fence(Ordering::SeqCst);
}

#[inline(never)]
fn path2_native_zeroize_u32s_v1(buf: &mut [u32]) {
    for word in buf {
        unsafe {
            ptr::write_volatile(word, 0);
        }
    }
    compiler_fence(Ordering::SeqCst);
}

#[inline(never)]
fn path2_native_zeroize_signer_digest_frame_v1(
    buf: &mut [u8; PATH2_NATIVE_SIGNER_DIGEST_FRAME_BYTES],
) {
    for byte in buf {
        unsafe {
            ptr::write_volatile(byte, 0);
        }
    }
    compiler_fence(Ordering::SeqCst);
}

const PATH2_NATIVE_PRIVATE_SHA256_IV_V1: [u32; 8] = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
];

const PATH2_NATIVE_PRIVATE_SHA256_K_V1: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

#[inline(always)]
fn path2_native_private_sha256_ch_v1(x: u32, y: u32, z: u32) -> u32 {
    (x & y) ^ (!x & z)
}

#[inline(always)]
fn path2_native_private_sha256_maj_v1(x: u32, y: u32, z: u32) -> u32 {
    (x & y) ^ (x & z) ^ (y & z)
}

#[inline(always)]
fn path2_native_private_sha256_big_sigma0_v1(x: u32) -> u32 {
    x.rotate_right(2) ^ x.rotate_right(13) ^ x.rotate_right(22)
}

#[inline(always)]
fn path2_native_private_sha256_big_sigma1_v1(x: u32) -> u32 {
    x.rotate_right(6) ^ x.rotate_right(11) ^ x.rotate_right(25)
}

#[inline(always)]
fn path2_native_private_sha256_small_sigma0_v1(x: u32) -> u32 {
    x.rotate_right(7) ^ x.rotate_right(18) ^ (x >> 3)
}

#[inline(always)]
fn path2_native_private_sha256_small_sigma1_v1(x: u32) -> u32 {
    x.rotate_right(17) ^ x.rotate_right(19) ^ (x >> 10)
}

#[inline(never)]
fn path2_native_private_sha256_digest_v1(data: &[u8], out: &mut [u8; DIGEST_BYTES]) {
    assert!(
        data.len() <= PATH2_NATIVE_SIGNER_DIGEST_FRAME_BYTES,
        "Path 2 native private SHA-256 input exceeds fixed signer frame"
    );
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let padded_len = ((data.len() + 1 + 8 + 63) / 64) * 64;
    let mut workspace_uninit =
        MaybeUninit::<[u8; PATH2_NATIVE_SIGNER_PRIVATE_SHA256_WORKSPACE_BYTES]>::uninit();
    let workspace_ptr = workspace_uninit.as_mut_ptr() as *mut u8;
    for idx in 0..PATH2_NATIVE_SIGNER_PRIVATE_SHA256_WORKSPACE_BYTES {
        unsafe {
            ptr::write_volatile(workspace_ptr.add(idx), 0);
        }
    }
    let workspace = unsafe { &mut *workspace_uninit.as_mut_ptr() };
    for idx in 0..data.len() {
        unsafe {
            ptr::write_volatile(
                workspace.as_mut_ptr().add(idx),
                ptr::read_volatile(data.as_ptr().add(idx)),
            );
        }
    }
    workspace[data.len()] = 0x80;
    let mut schedule = [0_u32; 64];
    let mut state = PATH2_NATIVE_PRIVATE_SHA256_IV_V1;
    workspace[padded_len - 8..padded_len].copy_from_slice(&bit_len.to_be_bytes());

    for block in workspace[..padded_len].chunks_exact(64) {
        for (idx, word) in schedule.iter_mut().take(16).enumerate() {
            let offset = idx * 4;
            *word = u32::from_be_bytes([
                block[offset],
                block[offset + 1],
                block[offset + 2],
                block[offset + 3],
            ]);
        }
        for idx in 16..64 {
            schedule[idx] = path2_native_private_sha256_small_sigma1_v1(schedule[idx - 2])
                .wrapping_add(schedule[idx - 7])
                .wrapping_add(path2_native_private_sha256_small_sigma0_v1(
                    schedule[idx - 15],
                ))
                .wrapping_add(schedule[idx - 16]);
        }

        let mut a = state[0];
        let mut b = state[1];
        let mut c = state[2];
        let mut d = state[3];
        let mut e = state[4];
        let mut f = state[5];
        let mut g = state[6];
        let mut h = state[7];
        for idx in 0..64 {
            let t1 = h
                .wrapping_add(path2_native_private_sha256_big_sigma1_v1(e))
                .wrapping_add(path2_native_private_sha256_ch_v1(e, f, g))
                .wrapping_add(PATH2_NATIVE_PRIVATE_SHA256_K_V1[idx])
                .wrapping_add(schedule[idx]);
            let t2 = path2_native_private_sha256_big_sigma0_v1(a)
                .wrapping_add(path2_native_private_sha256_maj_v1(a, b, c));
            h = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
        state[4] = state[4].wrapping_add(e);
        state[5] = state[5].wrapping_add(f);
        state[6] = state[6].wrapping_add(g);
        state[7] = state[7].wrapping_add(h);
    }

    for (idx, word) in state.iter().enumerate() {
        out[idx * 4..idx * 4 + 4].copy_from_slice(&word.to_be_bytes());
    }
    path2_native_zeroize_bytes_v1(workspace);
    path2_native_zeroize_u32s_v1(&mut schedule);
    path2_native_zeroize_u32s_v1(&mut state);
}

struct Path2NativeSignerDigestFrameV1 {
    bytes: [u8; PATH2_NATIVE_SIGNER_DIGEST_FRAME_BYTES],
    len: usize,
}

impl Path2NativeSignerDigestFrameV1 {
    fn new() -> Self {
        Self {
            bytes: [0_u8; PATH2_NATIVE_SIGNER_DIGEST_FRAME_BYTES],
            len: 0,
        }
    }

    fn append(&mut self, data: &[u8]) {
        let end = self
            .len
            .checked_add(data.len())
            .expect("Path 2 native signer digest frame length overflow");
        assert!(
            end <= self.bytes.len(),
            "Path 2 native signer digest frame capacity exceeded"
        );
        self.bytes[self.len..end].copy_from_slice(data);
        self.len = end;
    }

    fn append_frame(&mut self, label: &[u8], data: &[u8]) {
        self.append(&(label.len() as u16).to_le_bytes());
        self.append(label);
        self.append(&(data.len() as u64).to_le_bytes());
        self.append(data);
    }

    fn as_slice(&self) -> &[u8] {
        &self.bytes[..self.len]
    }

    fn zeroize(&mut self) {
        path2_native_zeroize_signer_digest_frame_v1(&mut self.bytes);
        self.len = 0;
    }
}

impl Path2NativeHonestConstructorSecretMaterialV1 {
    fn zeroize(&mut self) {
        path2_native_zeroize_bytes_v1(&mut self.authorization_local_seed);
        path2_native_zeroize_bytes_v1(&mut self.gauge_seed);
        path2_native_zeroize_bytes_v1(&mut self.randomizer_seed);
        path2_native_zeroize_bytes_v1(&mut self.wallet_recovery_seed);
        path2_native_zeroize_u16s_v1(&mut self.proof_randomizer_syndrome);
    }
}

#[derive(PartialEq, Eq)]
pub struct Path2NativeSignerEntropyRootV1 {
    pub root_entropy: [u8; DIGEST_BYTES],
    pub account_nonce: [u8; DIGEST_BYTES],
}

impl Path2NativeSignerEntropyRootV1 {
    fn zeroize(&mut self) {
        path2_native_zeroize_bytes_v1(&mut self.root_entropy);
        path2_native_zeroize_bytes_v1(&mut self.account_nonce);
    }
}

impl Drop for Path2NativeSignerEntropyRootV1 {
    fn drop(&mut self) {
        self.zeroize();
    }
}

impl Drop for Path2NativeHonestConstructorSecretMaterialV1 {
    fn drop(&mut self) {
        self.zeroize();
    }
}

pub fn path2_native_signer_entropy_root_from_os_v1()
-> Result<Path2NativeSignerEntropyRootV1, String> {
    let mut root = Path2NativeSignerEntropyRootV1 {
        root_entropy: [0_u8; DIGEST_BYTES],
        account_nonce: [0_u8; DIGEST_BYTES],
    };
    if getrandom::getrandom(&mut root.root_entropy).is_err() {
        root.zeroize();
        return Err("Path 2 native OS entropy root failure".to_string());
    }
    if getrandom::getrandom(&mut root.account_nonce).is_err() {
        root.zeroize();
        return Err("Path 2 native OS entropy nonce failure".to_string());
    }
    Ok(root)
}

