impl ProductionReviewedFq12HiddenSourceProof {
    pub fn new(bytes: [u8; REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES]) -> Self {
        Self { bytes }
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, String> {
        if bytes.len() != REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES {
            return Err(format!(
                "reviewed Fq12 hidden-source proof has {} bytes, expected {REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES}",
                bytes.len()
            ));
        }
        Ok(Self {
            bytes: bytes.try_into().unwrap(),
        })
    }

    pub fn as_bytes(&self) -> &[u8; REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES] {
        &self.bytes
    }
}

impl HiddenSourceFallbackProjectionCarrier {
    pub fn new(bytes: [u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES]) -> Self {
        Self { bytes }
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, String> {
        decode_hidden_source_fallback_projection_carrier(bytes)?;
        Ok(Self {
            bytes: bytes.try_into().unwrap(),
        })
    }

    pub fn as_bytes(&self) -> &[u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES] {
        &self.bytes
    }

    pub fn decode(&self) -> Result<HiddenSourceFallbackProjectionDecodedCarrier, String> {
        decode_hidden_source_fallback_projection_carrier(&self.bytes)
    }
}

pub fn decode_hidden_source_fallback_projection_carrier(
    bytes: &[u8],
) -> Result<HiddenSourceFallbackProjectionDecodedCarrier, String> {
    if bytes.len() != HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES {
        return Err(format!(
            "hidden-source fallback projection carrier has {} bytes, expected {HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES}",
            bytes.len()
        ));
    }

    let mut lanes = [0_u16; HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES];
    for (lane, out) in lanes.iter_mut().enumerate() {
        let offset = lane * 2;
        let value = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]);
        if value >= Q {
            return Err(format!(
                "hidden-source fallback projection carrier lane {lane} is noncanonical q12289 value {value}"
            ));
        }
        *out = value;
    }

    let mut check_bytes = [0_u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES];
    check_bytes.copy_from_slice(&bytes[24..27]);
    let mut transcript_binding = [0_u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES];
    transcript_binding.copy_from_slice(&bytes[27..56]);
    Ok(HiddenSourceFallbackProjectionDecodedCarrier {
        lanes,
        check_bytes,
        transcript_binding,
    })
}

pub fn hidden_source_fallback_projection_leakage_accounting()
-> HiddenSourceFallbackProjectionLeakageAccounting {
    let algebraic_lane_bytes = HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES * 2;
    let charged_projection_bytes =
        algebraic_lane_bytes + HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES;
    let context_binding_bytes = HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES;
    let accounted_carrier_bytes = charged_projection_bytes + context_binding_bytes;
    let unaccounted_carrier_bytes =
        HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES - accounted_carrier_bytes;
    HiddenSourceFallbackProjectionLeakageAccounting {
        carrier_bytes: HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES,
        envelope_bytes: REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_FALLBACK_PROJECTION_BYTES,
        algebraic_lane_count: HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES,
        algebraic_lane_bytes,
        check_bytes: HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES,
        transcript_binding_bytes: HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES,
        charged_projection_bytes,
        context_binding_bytes,
        accounted_carrier_bytes,
        unaccounted_carrier_bytes,
        all_carrier_bytes_accounted: accounted_carrier_bytes
            == HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES,
    }
}

pub fn hidden_source_fallback_checked_core_transcript_frame_bytes() -> usize {
    HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_DOMAIN
        .as_bytes()
        .len()
        + HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_PROFILE
            .as_bytes()
            .len()
        + SIS_FULL_RESPONSE_RESIDUES * 2
}

pub fn encode_hidden_source_fallback_checked_core_transcript_frame(
    response: &[u16; SIS_FULL_RESPONSE_RESIDUES],
) -> Result<Vec<u8>, String> {
    let mut frame =
        Vec::with_capacity(hidden_source_fallback_checked_core_transcript_frame_bytes());
    frame.extend_from_slice(HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_DOMAIN.as_bytes());
    frame
        .extend_from_slice(HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_PROFILE.as_bytes());
    for (index, value) in response.iter().enumerate() {
        if *value >= Q {
            return Err(format!(
                "hidden-source fallback checked-core transcript response coordinate {index} is noncanonical q12289 value {value}"
            ));
        }
        frame.extend_from_slice(&value.to_le_bytes());
    }
    Ok(frame)
}

pub fn decode_hidden_source_fallback_checked_core_transcript_frame(
    frame: &[u8],
) -> Result<[u16; SIS_FULL_RESPONSE_RESIDUES], String> {
    let expected = hidden_source_fallback_checked_core_transcript_frame_bytes();
    if frame.len() != expected {
        return Err(format!(
            "hidden-source fallback checked-core transcript frame has {} bytes, expected {expected}",
            frame.len()
        ));
    }

    let domain = HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_DOMAIN.as_bytes();
    if &frame[..domain.len()] != domain {
        return Err(
            "hidden-source fallback checked-core transcript frame domain mismatch".to_string(),
        );
    }
    let profile = HIDDEN_SOURCE_FALLBACK_CHECKED_CORE_TRANSCRIPT_FRAME_PROFILE.as_bytes();
    let profile_start = domain.len();
    let profile_end = profile_start + profile.len();
    if &frame[profile_start..profile_end] != profile {
        return Err(
            "hidden-source fallback checked-core transcript frame profile mismatch".to_string(),
        );
    }

    let mut response = [0_u16; SIS_FULL_RESPONSE_RESIDUES];
    let mut offset = profile_end;
    for (index, value) in response.iter_mut().enumerate() {
        let decoded = u16::from_le_bytes([frame[offset], frame[offset + 1]]);
        if decoded >= Q {
            return Err(format!(
                "hidden-source fallback checked-core transcript response coordinate {index} is noncanonical q12289 value {decoded}"
            ));
        }
        *value = decoded;
        offset += 2;
    }
    Ok(response)
}

pub fn hidden_source_fallback_checked_core_response_difference_from_transcripts(
    transcript_a: &[u8],
    transcript_b: &[u8],
) -> Result<[u16; SIS_FULL_RESPONSE_RESIDUES], String> {
    let response_a = decode_hidden_source_fallback_checked_core_transcript_frame(transcript_a)?;
    let response_b = decode_hidden_source_fallback_checked_core_transcript_frame(transcript_b)?;
    let mut difference = [0_u16; SIS_FULL_RESPONSE_RESIDUES];
    for (index, out) in difference.iter_mut().enumerate() {
        *out = ((response_a[index] as u32 + Q as u32 - response_b[index] as u32) % Q as u32) as u16;
    }
    Ok(difference)
}

pub fn verify_hidden_source_fallback_projection_public_bridge(
    carrier: &HiddenSourceFallbackProjectionDecodedCarrier,
    statement: &HiddenSourceFallbackProjectionPublicBridgeStatement,
) -> Result<(), String> {
    for (lane, (&observed, &expected)) in carrier
        .lanes
        .iter()
        .zip(statement.projection_values.iter())
        .enumerate()
    {
        if expected >= Q {
            return Err(format!(
                "hidden-source fallback projection expected lane {lane} ({}) is noncanonical q12289 value {expected}",
                HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS[lane]
            ));
        }
        if observed != expected {
            return Err(format!(
                "hidden-source fallback projection lane {lane} ({}) mismatch: observed {observed}, expected {expected}",
                HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS[lane]
            ));
        }
    }
    if carrier.check_bytes != statement.check_bytes {
        return Err("hidden-source fallback projection check bytes mismatch".to_string());
    }
    if carrier.transcript_binding != statement.transcript_binding {
        return Err("hidden-source fallback projection transcript binding mismatch".to_string());
    }
    Ok(())
}

pub fn classify_hidden_source_fallback_checked_core_break(
    input: &HiddenSourceFallbackProjectionCheckedCoreBreakInput,
) -> Result<HiddenSourceFallbackProjectionBreakExport, String> {
    let decoded =
        decode_hidden_source_fallback_projection_carrier(&input.projection_carrier_bytes)?;
    if decoded != input.decoded_carrier {
        return Err(
            "hidden-source fallback checked-core export carrier replay mismatch".to_string(),
        );
    }
    for (index, value) in input.response_difference.iter().enumerate() {
        if *value >= Q {
            return Err(format!(
                "hidden-source fallback checked-core response difference coordinate {index} is noncanonical q12289 value {value}"
            ));
        }
    }
    if input.checked_core_matrix_domain.is_empty() {
        return Err("hidden-source fallback checked-core matrix domain is empty".to_string());
    }

    let failed_equation_index_or_kernel_certificate_id = match &input.failure {
        HiddenSourceFallbackProjectionCheckedCoreFailure::ResponseRelationMismatch {
            failed_equation_index,
        } => format!("failed_equation_index:{failed_equation_index}"),
        HiddenSourceFallbackProjectionCheckedCoreFailure::ResponseLinkKernelCertificateMismatch {
            certificate_id,
        } => {
            if certificate_id.is_empty() {
                return Err(
                    "hidden-source fallback checked-core kernel certificate id is empty"
                        .to_string(),
                );
            }
            format!("kernel_certificate_id:{certificate_id}")
        }
    };

    Ok(
        HiddenSourceFallbackProjectionBreakExport::CheckedCoreOrResponseLink(
            HiddenSourceFallbackProjectionCheckedCoreBreakExport {
                serialized_checked_core_transcript: input
                    .serialized_checked_core_transcript
                    .clone(),
                projection_carrier_56_bytes: input.projection_carrier_bytes,
                decoded_12_q12289_lanes: decoded.lanes,
                response_difference_23_field_vector: input.response_difference,
                checked_core_matrix_domain: input.checked_core_matrix_domain.clone(),
                checked_core_matrix_transcript_sha256: input.checked_core_matrix_transcript_sha256,
                failed_equation_index_or_kernel_certificate_id,
                field_modulus_q: Q,
            },
        ),
    )
}

pub fn classify_hidden_source_fallback_checked_core_transcript_difference_break(
    input: &HiddenSourceFallbackProjectionCheckedCoreTranscriptDifferenceInput,
) -> Result<HiddenSourceFallbackProjectionBreakExport, String> {
    let response_difference =
        hidden_source_fallback_checked_core_response_difference_from_transcripts(
            &input.checked_core_transcript_a,
            &input.checked_core_transcript_b,
        )?;
    let mut serialized_checked_core_transcript = Vec::new();
    append_frame(
        &mut serialized_checked_core_transcript,
        b"checked_core_transcript_a",
        &input.checked_core_transcript_a,
    );
    append_frame(
        &mut serialized_checked_core_transcript,
        b"checked_core_transcript_b",
        &input.checked_core_transcript_b,
    );
    let replay = HiddenSourceFallbackProjectionCheckedCoreBreakInput {
        serialized_checked_core_transcript,
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        response_difference,
        checked_core_matrix_domain: input.checked_core_matrix_domain.clone(),
        checked_core_matrix_transcript_sha256: input.checked_core_matrix_transcript_sha256,
        failure: input.failure.clone(),
    };
    classify_hidden_source_fallback_checked_core_break(&replay)
}

pub fn classify_hidden_source_fallback_opening_break(
    input: &HiddenSourceFallbackProjectionHiddenBreakInput,
) -> Result<HiddenSourceFallbackProjectionBreakExport, String> {
    let decoded =
        decode_hidden_source_fallback_projection_carrier(&input.projection_carrier_bytes)?;
    if decoded != input.decoded_carrier {
        return Err("hidden-source fallback hidden export carrier replay mismatch".to_string());
    }

    match &input.failure {
        HiddenSourceFallbackProjectionHiddenFailure::OpeningProjectionMismatch {
            serialized_hidden_relation_statement,
            account_witness_opening_frame,
            pad_seed_opening_frame,
            claimed_projection_symbols,
            recomputed_projection_values,
            mismatching_lane_or_symbol,
        } => {
            if mismatching_lane_or_symbol.is_empty() {
                return Err(
                    "hidden-source fallback hidden opening mismatch label is empty".to_string(),
                );
            }
            for (index, (&claimed, &recomputed)) in claimed_projection_symbols
                .iter()
                .zip(recomputed_projection_values.iter())
                .enumerate()
            {
                if claimed >= Q {
                    return Err(format!(
                        "hidden-source fallback claimed projection coordinate {index} is noncanonical q12289 value {claimed}"
                    ));
                }
                if recomputed >= Q {
                    return Err(format!(
                        "hidden-source fallback recomputed projection coordinate {index} is noncanonical q12289 value {recomputed}"
                    ));
                }
            }
            Ok(
                HiddenSourceFallbackProjectionBreakExport::HiddenSourceOpeningBinding(
                    HiddenSourceFallbackProjectionHiddenOpeningBreakExport {
                        serialized_hidden_relation_statement: serialized_hidden_relation_statement
                            .clone(),
                        projection_carrier_56_bytes: input.projection_carrier_bytes,
                        decoded_12_q12289_lanes: decoded.lanes,
                        account_witness_opening_frame: account_witness_opening_frame.clone(),
                        pad_seed_opening_frame: pad_seed_opening_frame.clone(),
                        claimed_projection_symbols: *claimed_projection_symbols,
                        recomputed_projection_values: *recomputed_projection_values,
                        mismatching_lane_or_symbol: mismatching_lane_or_symbol.clone(),
                    },
                ),
            )
        }
        HiddenSourceFallbackProjectionHiddenFailure::AccountCommitmentSplitOpening {
            commitment_bytes,
            opening_frame_a,
            opening_frame_b,
            semantic_value_a,
            semantic_value_b,
            statement_digest,
        } => {
            if semantic_value_a == semantic_value_b {
                return Err(
                    "hidden-source fallback account split opening semantic values are equal"
                        .to_string(),
                );
            }
            Ok(
                HiddenSourceFallbackProjectionBreakExport::AccountCommitmentBinding(
                    HiddenSourceFallbackProjectionAccountCommitmentBreakExport {
                        commitment_bytes: commitment_bytes.clone(),
                        opening_frame_a: opening_frame_a.clone(),
                        opening_frame_b: opening_frame_b.clone(),
                        semantic_value_a: semantic_value_a.clone(),
                        semantic_value_b: semantic_value_b.clone(),
                        statement_digest: *statement_digest,
                    },
                ),
            )
        }
        HiddenSourceFallbackProjectionHiddenFailure::PadPrfProjectionDerivationMismatch {
            pad_seed_opening_frame,
            pad_statement_bytes,
            pad_projection_symbols,
            recomputed_pad_projection_values,
            sha256_pad_prf_domain,
        } => {
            if pad_projection_symbols.is_empty() {
                return Err(
                    "hidden-source fallback pad export has no projection symbols".to_string(),
                );
            }
            if pad_projection_symbols.len() != recomputed_pad_projection_values.len() {
                return Err(
                    "hidden-source fallback pad export symbol/value count mismatch".to_string(),
                );
            }
            if sha256_pad_prf_domain.is_empty() {
                return Err("hidden-source fallback pad PRF domain is empty".to_string());
            }
            for (index, value) in recomputed_pad_projection_values.iter().enumerate() {
                if *value >= Q {
                    return Err(format!(
                        "hidden-source fallback recomputed pad projection coordinate {index} is noncanonical q12289 value {value}"
                    ));
                }
            }
            Ok(HiddenSourceFallbackProjectionBreakExport::PadPrfOrOpening(
                HiddenSourceFallbackProjectionPadBreakExport {
                    pad_seed_opening_frame: pad_seed_opening_frame.clone(),
                    pad_statement_bytes: pad_statement_bytes.clone(),
                    projection_carrier_56_bytes: input.projection_carrier_bytes,
                    pad_projection_symbols: pad_projection_symbols.clone(),
                    recomputed_pad_projection_values: recomputed_pad_projection_values.clone(),
                    sha256_pad_prf_domain: sha256_pad_prf_domain.clone(),
                },
            ))
        }
    }
}

fn hidden_source_fallback_centered_mod_q(value: u16) -> i16 {
    if value > Q / 2 {
        value as i16 - Q as i16
    } else {
        value as i16
    }
}

pub fn reviewed_response_link_bounded_kernel_certificate()
-> HiddenSourceFallbackProjectionResponseLinkKernelCertificate {
    HiddenSourceFallbackProjectionResponseLinkKernelCertificate {
        q: Q,
        coords: REVIEWED_RESPONSE_LINK_COORDS,
        response_difference_bound: RESPONSE_LINK_BOUNDED_KERNEL_BOUND,
        matrix_transcript_sha256: RESPONSE_LINK_BOUNDED_KERNEL_MATRIX_TRANSCRIPT_SHA256.to_string(),
        canonical_basis_sha256: RESPONSE_LINK_BOUNDED_KERNEL_CANONICAL_BASIS_SHA256.to_string(),
        reduced_basis_sha256: RESPONSE_LINK_BOUNDED_KERNEL_REDUCED_BASIS_SHA256.to_string(),
        cover_ball_vector_sha256: RESPONSE_LINK_BOUNDED_KERNEL_COVER_BALL_VECTOR_SHA256.to_string(),
        manifest_payload_sha256: RESPONSE_LINK_BOUNDED_KERNEL_MANIFEST_PAYLOAD_SHA256.to_string(),
        visited_nodes: RESPONSE_LINK_BOUNDED_KERNEL_VISITED_NODES,
        visited_leaves: RESPONSE_LINK_BOUNDED_KERNEL_VISITED_LEAVES,
        nonzero_vectors_in_cover_ball: RESPONSE_LINK_BOUNDED_KERNEL_NONZERO_COVER_BALL_VECTORS,
        status: "infeasible".to_string(),
    }
}

pub fn verify_hidden_source_fallback_response_link_kernel_or_export(
    input: &HiddenSourceFallbackProjectionResponseLinkKernelReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let expected = reviewed_response_link_bounded_kernel_certificate();
    if input.certificate != expected {
        let mut break_input = input.checked_core_break_input.clone();
        break_input.failure =
            HiddenSourceFallbackProjectionCheckedCoreFailure::ResponseLinkKernelCertificateMismatch {
                certificate_id: "response_link_bounded_kernel_n32_q12289_coords_0_3_b96"
                    .to_string(),
            };
        return match classify_hidden_source_fallback_checked_core_break(&break_input) {
            Ok(export) => HiddenSourceFallbackProjectionSemanticPredicateResult::Export(export),
            Err(err) => {
                HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err)
            }
        };
    }

    let response_difference = &input.checked_core_break_input.response_difference;
    for (index, &value) in response_difference.iter().enumerate() {
        if value >= Q {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback response-link coordinate {index} is noncanonical q12289 value {value}"
                ),
            );
        }
        let centered = hidden_source_fallback_centered_mod_q(value);
        if centered.abs() > RESPONSE_LINK_BOUNDED_KERNEL_BOUND {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback response-link coordinate {index} has centered value {centered} outside +/-{RESPONSE_LINK_BOUNDED_KERNEL_BOUND}"
                ),
            );
        }
    }

    let nonzero = response_difference.iter().any(|&value| value != 0);
    let survives_response_link = REVIEWED_RESPONSE_LINK_COORDS
        .iter()
        .all(|&coord| response_difference[coord] == 0);
    if nonzero && survives_response_link {
        let mut break_input = input.checked_core_break_input.clone();
        break_input.failure =
            HiddenSourceFallbackProjectionCheckedCoreFailure::ResponseLinkKernelCertificateMismatch {
                certificate_id: "response_link_bounded_kernel_n32_q12289_coords_0_3_b96"
                    .to_string(),
            };
        return match classify_hidden_source_fallback_checked_core_break(&break_input) {
            Ok(export) => HiddenSourceFallbackProjectionSemanticPredicateResult::Export(export),
            Err(err) => {
                HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err)
            }
        };
    }

    HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(())
}

pub fn verify_hidden_source_fallback_opening_projection_or_export(
    input: &HiddenSourceFallbackProjectionOpeningProjectionReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let decoded = match decode_hidden_source_fallback_projection_carrier(
        &input.projection_carrier_bytes,
    ) {
        Ok(decoded) => decoded,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    if decoded != input.decoded_carrier {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback opening projection replay carrier mismatch".to_string(),
        );
    }

    let mut mismatch_label: Option<String> = None;
    for lane in 0..HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES {
        let claimed = input.claimed_projection_symbols[lane];
        let recomputed = input.recomputed_projection_values[lane];
        if claimed >= Q {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback claimed projection lane {lane} is noncanonical q12289 value {claimed}"
                ),
            );
        }
        if recomputed >= Q {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback recomputed projection lane {lane} is noncanonical q12289 value {recomputed}"
                ),
            );
        }
        if mismatch_label.is_none() && (decoded.lanes[lane] != claimed || claimed != recomputed) {
            mismatch_label = Some(format!(
                "lane:{lane}:symbol:{}:carrier:{}:claimed:{}:recomputed:{}",
                HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS[lane],
                decoded.lanes[lane],
                claimed,
                recomputed
            ));
        }
    }

    if let Some(mismatching_lane_or_symbol) = mismatch_label {
        let break_input = HiddenSourceFallbackProjectionHiddenBreakInput {
            projection_carrier_bytes: input.projection_carrier_bytes,
            decoded_carrier: input.decoded_carrier,
            failure: HiddenSourceFallbackProjectionHiddenFailure::OpeningProjectionMismatch {
                serialized_hidden_relation_statement: input
                    .serialized_hidden_relation_statement
                    .clone(),
                account_witness_opening_frame: input.account_witness_opening_frame.clone(),
                pad_seed_opening_frame: input.pad_seed_opening_frame.clone(),
                claimed_projection_symbols: input.claimed_projection_symbols,
                recomputed_projection_values: input.recomputed_projection_values,
                mismatching_lane_or_symbol,
            },
        };
        return match classify_hidden_source_fallback_opening_break(&break_input) {
            Ok(export) => HiddenSourceFallbackProjectionSemanticPredicateResult::Export(export),
            Err(err) => {
                HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err)
            }
        };
    }

    HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(())
}

pub fn verify_hidden_source_fallback_account_commitment_split_or_export(
    input: &HiddenSourceFallbackProjectionAccountCommitmentSplitReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let decoded = match decode_hidden_source_fallback_projection_carrier(
        &input.projection_carrier_bytes,
    ) {
        Ok(decoded) => decoded,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    if decoded != input.decoded_carrier {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback account split replay carrier mismatch".to_string(),
        );
    }
    if input.commitment_bytes.is_empty() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback account split commitment is empty".to_string(),
        );
    }
    if input.opening_frame_a.is_empty() || input.opening_frame_b.is_empty() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback account split opening frame is empty".to_string(),
        );
    }

    if input.semantic_value_a == input.semantic_value_b {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(());
    }

    let break_input = HiddenSourceFallbackProjectionHiddenBreakInput {
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        failure: HiddenSourceFallbackProjectionHiddenFailure::AccountCommitmentSplitOpening {
            commitment_bytes: input.commitment_bytes.clone(),
            opening_frame_a: input.opening_frame_a.clone(),
            opening_frame_b: input.opening_frame_b.clone(),
            semantic_value_a: input.semantic_value_a.clone(),
            semantic_value_b: input.semantic_value_b.clone(),
            statement_digest: input.statement_digest,
        },
    };
    match classify_hidden_source_fallback_opening_break(&break_input) {
        Ok(export) => HiddenSourceFallbackProjectionSemanticPredicateResult::Export(export),
        Err(err) => {
            HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err)
        }
    }
}

