pub fn verify_hidden_source_fallback_pad_prf_projection_or_export(
    input: &HiddenSourceFallbackProjectionPadPrfProjectionReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let decoded = match decode_hidden_source_fallback_projection_carrier(
        &input.projection_carrier_bytes,
    ) {
        Ok(decoded) => decoded,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    if decoded != input.decoded_carrier {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback pad PRF replay carrier mismatch".to_string(),
        );
    }
    if input.pad_projection_symbols.is_empty() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback pad PRF replay has no projection symbols".to_string(),
        );
    }
    if input.pad_projection_symbols.len() != input.recomputed_pad_projection_values.len() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback pad PRF replay symbol/value count mismatch".to_string(),
        );
    }
    if input.sha256_pad_prf_domain.is_empty() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback pad PRF domain is empty".to_string(),
        );
    }

    let mut mismatch = false;
    for (index, (symbol, &recomputed)) in input
        .pad_projection_symbols
        .iter()
        .zip(input.recomputed_pad_projection_values.iter())
        .enumerate()
    {
        if recomputed >= Q {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback pad PRF recomputed projection {index} is noncanonical q12289 value {recomputed}"
                ),
            );
        }
        let Some(lane) = HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
            .iter()
            .position(|candidate| candidate == symbol)
        else {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!("hidden-source fallback pad PRF projection symbol is unknown: {symbol}"),
            );
        };
        if !symbol.starts_with("pad_seed_projection[") {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                format!(
                    "hidden-source fallback pad PRF projection symbol is not a pad lane: {symbol}"
                ),
            );
        }
        if decoded.lanes[lane] != recomputed {
            mismatch = true;
        }
    }

    if !mismatch {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(());
    }

    let break_input = HiddenSourceFallbackProjectionHiddenBreakInput {
        projection_carrier_bytes: input.projection_carrier_bytes,
        decoded_carrier: input.decoded_carrier,
        failure: HiddenSourceFallbackProjectionHiddenFailure::PadPrfProjectionDerivationMismatch {
            pad_seed_opening_frame: input.pad_seed_opening_frame.clone(),
            pad_statement_bytes: input.pad_statement_bytes.clone(),
            pad_projection_symbols: input.pad_projection_symbols.clone(),
            recomputed_pad_projection_values: input.recomputed_pad_projection_values.clone(),
            sha256_pad_prf_domain: input.sha256_pad_prf_domain.clone(),
        },
    };
    match classify_hidden_source_fallback_opening_break(&break_input) {
        Ok(export) => HiddenSourceFallbackProjectionSemanticPredicateResult::Export(export),
        Err(err) => {
            HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err)
        }
    }
}

fn hidden_source_fallback_pad_projection_block_coord(symbol: &str) -> Option<(usize, usize)> {
    match symbol {
        "pad_seed_projection[1,0]" => Some((1, 0)),
        "pad_seed_projection[2,1]" => Some((2, 1)),
        "pad_seed_projection[6,1]" => Some((6, 1)),
        "pad_seed_projection[7,0]" => Some((7, 0)),
        "pad_seed_projection[11,0]" => Some((11, 0)),
        "pad_seed_projection[12,1]" => Some((12, 1)),
        _ => None,
    }
}

fn hidden_source_fallback_account_projection_block_coord(symbol: &str) -> Option<(usize, usize)> {
    match symbol {
        "account_witness_projection[0,1]" => Some((0, 1)),
        "account_witness_projection[1,0]" => Some((1, 0)),
        "account_witness_projection[4,1]" => Some((4, 1)),
        "account_witness_projection[7,0]" => Some((7, 0)),
        "account_witness_projection[10,1]" => Some((10, 1)),
        "account_witness_projection[13,0]" => Some((13, 0)),
        _ => None,
    }
}

fn hidden_source_fallback_mul_mod_q(left: u16, right: u16) -> u16 {
    ((left as u32 * right as u32) % Q as u32) as u16
}

pub fn hidden_source_fallback_account_witness_opening_frame_bytes() -> usize {
    HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_DOMAIN
        .as_bytes()
        .len()
        + HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_PROFILE
            .as_bytes()
            .len()
        + HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES * 2
}

pub fn encode_hidden_source_fallback_account_witness_opening_frame(
    opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
) -> Result<Vec<u8>, String> {
    let mut frame =
        Vec::with_capacity(hidden_source_fallback_account_witness_opening_frame_bytes());
    frame.extend_from_slice(HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_DOMAIN.as_bytes());
    frame.extend_from_slice(HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_PROFILE.as_bytes());
    for (index, value) in opening.selected_source_values.iter().enumerate() {
        if *value >= Q {
            return Err(format!(
                "hidden-source fallback account opening frame coordinate {index} is noncanonical q12289 value {value}"
            ));
        }
        frame.extend_from_slice(&value.to_le_bytes());
    }
    Ok(frame)
}

pub fn decode_hidden_source_fallback_account_witness_opening_frame(
    frame: &[u8],
) -> Result<HiddenSourceFallbackProjectionAccountWitnessOpening, String> {
    let expected = hidden_source_fallback_account_witness_opening_frame_bytes();
    if frame.len() != expected {
        return Err(format!(
            "hidden-source fallback account opening frame has {} bytes, expected {expected}",
            frame.len()
        ));
    }

    let domain = HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_DOMAIN.as_bytes();
    if &frame[..domain.len()] != domain {
        return Err("hidden-source fallback account opening frame domain mismatch".to_string());
    }
    let profile = HIDDEN_SOURCE_FALLBACK_ACCOUNT_OPENING_FRAME_PROFILE.as_bytes();
    let profile_start = domain.len();
    let profile_end = profile_start + profile.len();
    if &frame[profile_start..profile_end] != profile {
        return Err("hidden-source fallback account opening frame profile mismatch".to_string());
    }

    let mut selected_source_values = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    let mut offset = profile_end;
    for (index, value) in selected_source_values.iter_mut().enumerate() {
        let decoded = u16::from_le_bytes([frame[offset], frame[offset + 1]]);
        if decoded >= Q {
            return Err(format!(
                "hidden-source fallback account opening frame coordinate {index} is noncanonical q12289 value {decoded}"
            ));
        }
        *value = decoded;
        offset += 2;
    }
    Ok(HiddenSourceFallbackProjectionAccountWitnessOpening {
        selected_source_values,
    })
}

pub fn hidden_source_fallback_account_witness_opening_semantic_value(
    opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
) -> Result<Vec<u8>, String> {
    let mut value = Vec::with_capacity(HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES * 2);
    for (index, coordinate) in opening.selected_source_values.iter().enumerate() {
        if *coordinate >= Q {
            return Err(format!(
                "hidden-source fallback account opening semantic coordinate {index} is noncanonical q12289 value {coordinate}"
            ));
        }
        value.extend_from_slice(&coordinate.to_le_bytes());
    }
    Ok(value)
}

pub fn hidden_source_fallback_account_projection_values_from_opening(
    opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
) -> Result<(Vec<String>, Vec<u16>), String> {
    let mut symbols = Vec::new();
    let mut values = Vec::new();
    let mut selected_index = 0_usize;
    for (lane, symbol) in HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
        .iter()
        .enumerate()
    {
        if !symbol.starts_with("account_witness_projection[") {
            continue;
        }
        let Some((block, coord)) = hidden_source_fallback_account_projection_block_coord(symbol)
        else {
            return Err(format!(
                "hidden-source fallback account projection symbol is unknown: {symbol}"
            ));
        };
        if block >= GROUPS || coord >= LOCAL_FREE {
            return Err(format!(
                "hidden-source fallback account projection symbol is out of range: {symbol}"
            ));
        }
        let source_value = opening.selected_source_values[selected_index];
        if source_value >= Q {
            return Err(format!(
                "hidden-source fallback account projection source value {selected_index} is noncanonical q12289 value {source_value}"
            ));
        }
        symbols.push((*symbol).to_string());
        values.push(hidden_source_fallback_mul_mod_q(
            HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_COEFFICIENTS[lane],
            source_value,
        ));
        selected_index += 1;
    }
    if selected_index != HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        return Err("hidden-source fallback account projection lane count mismatch".to_string());
    }
    Ok((symbols, values))
}

pub fn hidden_source_fallback_expanded_account_opening_commitment(
    opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
) -> Result<[u8; DIGEST_BYTES], String> {
    let mut hasher = Sha256::new();
    hasher.update(HIDDEN_SOURCE_FALLBACK_EXPANDED_OPENING_COMMITMENT_DOMAIN.as_bytes());
    hasher.update((Q as u32).to_le_bytes());
    hasher.update((GROUPS as u32).to_le_bytes());
    hasher.update((LOCAL_FREE as u32).to_le_bytes());
    hasher.update((HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES as u32).to_le_bytes());

    let mut selected_index = 0_usize;
    for (lane, symbol) in HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS
        .iter()
        .enumerate()
    {
        if !symbol.starts_with("account_witness_projection[") {
            continue;
        }
        let value = opening.selected_source_values[selected_index];
        if value >= Q {
            return Err(format!(
                "hidden-source fallback expanded account opening coordinate {selected_index} is noncanonical q12289 value {value}"
            ));
        }
        hasher.update((lane as u32).to_le_bytes());
        hasher.update((*symbol).as_bytes());
        hasher.update([0_u8]);
        hasher.update(HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_COEFFICIENTS[lane].to_le_bytes());
        hasher.update(value.to_le_bytes());
        selected_index += 1;
    }
    if selected_index != HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        return Err(
            "hidden-source fallback expanded account opening lane count mismatch".to_string(),
        );
    }

    Ok(hasher.finalize().into())
}

pub fn verify_hidden_source_fallback_expanded_opening_commitment(
    input: &HiddenSourceFallbackProjectionExpandedOpeningCommitmentReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    if input.account_witness_opening_frame.is_empty() {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback expanded account opening frame is empty".to_string(),
        );
    }
    let recomputed = match hidden_source_fallback_expanded_account_opening_commitment(
        &input.account_witness_opening,
    ) {
        Ok(commitment) => commitment,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    if recomputed != input.expected_expanded_opening_commitment {
        return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
            "hidden-source fallback expanded account opening commitment mismatch".to_string(),
        );
    }
    HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(())
}

pub fn verify_hidden_source_fallback_expanded_opening_frame_commitment(
    input: &HiddenSourceFallbackProjectionExpandedOpeningFrameReplayInput,
) -> HiddenSourceFallbackProjectionSemanticPredicateResult<()> {
    let account_witness_opening = match decode_hidden_source_fallback_account_witness_opening_frame(
        &input.account_witness_opening_frame,
    ) {
        Ok(opening) => opening,
        Err(err) => {
            return HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(
                err,
            );
        }
    };
    let replay = HiddenSourceFallbackProjectionExpandedOpeningCommitmentReplayInput {
        expected_expanded_opening_commitment: input.expected_expanded_opening_commitment,
        account_witness_opening_frame: input.account_witness_opening_frame.clone(),
        account_witness_opening,
    };
    verify_hidden_source_fallback_expanded_opening_commitment(&replay)
}

pub fn verify_hidden_source_fallback_expanded_opening_state_slot(
    slot: &ProductionReviewedFq12StateAssistedAccountSlot,
    account_witness_opening_frame: &[u8],
    account_witness_opening: &HiddenSourceFallbackProjectionAccountWitnessOpening,
) -> Result<[u8; DIGEST_BYTES], String> {
    // Archival direct-commitment helper for older projection wiring. The selected
    // deployment path uses verify_reviewed_fq12_state_assisted_account_witness_projection_opening.
    slot.commitment().validate()?;
    if !slot.is_unused() {
        return Err("hidden-source fallback projection slot is already consumed".to_string());
    }
    let expected_expanded_opening_commitment = slot.hidden_source_opening_commitment();
    let replay = HiddenSourceFallbackProjectionExpandedOpeningCommitmentReplayInput {
        expected_expanded_opening_commitment,
        account_witness_opening_frame: account_witness_opening_frame.to_vec(),
        account_witness_opening: *account_witness_opening,
    };
    match verify_hidden_source_fallback_expanded_opening_commitment(&replay) {
        HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(()) => {
            Ok(expected_expanded_opening_commitment)
        }
        HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err) => {
            Err(err)
        }
        HiddenSourceFallbackProjectionSemanticPredicateResult::Export(_) => Err(
            "hidden-source fallback expanded opening state-slot check unexpectedly exported a break"
                .to_string(),
        ),
    }
}

