pub fn reviewed_fq12_account_witness_projection_opening_digest(
    account_witness_opening_frame: &[u8],
) -> Result<[u8; DIGEST_BYTES], String> {
    let account_witness_opening =
        decode_hidden_source_fallback_account_witness_opening_frame(account_witness_opening_frame)?;
    let semantic_value =
        hidden_source_fallback_account_witness_opening_semantic_value(&account_witness_opening)?;
    let expanded_opening_commitment =
        hidden_source_fallback_expanded_account_opening_commitment(&account_witness_opening)?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_ACCOUNT_WITNESS_PROJECTION_OPENING_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(
        &mut frame,
        b"projection_lanes",
        HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES as u64,
    );
    append_frame(
        &mut frame,
        b"account_witness_opening_frame",
        account_witness_opening_frame,
    );
    append_frame(&mut frame, b"semantic_value", &semantic_value);
    append_frame(
        &mut frame,
        b"expanded_opening_commitment",
        &expanded_opening_commitment,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn reviewed_fq12_packed_witness_state18_projection_opening(
    witness_commitment: &[u8; DIGEST_BYTES],
) -> Result<HiddenSourceFallbackProjectionAccountWitnessOpening, String> {
    let residues = unpack_reviewed_fq12_packed_witness_state18(witness_commitment)?;
    let mut selected_source_values = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for (idx, value) in selected_source_values.iter_mut().enumerate() {
        *value = residues[REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET + idx];
    }
    Ok(HiddenSourceFallbackProjectionAccountWitnessOpening {
        selected_source_values,
    })
}

pub fn reviewed_fq12_packed_witness_state18_projection_masks(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    slot_id: u64,
) -> [u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES] {
    let mut seed = Vec::with_capacity(REVIEWED_FQ12_PAD_SEED_BYTES + 8);
    seed.extend_from_slice(pad_seed);
    seed.extend_from_slice(&slot_id.to_le_bytes());
    let mut masks = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for (idx, mask) in masks.iter_mut().enumerate() {
        *mask = uniform_mod_from_hash(
            REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_MASK_DOMAIN.as_bytes(),
            &seed,
            slot_id,
            idx as u64,
            Q,
        );
    }
    masks
}

#[cfg(test)]
fn reviewed_fq12_packed_witness_state18_projection_mask_prf_input_frame(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    slot_id: u64,
    lane: usize,
    counter: u32,
) -> Result<Vec<u8>, String> {
    if lane >= HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        return Err(format!(
            "reviewed Fq12 packed witness state18 projection mask lane {lane} is out of range"
        ));
    }
    let mut seed = Vec::with_capacity(REVIEWED_FQ12_PAD_SEED_BYTES + 8);
    seed.extend_from_slice(pad_seed);
    seed.extend_from_slice(&slot_id.to_le_bytes());

    let mut frame = Vec::with_capacity(
        REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_MASK_DOMAIN.len() + seed.len() + 8 + 8 + 4,
    );
    frame.extend_from_slice(REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_MASK_DOMAIN.as_bytes());
    frame.extend_from_slice(&seed);
    frame.extend_from_slice(&slot_id.to_le_bytes());
    frame.extend_from_slice(&(lane as u64).to_le_bytes());
    frame.extend_from_slice(&counter.to_le_bytes());
    Ok(frame)
}

pub fn reviewed_fq12_pack_masked_witness_state18_from_parts(
    syndrome: &[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
    account_projection: &[u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    slot_id: u64,
) -> Result<[u8; DIGEST_BYTES], String> {
    let masks = reviewed_fq12_packed_witness_state18_projection_masks(pad_seed, slot_id);
    let mut masked_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for idx in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        if account_projection[idx] >= Q {
            return Err(format!(
                "reviewed Fq12 masked witness state18 projection residue {idx} is non-canonical: {}",
                account_projection[idx]
            ));
        }
        masked_projection[idx] =
            ((account_projection[idx] as u32 + masks[idx] as u32) % Q as u32) as u16;
    }
    pack_reviewed_fq12_packed_witness_state18_from_parts(syndrome, &masked_projection)
}

pub fn reviewed_fq12_masked_packed_witness_state18_projection_opening(
    witness_commitment: &[u8; DIGEST_BYTES],
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    slot_id: u64,
) -> Result<HiddenSourceFallbackProjectionAccountWitnessOpening, String> {
    let residues = unpack_reviewed_fq12_packed_witness_state18(witness_commitment)?;
    let masks = reviewed_fq12_packed_witness_state18_projection_masks(pad_seed, slot_id);
    let mut selected_source_values = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for idx in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        let masked = residues[REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET + idx];
        selected_source_values[idx] =
            ((masked as u32 + Q as u32 - masks[idx] as u32) % Q as u32) as u16;
    }
    Ok(HiddenSourceFallbackProjectionAccountWitnessOpening {
        selected_source_values,
    })
}

pub fn reviewed_fq12_masked_state18_packed_witness_opening_frame(
    opening: &ProductionReviewedFq12MaskedState18PackedWitnessOpening,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_MASKED_STATE18_PACKED_WITNESS_OPENING_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(
        &mut frame,
        b"checked_core_rows",
        REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS as u64,
    );
    append_u64(
        &mut frame,
        b"projection_lanes",
        HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES as u64,
    );
    append_u64(&mut frame, b"slot_id", opening.slot_id);
    append_frame(
        &mut frame,
        b"witness_commitment",
        &opening.witness_commitment,
    );
    for (idx, value) in opening.witness_syndrome.iter().enumerate() {
        append_u64(&mut frame, b"syndrome_index", idx as u64);
        append_frame(&mut frame, b"syndrome_residue", &value.to_le_bytes());
    }
    for idx in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        append_u64(&mut frame, b"projection_lane", idx as u64);
        append_frame(
            &mut frame,
            b"masked_projection_residue",
            &opening.masked_projection[idx].to_le_bytes(),
        );
        append_frame(
            &mut frame,
            b"projection_mask",
            &opening.projection_masks[idx].to_le_bytes(),
        );
        append_frame(
            &mut frame,
            b"account_projection_residue",
            &opening.account_projection[idx].to_le_bytes(),
        );
    }
    append_frame(
        &mut frame,
        b"repacked_witness_commitment",
        &opening.repacked_witness_commitment,
    );
    frame
}

pub fn reviewed_fq12_masked_state18_packed_witness_opening_digest(
    opening: &ProductionReviewedFq12MaskedState18PackedWitnessOpening,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_masked_state18_packed_witness_opening_frame(
        opening,
    ))
    .into()
}

pub fn reviewed_fq12_masked_state18_packed_witness_opening(
    witness_commitment: &[u8; DIGEST_BYTES],
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    slot_id: u64,
) -> Result<ProductionReviewedFq12MaskedState18PackedWitnessOpening, String> {
    let residues = unpack_reviewed_fq12_packed_witness_state18(witness_commitment)?;
    let mut witness_syndrome = [0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS];
    witness_syndrome.copy_from_slice(&residues[..REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS]);

    let mut masked_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    masked_projection.copy_from_slice(
        &residues[REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET
            ..REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET
                + HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
    );
    let projection_masks = reviewed_fq12_packed_witness_state18_projection_masks(pad_seed, slot_id);
    let mut account_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for idx in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        account_projection[idx] = ((masked_projection[idx] as u32 + Q as u32
            - projection_masks[idx] as u32)
            % Q as u32) as u16;
    }
    let repacked_witness_commitment = reviewed_fq12_pack_masked_witness_state18_from_parts(
        &witness_syndrome,
        &account_projection,
        pad_seed,
        slot_id,
    )?;
    if &repacked_witness_commitment != witness_commitment {
        return Err(
            "reviewed Fq12 masked state18 packed witness opening repack mismatch".to_string(),
        );
    }
    let mut opening = ProductionReviewedFq12MaskedState18PackedWitnessOpening {
        digest: [0_u8; DIGEST_BYTES],
        slot_id,
        witness_commitment: *witness_commitment,
        witness_syndrome,
        masked_projection,
        projection_masks,
        account_projection,
        repacked_witness_commitment,
    };
    opening.digest = reviewed_fq12_masked_state18_packed_witness_opening_digest(&opening);
    Ok(opening)
}

pub fn validate_reviewed_fq12_masked_state18_packed_witness_opening(
    opening: &ProductionReviewedFq12MaskedState18PackedWitnessOpening,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<(), String> {
    let expected = reviewed_fq12_masked_state18_packed_witness_opening(
        &opening.witness_commitment,
        pad_seed,
        opening.slot_id,
    )?;
    if &expected != opening {
        return Err(
            "reviewed Fq12 masked state18 packed witness opening fields mismatch".to_string(),
        );
    }
    if reviewed_fq12_masked_state18_packed_witness_opening_digest(opening) != opening.digest {
        return Err(
            "reviewed Fq12 masked state18 packed witness opening digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn verify_reviewed_fq12_state_assisted_account_witness_projection_opening(
    slot: &ProductionReviewedFq12StateAssistedAccountSlot,
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    account_witness_opening_frame: &[u8],
) -> Result<[u8; DIGEST_BYTES], String> {
    let opening_commitment = verify_reviewed_fq12_state_assisted_slot_opening(slot, opening)?;
    if reviewed_fq12_hidden_source_statement_digest(statement) != statement.digest {
        return Err(
            "reviewed Fq12 account witness projection opening statement digest mismatch"
                .to_string(),
        );
    }
    if statement.slot_id as u64 != opening.slot_id {
        return Err(
            "reviewed Fq12 account witness projection opening slot id mismatch".to_string(),
        );
    }
    if statement.witness_commitment != opening.account_witness_commitment {
        return Err(
            "reviewed Fq12 account witness projection opening statement commitment mismatch"
                .to_string(),
        );
    }
    let actual_opening_digest =
        reviewed_fq12_account_witness_projection_opening_digest(account_witness_opening_frame)?;
    if actual_opening_digest != opening.witness_opening_digest {
        return Err("reviewed Fq12 account witness projection opening digest mismatch".to_string());
    }
    Ok(opening_commitment)
}

pub fn verify_reviewed_fq12_state_assisted_packed_witness_state18_projection_opening(
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
) -> Result<Vec<u8>, String> {
    if reviewed_fq12_hidden_source_statement_digest(statement) != statement.digest {
        return Err(
            "reviewed Fq12 packed witness state18 projection opening statement digest mismatch"
                .to_string(),
        );
    }
    if statement.slot_id as u64 != opening.slot_id {
        return Err(
            "reviewed Fq12 packed witness state18 projection opening slot id mismatch".to_string(),
        );
    }
    if statement.witness_commitment != opening.account_witness_commitment {
        return Err(
            "reviewed Fq12 packed witness state18 projection opening statement commitment mismatch"
                .to_string(),
        );
    }
    let account_witness_opening = reviewed_fq12_packed_witness_state18_projection_opening(
        &opening.account_witness_commitment,
    )?;
    let account_witness_opening_frame =
        encode_hidden_source_fallback_account_witness_opening_frame(&account_witness_opening)?;
    let actual_opening_digest =
        reviewed_fq12_account_witness_projection_opening_digest(&account_witness_opening_frame)?;
    if actual_opening_digest != opening.witness_opening_digest {
        return Err(
            "reviewed Fq12 packed witness state18 projection opening digest mismatch".to_string(),
        );
    }
    Ok(account_witness_opening_frame)
}

