pub fn reviewed_fq12_state_assisted_projection_carrier_binding(
    opening_commitment: &[u8; DIGEST_BYTES],
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    projection_lanes: &[u16; HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES],
) -> Result<
    (
        [u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES],
        [u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES],
    ),
    String,
> {
    let statement_digest = reviewed_fq12_hidden_source_statement_digest(statement);
    if statement_digest != statement.digest {
        return Err(
            "reviewed Fq12 projection carrier binding statement digest mismatch".to_string(),
        );
    }
    if statement.slot_id as u64 != opening.slot_id {
        return Err("reviewed Fq12 projection carrier binding slot id mismatch".to_string());
    }
    if statement.witness_commitment != opening.account_witness_commitment {
        return Err(
            "reviewed Fq12 projection carrier binding witness commitment mismatch".to_string(),
        );
    }
    if statement.randomizer_commitment != opening.account_randomizer_commitment {
        return Err(
            "reviewed Fq12 projection carrier binding randomizer commitment mismatch".to_string(),
        );
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_STATE_ASSISTED_PROJECTION_CARRIER_BINDING_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(
        &mut frame,
        b"projection_lanes",
        HIDDEN_SOURCE_FALLBACK_PROJECTION_LANES as u64,
    );
    append_frame(&mut frame, b"opening_commitment", opening_commitment);
    append_frame(
        &mut frame,
        b"carrier_handle_secret_digest",
        &opening.carrier_handle_secret_digest,
    );
    append_frame(&mut frame, b"statement_digest", &statement_digest);
    append_frame(&mut frame, b"signature_digest", &statement.signature_digest);
    append_frame(
        &mut frame,
        b"public_key_digest",
        &statement.public_key_digest,
    );
    append_frame(&mut frame, b"message_digest", &statement.message_digest);
    append_u64(&mut frame, b"slot_id", statement.slot_id as u64);
    for (lane, &value) in projection_lanes.iter().enumerate() {
        if value >= Q {
            return Err(format!(
                "reviewed Fq12 projection carrier binding lane {lane} is noncanonical q12289 value {value}"
            ));
        }
        append_u64(&mut frame, b"lane_index", lane as u64);
        append_frame(
            &mut frame,
            b"lane_symbol",
            HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_SYMBOLS[lane].as_bytes(),
        );
        append_frame(
            &mut frame,
            b"lane_coefficient",
            &HIDDEN_SOURCE_FALLBACK_PROJECTION_LANE_COEFFICIENTS[lane].to_le_bytes(),
        );
        append_frame(&mut frame, b"lane_value", &value.to_le_bytes());
    }
    let digest = Sha256::digest(frame);
    let mut check_bytes = [0_u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES];
    check_bytes.copy_from_slice(&digest[..HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES]);
    let mut transcript_binding = [0_u8; HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES];
    transcript_binding.copy_from_slice(
        &digest[HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES
            ..HIDDEN_SOURCE_FALLBACK_PROJECTION_CHECK_BYTES
                + HIDDEN_SOURCE_FALLBACK_PROJECTION_TRANSCRIPT_BINDING_BYTES],
    );
    Ok((check_bytes, transcript_binding))
}

pub fn verify_reviewed_fq12_state_assisted_projection_carrier_tuple(
    slot: &ProductionReviewedFq12StateAssistedAccountSlot,
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    account_witness_opening_frame: &[u8],
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    carrier: &HiddenSourceFallbackProjectionCarrier,
) -> Result<[u8; DIGEST_BYTES], String> {
    let opening_commitment =
        verify_reviewed_fq12_state_assisted_account_witness_projection_opening(
            slot,
            opening,
            statement,
            account_witness_opening_frame,
        )?;
    let pad_opening_commitment = verify_reviewed_fq12_state_assisted_pad_seed_opening(
        slot,
        opening,
        &statement.pad_opening_statement,
        pad_seed,
    )?;
    if pad_opening_commitment != opening_commitment {
        return Err("reviewed Fq12 state-assisted tuple opening commitment mismatch".to_string());
    }
    let decoded_carrier = carrier.decode()?;
    let pad_seed_opening_frame = reviewed_fq12_pad_seed_opening_digest(pad_seed).to_vec();
    let hidden_material_input = HiddenSourceFallbackProjectionHiddenMaterialFrameReplayInput {
        projection_carrier_bytes: *carrier.as_bytes(),
        decoded_carrier,
        serialized_hidden_relation_statement: reviewed_fq12_hidden_source_statement_frame(
            statement,
        ),
        account_witness_opening_frame: account_witness_opening_frame.to_vec(),
        pad_seed_opening_frame,
        pad_seed: *pad_seed,
    };
    match verify_hidden_source_fallback_hidden_material_frame_projection_or_export(
        &hidden_material_input,
    ) {
        HiddenSourceFallbackProjectionSemanticPredicateResult::Accept(()) => {}
        HiddenSourceFallbackProjectionSemanticPredicateResult::RejectBeforeAcceptance(err) => {
            return Err(err);
        }
        HiddenSourceFallbackProjectionSemanticPredicateResult::Export(_) => {
            return Err(
                "reviewed Fq12 state-assisted projection carrier tuple exported a hidden-material break"
                    .to_string(),
            );
        }
    }
    let (expected_check_bytes, expected_transcript_binding) =
        reviewed_fq12_state_assisted_projection_carrier_binding(
            &opening_commitment,
            opening,
            statement,
            &decoded_carrier.lanes,
        )?;
    if decoded_carrier.check_bytes != expected_check_bytes {
        return Err("reviewed Fq12 projection carrier check bytes mismatch".to_string());
    }
    if decoded_carrier.transcript_binding != expected_transcript_binding {
        return Err("reviewed Fq12 projection carrier transcript binding mismatch".to_string());
    }
    Ok(opening_commitment)
}

