pub const PRODUCTION_DEPLOYMENT_REQUIRED_CALLBACK_BOUNDARIES: &[&str] = &[
    "sign_with_account_binding_sanitized",
    "sign_with_secret_key_sanitized",
    "verify_with_account_binding_sanitized",
    "verify_reviewed_fq12_account_carried_hidden_source_proof_with_transcript",
    "sign_reserved_and_consume_sanitized",
    "verify_and_consume_sanitized",
    "verify_consume_and_record_spent_sanitized",
    "verify_consume_record_and_save_sanitized",
];

pub fn production_callback_boundary_classification(
    boundary: &str,
) -> Option<&'static ProductionCallbackBoundaryClassification> {
    PRODUCTION_CALLBACK_BOUNDARIES
        .iter()
        .find(|classification| classification.boundary == boundary)
}

pub fn require_deployment_callback_boundaries<'a>(
    boundaries: impl IntoIterator<Item = &'a str>,
) -> Result<(), String> {
    for boundary in boundaries {
        let classification = production_callback_boundary_classification(boundary)
            .ok_or_else(|| format!("unknown callback boundary: {boundary}"))?;
        if !classification.deployment_facing {
            return Err(format!(
                "callback boundary {boundary} is diagnostic-only and not deployment-facing"
            ));
        }
        if classification.error_policy != ProductionCallbackErrorPolicy::SanitizedFixedPublicErrors
        {
            return Err(format!(
                "callback boundary {boundary} does not use fixed public errors"
            ));
        }
    }
    Ok(())
}

pub fn verify_default_deployment_callback_boundaries() -> Result<(), String> {
    require_deployment_callback_boundaries(
        PRODUCTION_DEPLOYMENT_REQUIRED_CALLBACK_BOUNDARIES
            .iter()
            .copied(),
    )
}

