pub fn production_deployment_preflight() -> ProductionDeploymentPreflight {
    let callback_boundaries_ok = verify_default_deployment_callback_boundaries().is_ok();
    let reviewed_target_codec_present = REVIEWED_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES
        == REVIEWED_TARGET_TRANSACTION_SIGNATURE_BYTES
        && REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES == 37;
    let reviewed_target_account_binding_present = reviewed_target_codec_present;
    let reviewed_target_challenge_binding_present = reviewed_target_account_binding_present;
    let reviewed_fq12_checked_core_present =
        REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES == 258
            && REVIEWED_FQ12_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES == 39;
    let reviewed_fq12_fallback_projection_codec_present =
        REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_FALLBACK_PROJECTION_BYTES == 314
            && HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES == 56;
    let reviewed_fq12_hidden_source_proof_callback_present = true;
    let reviewed_fq12_hidden_source_proof_transcript_callback_present = true;
    let hidden_source_semantics_bridge_audit =
        path2_reviewed_fq12_hidden_source_semantics_bridge_audit();
    let reviewed_fq12_hidden_source_semantics_bridge_audit_present =
        validate_path2_reviewed_fq12_hidden_source_semantics_bridge_audit(
            &hidden_source_semantics_bridge_audit,
        )
        .is_ok();
    let reviewed_fq12_hidden_source_semantics_bridge_complete =
        reviewed_fq12_hidden_source_semantics_bridge_audit_present
            && hidden_source_semantics_bridge_audit.semantics_bridge_complete;
    let reviewed_fq12_hidden_source_readiness_report_present = true;
    let reviewed_fq12_hidden_source_readiness_verdict_present = true;
    let reviewed_fq12_hidden_source_deployability_assertion_present = true;
    let reviewed_fq12_active_lane_relation_certificate_present = true;
    let reviewed_fq12_account_witness_projection_opening_binding_present = true;
    let reviewed_fq12_direct_expanded_opening_path_archived =
        HIDDEN_SOURCE_FALLBACK_DIRECT_EXPANDED_OPENING_DEPLOYMENT_STATUS
            .starts_with("archived_non_deployment_path:");
    let reviewed_fq12_pad_opening_witness_binding_present = true;
    let reviewed_fq12_state_assisted_projection_carrier_tuple_binding_present = true;
    let reviewed_fq12_state_assisted_pad_seed_digest_account_invariant_present = true;
    let reviewed_fq12_selected_projection_spent_pad_seed_digest_invariant_present = true;
    let reviewed_fq12_target_chain_pad_seed_digest_commit_validation_present = true;
    let reviewed_fq12_fail_closed_deployment_verifier_present = true;
    let reviewed_fq12_state_assisted_masked_projection_candidate_verifier_present = true;
    let reviewed_fq12_deployment_verifier_present = false;
    let executable_matches_reviewed_target = LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES
        == REVIEWED_TARGET_TRANSACTION_SIGNATURE_BYTES;
    let mut blockers = Vec::new();
    if !callback_boundaries_ok {
        blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_CALLBACK_BOUNDARIES);
    }
    if !reviewed_fq12_state_assisted_masked_projection_candidate_verifier_present {
        blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_SELECTED_VERIFIER);
    }
    if !reviewed_fq12_pad_opening_witness_binding_present {
        blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_PAD_OPENING_BINDING);
    }
    blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_HIDDEN_SOURCE_PROOF_SEMANTICS);
    blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_CONSTANT_TIME);
    blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_STORAGE);
    blockers.push(PRODUCTION_DEPLOYMENT_BLOCKER_EXTERNAL_REVIEW);
    ProductionDeploymentPreflight {
        callback_boundaries_ok,
        executable_signature_bytes: LINEAR_SIGMA_TARGET_TRANSACTION_SIGNATURE_BYTES,
        reviewed_target_signature_bytes: REVIEWED_TARGET_TRANSACTION_SIGNATURE_BYTES,
        reviewed_fq12_fallback_signature_bytes:
            REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES,
        reviewed_fq12_hidden_source_proof_bytes: REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES,
        reviewed_fq12_with_hidden_source_proof_bytes:
            REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_HIDDEN_SOURCE_PROOF_BYTES,
        reviewed_fq12_fallback_projection_carrier_bytes:
            HIDDEN_SOURCE_FALLBACK_PROJECTION_CARRIER_BYTES,
        reviewed_fq12_with_fallback_projection_bytes:
            REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_FALLBACK_PROJECTION_BYTES,
        reviewed_account_link_bytes: REVIEWED_ACCOUNT_LINK_BYTES,
        reviewed_target_codec_present,
        reviewed_target_account_binding_present,
        reviewed_target_challenge_binding_present,
        reviewed_fq12_checked_core_present,
        reviewed_fq12_fallback_projection_codec_present,
        reviewed_fq12_hidden_source_proof_callback_present,
        reviewed_fq12_hidden_source_proof_transcript_callback_present,
        reviewed_fq12_hidden_source_semantics_bridge_audit_present,
        reviewed_fq12_hidden_source_semantics_bridge_complete,
        reviewed_fq12_hidden_source_readiness_report_present,
        reviewed_fq12_hidden_source_readiness_verdict_present,
        reviewed_fq12_hidden_source_deployability_assertion_present,
        reviewed_fq12_active_lane_relation_certificate_present,
        reviewed_fq12_account_witness_projection_opening_binding_present,
        reviewed_fq12_direct_expanded_opening_path_archived,
        reviewed_fq12_pad_opening_witness_binding_present,
        reviewed_fq12_state_assisted_projection_carrier_tuple_binding_present,
        reviewed_fq12_state_assisted_pad_seed_digest_account_invariant_present,
        reviewed_fq12_selected_projection_spent_pad_seed_digest_invariant_present,
        reviewed_fq12_target_chain_pad_seed_digest_commit_validation_present,
        reviewed_fq12_fail_closed_deployment_verifier_present,
        reviewed_fq12_state_assisted_masked_projection_candidate_verifier_present,
        reviewed_fq12_deployment_verifier_present,
        executable_matches_reviewed_target,
        deployment_ready: blockers.is_empty(),
        blockers,
    }
}

pub fn production_deployment_preflight_report() -> ProductionDeploymentPreflightReport {
    let preflight = production_deployment_preflight();
    let mut report = ProductionDeploymentPreflightReport {
        digest: [0_u8; DIGEST_BYTES],
        preflight,
    };
    report.digest = production_deployment_preflight_report_digest(&report);
    report
}

pub fn production_deployment_preflight_report_digest(
    report: &ProductionDeploymentPreflightReport,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_report_frame(report)).into()
}

pub fn validate_production_deployment_preflight_report(
    report: &ProductionDeploymentPreflightReport,
) -> Result<(), String> {
    let expected = production_deployment_preflight_report();
    if expected != *report {
        return Err("production deployment preflight report mismatch".to_string());
    }
    if production_deployment_preflight_report_digest(report) != report.digest {
        return Err("production deployment preflight report digest mismatch".to_string());
    }
    Ok(())
}

pub fn production_deployment_preflight_blockers(
    report: &ProductionDeploymentPreflightReport,
) -> Result<Vec<ProductionDeploymentPreflightBlocker>, String> {
    if production_deployment_preflight_report_digest(report) != report.digest {
        return Err("production deployment preflight report digest mismatch".to_string());
    }
    let mut rows = Vec::with_capacity(report.preflight.blockers.len());
    for (index, blocker) in report.preflight.blockers.iter().copied().enumerate() {
        let mut row = ProductionDeploymentPreflightBlocker {
            digest: [0_u8; DIGEST_BYTES],
            preflight_report_digest: report.digest,
            index,
            blocker,
        };
        row.digest = production_deployment_preflight_blocker_digest(&row);
        rows.push(row);
    }
    Ok(rows)
}

pub fn production_deployment_preflight_blocker_digest(
    blocker: &ProductionDeploymentPreflightBlocker,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_blocker_frame(blocker)).into()
}

pub fn validate_production_deployment_preflight_blocker(
    report: &ProductionDeploymentPreflightReport,
    blocker: &ProductionDeploymentPreflightBlocker,
) -> Result<(), String> {
    if production_deployment_preflight_report_digest(report) != report.digest {
        return Err("production deployment preflight report digest mismatch".to_string());
    }
    if blocker.index >= report.preflight.blockers.len() {
        return Err("production deployment preflight blocker index out of range".to_string());
    }
    if blocker.preflight_report_digest != report.digest {
        return Err("production deployment preflight blocker report digest mismatch".to_string());
    }
    if blocker.blocker != report.preflight.blockers[blocker.index] {
        return Err("production deployment preflight blocker string mismatch".to_string());
    }
    if production_deployment_preflight_blocker_digest(blocker) != blocker.digest {
        return Err("production deployment preflight blocker digest mismatch".to_string());
    }
    Ok(())
}

pub fn production_deployment_preflight_blocker_report(
    report: &ProductionDeploymentPreflightReport,
) -> Result<ProductionDeploymentPreflightBlockerReport, String> {
    let blockers = production_deployment_preflight_blockers(report)?;
    let mut blocker_report = ProductionDeploymentPreflightBlockerReport {
        digest: [0_u8; DIGEST_BYTES],
        preflight_report_digest: report.digest,
        blocker_count: blockers.len(),
        blocker_digests: blockers.iter().map(|blocker| blocker.digest).collect(),
    };
    blocker_report.digest = production_deployment_preflight_blocker_report_digest(&blocker_report);
    Ok(blocker_report)
}

pub fn production_deployment_preflight_blocker_report_digest(
    blocker_report: &ProductionDeploymentPreflightBlockerReport,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_blocker_report_frame(
        blocker_report,
    ))
    .into()
}

pub fn validate_production_deployment_preflight_blocker_report(
    report: &ProductionDeploymentPreflightReport,
    blocker_report: &ProductionDeploymentPreflightBlockerReport,
) -> Result<(), String> {
    let expected = production_deployment_preflight_blocker_report(report)?;
    if expected != *blocker_report {
        return Err("production deployment preflight blocker report mismatch".to_string());
    }
    if production_deployment_preflight_blocker_report_digest(blocker_report)
        != blocker_report.digest
    {
        return Err("production deployment preflight blocker report digest mismatch".to_string());
    }
    Ok(())
}

pub fn production_deployment_preflight_verdict(
    report: &ProductionDeploymentPreflightReport,
) -> Result<ProductionDeploymentPreflightVerdict, String> {
    if production_deployment_preflight_report_digest(report) != report.digest {
        return Err("production deployment preflight report digest mismatch".to_string());
    }
    let verdict = if report.preflight.deployment_ready {
        PRODUCTION_DEPLOYMENT_PREFLIGHT_VERDICT_DEPLOYABLE
    } else {
        PRODUCTION_DEPLOYMENT_PREFLIGHT_VERDICT_BLOCKED
    };
    let primary_blocker = report
        .preflight
        .blockers
        .first()
        .copied()
        .unwrap_or(PRODUCTION_DEPLOYMENT_PREFLIGHT_NO_BLOCKER);
    let blocker_report = production_deployment_preflight_blocker_report(report)?;
    let mut preflight_verdict = ProductionDeploymentPreflightVerdict {
        digest: [0_u8; DIGEST_BYTES],
        preflight_report_digest: report.digest,
        blocker_report_digest: blocker_report.digest,
        verdict,
        deployment_ready: report.preflight.deployment_ready,
        blocker_count: report.preflight.blockers.len(),
        primary_blocker,
    };
    preflight_verdict.digest = production_deployment_preflight_verdict_digest(&preflight_verdict);
    Ok(preflight_verdict)
}

pub fn production_deployment_preflight_verdict_digest(
    verdict: &ProductionDeploymentPreflightVerdict,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_verdict_frame(verdict)).into()
}

pub fn validate_production_deployment_preflight_verdict(
    report: &ProductionDeploymentPreflightReport,
    verdict: &ProductionDeploymentPreflightVerdict,
) -> Result<(), String> {
    let expected = production_deployment_preflight_verdict(report)?;
    if expected != *verdict {
        return Err("production deployment preflight verdict mismatch".to_string());
    }
    if production_deployment_preflight_verdict_digest(verdict) != verdict.digest {
        return Err("production deployment preflight verdict digest mismatch".to_string());
    }
    Ok(())
}

pub fn production_deployment_preflight_ready_assertion(
    report: &ProductionDeploymentPreflightReport,
    verdict: &ProductionDeploymentPreflightVerdict,
) -> Result<ProductionDeploymentPreflightReadyAssertion, String> {
    validate_production_deployment_preflight_verdict(report, verdict)?;
    let assertion_passed = verdict.verdict == PRODUCTION_DEPLOYMENT_PREFLIGHT_VERDICT_DEPLOYABLE
        && verdict.deployment_ready
        && verdict.blocker_count == 0;
    let blocker = if assertion_passed {
        PRODUCTION_DEPLOYMENT_PREFLIGHT_NO_BLOCKER
    } else {
        verdict.primary_blocker
    };
    let mut assertion = ProductionDeploymentPreflightReadyAssertion {
        digest: [0_u8; DIGEST_BYTES],
        preflight_report_digest: report.digest,
        blocker_report_digest: verdict.blocker_report_digest,
        verdict_digest: verdict.digest,
        assertion_passed,
        blocker,
    };
    assertion.digest = production_deployment_preflight_ready_assertion_digest(&assertion);
    Ok(assertion)
}

pub fn production_deployment_preflight_ready_assertion_digest(
    assertion: &ProductionDeploymentPreflightReadyAssertion,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_ready_assertion_frame(
        assertion,
    ))
    .into()
}

pub fn validate_production_deployment_preflight_ready_assertion(
    report: &ProductionDeploymentPreflightReport,
    verdict: &ProductionDeploymentPreflightVerdict,
    assertion: &ProductionDeploymentPreflightReadyAssertion,
) -> Result<(), String> {
    let expected = production_deployment_preflight_ready_assertion(report, verdict)?;
    if expected != *assertion {
        return Err("production deployment preflight ready assertion mismatch".to_string());
    }
    if production_deployment_preflight_ready_assertion_digest(assertion) != assertion.digest {
        return Err("production deployment preflight ready assertion digest mismatch".to_string());
    }
    Ok(())
}

pub fn production_deployment_preflight_certificate(
    report: &ProductionDeploymentPreflightReport,
) -> Result<ProductionDeploymentPreflightCertificate, String> {
    validate_production_deployment_preflight_report(report)?;
    let blocker_report = production_deployment_preflight_blocker_report(report)?;
    let verdict = production_deployment_preflight_verdict(report)?;
    let ready_assertion = production_deployment_preflight_ready_assertion(report, &verdict)?;
    let mut certificate = ProductionDeploymentPreflightCertificate {
        digest: [0_u8; DIGEST_BYTES],
        preflight_report_digest: report.digest,
        blocker_report_digest: blocker_report.digest,
        verdict_digest: verdict.digest,
        ready_assertion_digest: ready_assertion.digest,
        deployment_ready: ready_assertion.assertion_passed,
        blocker_count: verdict.blocker_count,
        primary_blocker: ready_assertion.blocker,
    };
    certificate.digest = production_deployment_preflight_certificate_digest(&certificate);
    Ok(certificate)
}

pub fn production_deployment_preflight_certificate_digest(
    certificate: &ProductionDeploymentPreflightCertificate,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(production_deployment_preflight_certificate_frame(
        certificate,
    ))
    .into()
}

