pub fn path2_reviewed_fq12_extraction_compatibility_certificate_v1(
    assembly_cert: &Path2ReviewedFq12NativeRepresentativeAssemblyCertificateV1,
    full_opening_cert: &Path2ReviewedFq12FullNativeOpeningCertificateV1,
    payload_binding: &Path2ReviewedFq12HiddenSourcePayloadBindingV1,
    extraction_cert: &Path2ReviewedFq12HiddenRelationExtractionCertificateV1,
) -> Result<Path2ReviewedFq12ExtractionCompatibilityCertificateV1, String> {
    if path2_reviewed_fq12_native_representative_assembly_certificate_v1_digest(assembly_cert)?
        != assembly_cert.assembly_certificate_digest
    {
        return Err(
            "Path 2 extraction compatibility assembly certificate digest mismatch".to_string(),
        );
    }
    if path2_reviewed_fq12_full_native_opening_certificate_v1_digest(full_opening_cert)?
        != full_opening_cert.role_lift_certificate_digest
    {
        return Err(
            "Path 2 extraction compatibility role-lift certificate digest mismatch".to_string(),
        );
    }
    if path2_reviewed_fq12_hidden_source_payload_binding_v1_digest(payload_binding)?
        != payload_binding.payload_digest
    {
        return Err("Path 2 extraction compatibility payload digest mismatch".to_string());
    }
    if path2_reviewed_fq12_hidden_relation_extraction_certificate_v1_digest(extraction_cert)?
        != extraction_cert.extraction_certificate_digest
    {
        return Err(
            "Path 2 extraction compatibility extraction certificate digest mismatch".to_string(),
        );
    }
    if assembly_cert.role_lift_certificate_digest != full_opening_cert.role_lift_certificate_digest
        || assembly_cert.payload_binding_digest != payload_binding.payload_digest
        || assembly_cert.extraction_certificate_digest
            != extraction_cert.extraction_certificate_digest
        || full_opening_cert.payload_binding_digest != payload_binding.payload_digest
        || full_opening_cert.extraction_certificate_digest
            != extraction_cert.extraction_certificate_digest
    {
        return Err("Path 2 extraction compatibility certificate chain mismatch".to_string());
    }
    if assembly_cert.native_boundary_digest != payload_binding.native_boundary_digest
        || assembly_cert.native_boundary_digest != extraction_cert.native_boundary_digest
        || assembly_cert.slot_id != payload_binding.slot_id
        || assembly_cert.slot_id != extraction_cert.slot_id
        || assembly_cert.hidden_source_statement_digest
            != payload_binding.hidden_source_statement_digest
        || assembly_cert.hidden_source_statement_digest
            != extraction_cert.hidden_source_statement_digest
        || assembly_cert.reviewed_active_lane_statement_digest
            != payload_binding.reviewed_active_lane_statement_digest
        || assembly_cert.reviewed_active_lane_statement_digest
            != extraction_cert.reviewed_active_lane_statement_digest
    {
        return Err("Path 2 extraction compatibility payload field mismatch".to_string());
    }
    if assembly_cert.full_opening_digest != full_opening_cert.full_opening_digest
        || assembly_cert.selected_account_projection_digest
            != full_opening_cert.selected_account_projection_digest
        || assembly_cert.selected_account_projection_digest
            != extraction_cert.account_projection_digest
    {
        return Err("Path 2 extraction compatibility representative mismatch".to_string());
    }
    let mut cert = Path2ReviewedFq12ExtractionCompatibilityCertificateV1 {
        schema: PATH2_REVIEWED_FQ12_EXTRACTION_COMPATIBILITY_CERTIFICATE_DOMAIN,
        assembly_certificate_digest: assembly_cert.assembly_certificate_digest,
        role_lift_certificate_digest: assembly_cert.role_lift_certificate_digest,
        payload_binding_digest: assembly_cert.payload_binding_digest,
        extraction_certificate_digest: assembly_cert.extraction_certificate_digest,
        native_boundary_digest: assembly_cert.native_boundary_digest,
        slot_id: assembly_cert.slot_id,
        hidden_source_statement_digest: assembly_cert.hidden_source_statement_digest,
        reviewed_active_lane_statement_digest: assembly_cert.reviewed_active_lane_statement_digest,
        full_opening_digest: assembly_cert.full_opening_digest,
        selected_account_projection_digest: assembly_cert.selected_account_projection_digest,
        representative_digest: assembly_cert.representative_digest,
        compatibility_certificate_digest: [0_u8; DIGEST_BYTES],
    };
    cert.compatibility_certificate_digest =
        path2_reviewed_fq12_extraction_compatibility_certificate_v1_digest(&cert)?;
    Ok(cert)
}

