pub fn path2_transparent_proof_family_capability_v1()
-> Result<Path2TransparentProofFamilyCapabilityV1, String> {
    let trace_column_manifest = path2_native_boundary_trace_column_manifest_v1()?;
    let capability = Path2TransparentProofFamilyCapabilityV1 {
        schema: PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA,
        profile_id: PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_PROFILE_ID,
        family: PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY,
        relation_layout_digest: path2_transparent_relation_layout_v1_digest()?,
        trace_column_manifest_digest: path2_native_boundary_trace_column_manifest_v1_digest()?,
        query_schedule_digest: path2_transparent_query_schedule_v1_digest()?,
        trace_proof_family_interface_digest:
            path2_native_boundary_trace_proof_family_interface_v1_digest()?,
        column_profile: PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
        active_witness_lane_floor: trace_column_manifest.range_account_lane_floor,
        native_boundary_relation_rows: trace_column_manifest.relation_rows_working,
        parent_root_binding: true,
        typed_role_subcommitments: true,
        creation_binding_role_handles_bound: true,
        inner_commitment_binding_break_exported: true,
        full_trace_extractable: true,
        full_witness_relation_knowledge: true,
        hidden_column_zero_knowledge: true,
        masked_query_no_export: true,
        qrom_schedule_bound: true,
        norm_range_soundness: true,
        blinding_noise_bound_soundness: true,
        role_authentication_material_simulatable: true,
        mask_freshness: true,
        no_raw_hidden_openings: true,
        no_public_linear_role_commitments: true,
        fallback_threshold_bytes: PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES,
    };
    verify_path2_transparent_proof_family_capability(&capability)?;
    Ok(capability)
}

pub fn verify_path2_transparent_proof_family_capability(
    capability: &Path2TransparentProofFamilyCapabilityV1,
) -> Result<(), String> {
    if capability.schema != PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA {
        return Err("Path 2 transparent proof-family capability schema mismatch".to_string());
    }
    if capability.profile_id != PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_PROFILE_ID {
        return Err("Path 2 transparent proof-family capability profile mismatch".to_string());
    }
    if capability.family != PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY {
        return Err("Path 2 transparent proof-family capability family mismatch".to_string());
    }
    if capability.relation_layout_digest != path2_transparent_relation_layout_v1_digest()? {
        return Err(
            "Path 2 transparent proof-family capability relation layout mismatch".to_string(),
        );
    }
    let trace_column_manifest = path2_native_boundary_trace_column_manifest_v1()?;
    if capability.trace_column_manifest_digest
        != path2_native_boundary_trace_column_manifest_v1_digest()?
    {
        return Err(
            "Path 2 transparent proof-family capability trace column manifest mismatch".to_string(),
        );
    }
    if capability.query_schedule_digest != path2_transparent_query_schedule_v1_digest()? {
        return Err(
            "Path 2 transparent proof-family capability query schedule mismatch".to_string(),
        );
    }
    if capability.trace_proof_family_interface_digest
        != path2_native_boundary_trace_proof_family_interface_v1_digest()?
    {
        return Err(
            "Path 2 transparent proof-family capability trace proof interface mismatch".to_string(),
        );
    }
    verify_path2_two_view_column_profile_id(capability.column_profile)?;
    if capability.active_witness_lane_floor != trace_column_manifest.range_account_lane_floor {
        return Err(
            "Path 2 transparent proof-family capability active witness lane floor mismatch"
                .to_string(),
        );
    }
    if capability.active_witness_lane_floor <= PATH2_TRANSPARENT_DESCENT_WITNESS_LANES as u16 {
        return Err("Path 2 transparent proof-family capability is semantic-core-only".to_string());
    }
    if capability.native_boundary_relation_rows != trace_column_manifest.relation_rows_working {
        return Err(
            "Path 2 transparent proof-family capability native relation rows mismatch".to_string(),
        );
    }
    for (label, enabled) in [
        ("parent_root_binding", capability.parent_root_binding),
        (
            "typed_role_subcommitments",
            capability.typed_role_subcommitments,
        ),
        (
            "creation_binding_role_handles_bound",
            capability.creation_binding_role_handles_bound,
        ),
        (
            "inner_commitment_binding_break_exported",
            capability.inner_commitment_binding_break_exported,
        ),
        ("full_trace_extractable", capability.full_trace_extractable),
        (
            "full_witness_relation_knowledge",
            capability.full_witness_relation_knowledge,
        ),
        (
            "hidden_column_zero_knowledge",
            capability.hidden_column_zero_knowledge,
        ),
        ("masked_query_no_export", capability.masked_query_no_export),
        ("qrom_schedule_bound", capability.qrom_schedule_bound),
        ("norm_range_soundness", capability.norm_range_soundness),
        (
            "blinding_noise_bound_soundness",
            capability.blinding_noise_bound_soundness,
        ),
        (
            "role_authentication_material_simulatable",
            capability.role_authentication_material_simulatable,
        ),
        ("mask_freshness", capability.mask_freshness),
        ("no_raw_hidden_openings", capability.no_raw_hidden_openings),
        (
            "no_public_linear_role_commitments",
            capability.no_public_linear_role_commitments,
        ),
    ] {
        if !enabled {
            return Err(format!(
                "Path 2 transparent proof-family capability missing {label}"
            ));
        }
    }
    if capability.fallback_threshold_bytes
        != PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES
    {
        return Err(
            "Path 2 transparent proof-family capability fallback threshold mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn path2_transparent_proof_family_capability_v1_digest() -> Result<[u8; DIGEST_BYTES], String> {
    let capability = path2_transparent_proof_family_capability_v1()?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"profile_id", capability.profile_id as u64);
    append_frame(&mut frame, b"family", capability.family.as_bytes());
    append_frame(
        &mut frame,
        b"relation_layout_digest",
        &capability.relation_layout_digest,
    );
    append_frame(
        &mut frame,
        b"trace_column_manifest_digest",
        &capability.trace_column_manifest_digest,
    );
    append_frame(
        &mut frame,
        b"query_schedule_digest",
        &capability.query_schedule_digest,
    );
    append_frame(
        &mut frame,
        b"trace_proof_family_interface_digest",
        &capability.trace_proof_family_interface_digest,
    );
    append_u64(
        &mut frame,
        b"column_profile",
        capability.column_profile as u64,
    );
    append_u64(
        &mut frame,
        b"active_witness_lane_floor",
        capability.active_witness_lane_floor as u64,
    );
    append_u64(
        &mut frame,
        b"native_boundary_relation_rows",
        capability.native_boundary_relation_rows as u64,
    );
    for (label, enabled) in [
        ("parent_root_binding", capability.parent_root_binding),
        (
            "typed_role_subcommitments",
            capability.typed_role_subcommitments,
        ),
        (
            "creation_binding_role_handles_bound",
            capability.creation_binding_role_handles_bound,
        ),
        (
            "inner_commitment_binding_break_exported",
            capability.inner_commitment_binding_break_exported,
        ),
        ("full_trace_extractable", capability.full_trace_extractable),
        (
            "full_witness_relation_knowledge",
            capability.full_witness_relation_knowledge,
        ),
        (
            "hidden_column_zero_knowledge",
            capability.hidden_column_zero_knowledge,
        ),
        ("masked_query_no_export", capability.masked_query_no_export),
        ("qrom_schedule_bound", capability.qrom_schedule_bound),
        ("norm_range_soundness", capability.norm_range_soundness),
        (
            "blinding_noise_bound_soundness",
            capability.blinding_noise_bound_soundness,
        ),
        (
            "role_authentication_material_simulatable",
            capability.role_authentication_material_simulatable,
        ),
        ("mask_freshness", capability.mask_freshness),
        ("no_raw_hidden_openings", capability.no_raw_hidden_openings),
        (
            "no_public_linear_role_commitments",
            capability.no_public_linear_role_commitments,
        ),
    ] {
        append_u64(&mut frame, label.as_bytes(), u64::from(enabled));
    }
    append_u64(
        &mut frame,
        b"fallback_threshold_bytes",
        capability.fallback_threshold_bytes as u64,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_commitment_api_v1(
    public_view: &Path2TransparentDescentPublicViewV1,
    binding: &Path2CreationProofBindingV1,
) -> Result<Path2TransparentCommitmentApiV1, String> {
    let role_handles = [
        Path2TransparentCommitmentRoleHandleV1 {
            role_id: PATH2_TWO_VIEW_ROLE_PAD_SOURCE,
            column_set_id: path2_two_view_column_profile_entry(PATH2_TWO_VIEW_ROLE_PAD_SOURCE)?
                .hidden_column_set_id,
            role_handle: binding.pad_source_commitment,
            authenticated_under_parent_root: true,
        },
        Path2TransparentCommitmentRoleHandleV1 {
            role_id: PATH2_TWO_VIEW_ROLE_PROJECTION_RELATION,
            column_set_id: path2_two_view_column_profile_entry(
                PATH2_TWO_VIEW_ROLE_PROJECTION_RELATION,
            )?
            .hidden_column_set_id,
            role_handle: binding.projection_relation_commitment,
            authenticated_under_parent_root: true,
        },
        Path2TransparentCommitmentRoleHandleV1 {
            role_id: PATH2_TWO_VIEW_ROLE_OPENING_TUPLE,
            column_set_id: path2_two_view_column_profile_entry(PATH2_TWO_VIEW_ROLE_OPENING_TUPLE)?
                .hidden_column_set_id,
            role_handle: binding.opening_tuple_commitment,
            authenticated_under_parent_root: true,
        },
        Path2TransparentCommitmentRoleHandleV1 {
            role_id: PATH2_TWO_VIEW_ROLE_PACKED_WITNESS,
            column_set_id: path2_two_view_column_profile_entry(PATH2_TWO_VIEW_ROLE_PACKED_WITNESS)?
                .hidden_column_set_id,
            role_handle: binding.packed_witness_commitment,
            authenticated_under_parent_root: true,
        },
    ];
    let api = Path2TransparentCommitmentApiV1 {
        schema: PATH2_TRANSPARENT_COMMITMENT_API_SCHEMA,
        proof_system_id: public_view.proof_system_id,
        relation_id: public_view.relation_id,
        column_profile: public_view.column_profile,
        trace_commitment_root: public_view.trace_commitment_root,
        constraint_commitment_root: public_view.constraint_commitment_root,
        creation_proof_binding_digest: binding.digest,
        native_role_root_commitment: binding.native_role_root_commitment,
        role_handles,
    };
    verify_path2_transparent_commitment_api(&api, public_view, binding)?;
    Ok(api)
}

pub fn verify_path2_transparent_commitment_api(
    api: &Path2TransparentCommitmentApiV1,
    public_view: &Path2TransparentDescentPublicViewV1,
    binding: &Path2CreationProofBindingV1,
) -> Result<(), String> {
    verify_path2_transparent_descent_public_view(public_view)?;
    if api.schema != PATH2_TRANSPARENT_COMMITMENT_API_SCHEMA {
        return Err("Path 2 transparent commitment API schema mismatch".to_string());
    }
    if path2_creation_proof_binding_v1_digest(binding) != binding.digest {
        return Err("Path 2 transparent commitment API binding digest mismatch".to_string());
    }
    let expected_role_root = path2_creation_native_role_root_commitment_v1(
        &binding.packed_witness_commitment,
        &binding.randomizer_commitment,
        &binding.pad_source_commitment,
        &binding.opening_tuple_commitment,
        &binding.projection_relation_commitment,
        &binding.gauge_commitment,
    );
    if binding.native_role_root_commitment != expected_role_root {
        return Err("Path 2 transparent commitment API native role root mismatch".to_string());
    }
    if api.proof_system_id != public_view.proof_system_id
        || api.relation_id != public_view.relation_id
        || api.column_profile != public_view.column_profile
        || api.trace_commitment_root != public_view.trace_commitment_root
        || api.constraint_commitment_root != public_view.constraint_commitment_root
        || api.creation_proof_binding_digest != public_view.creation_proof_binding_digest
        || api.creation_proof_binding_digest != binding.digest
        || api.native_role_root_commitment != binding.native_role_root_commitment
    {
        return Err("Path 2 transparent commitment API context mismatch".to_string());
    }
    let expected_roles = [
        (
            PATH2_TWO_VIEW_ROLE_PAD_SOURCE,
            binding.pad_source_commitment,
        ),
        (
            PATH2_TWO_VIEW_ROLE_PROJECTION_RELATION,
            binding.projection_relation_commitment,
        ),
        (
            PATH2_TWO_VIEW_ROLE_OPENING_TUPLE,
            binding.opening_tuple_commitment,
        ),
        (
            PATH2_TWO_VIEW_ROLE_PACKED_WITNESS,
            binding.packed_witness_commitment,
        ),
    ];
    let mut seen_roles = BTreeSet::new();
    for (handle, (expected_role_id, expected_handle)) in api.role_handles.iter().zip(expected_roles)
    {
        if !seen_roles.insert(handle.role_id) {
            return Err("Path 2 transparent commitment API duplicate role handle".to_string());
        }
        if handle.role_id != expected_role_id {
            return Err("Path 2 transparent commitment API role order mismatch".to_string());
        }
        let profile_entry = path2_two_view_column_profile_entry(handle.role_id)?;
        if handle.column_set_id != profile_entry.hidden_column_set_id {
            return Err("Path 2 transparent commitment API column set mismatch".to_string());
        }
        if handle.role_handle != expected_handle || handle.role_handle == [0_u8; DIGEST_BYTES] {
            return Err("Path 2 transparent commitment API role handle mismatch".to_string());
        }
        if !handle.authenticated_under_parent_root {
            return Err(
                "Path 2 transparent commitment API role handle is not parent-authenticated"
                    .to_string(),
            );
        }
    }
    Ok(())
}

pub fn path2_transparent_commitment_api_v1_digest(
    api: &Path2TransparentCommitmentApiV1,
    public_view: &Path2TransparentDescentPublicViewV1,
    binding: &Path2CreationProofBindingV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_commitment_api(api, public_view, binding)?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_COMMITMENT_API_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", &api.proof_system_id);
    append_frame(&mut frame, b"relation_id", &api.relation_id);
    append_frame(
        &mut frame,
        b"column_profile",
        &api.column_profile.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"trace_commitment_root",
        &api.trace_commitment_root,
    );
    append_frame(
        &mut frame,
        b"constraint_commitment_root",
        &api.constraint_commitment_root,
    );
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        &api.creation_proof_binding_digest,
    );
    append_frame(
        &mut frame,
        b"native_role_root_commitment",
        &api.native_role_root_commitment,
    );
    for handle in api.role_handles {
        append_frame(&mut frame, b"role_id", &[handle.role_id]);
        append_frame(
            &mut frame,
            b"column_set_id",
            &handle.column_set_id.to_le_bytes(),
        );
        append_frame(&mut frame, b"role_handle", &handle.role_handle);
        append_u64(
            &mut frame,
            b"authenticated_under_parent_root",
            u64::from(handle.authenticated_under_parent_root),
        );
    }
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_descent_proof_system_id() -> [u8; DIGEST_BYTES] {
    let proof_family_capability_digest = path2_transparent_proof_family_capability_v1_digest()
        .expect("Path 2 transparent proof-family capability is statically valid");
    let query_schedule_digest = path2_transparent_query_schedule_v1_digest()
        .expect("Path 2 transparent query schedule is statically valid");
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"proof_system_profile",
        PATH2_TRANSPARENT_DESCENT_PROOF_SYSTEM_PROFILE.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"proof_domain",
        PATH2_TRANSPARENT_DESCENT_PROOF_DOMAIN.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"relation_id",
        &path2_transparent_descent_relation_id(),
    );
    append_frame(
        &mut frame,
        b"proof_family_capability_digest",
        &proof_family_capability_digest,
    );
    append_frame(&mut frame, b"query_schedule_digest", &query_schedule_digest);
    append_u64(
        &mut frame,
        b"witness_lanes",
        PATH2_TRANSPARENT_DESCENT_WITNESS_LANES as u64,
    );
    append_u64(
        &mut frame,
        b"relation_rows",
        PATH2_TRANSPARENT_DESCENT_RELATION_ROWS as u64,
    );
    Sha256::digest(frame).into()
}

