pub fn verify_path2_two_view_column_profile(
    profile: &Path2TwoViewColumnProfileV1,
) -> Result<(), String> {
    if profile.schema != PATH2_TWO_VIEW_COLUMN_PROFILE_SCHEMA {
        return Err("Path 2 two-view column profile schema mismatch".to_string());
    }
    if profile.profile_id != PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1 {
        return Err("Path 2 two-view unknown column profile".to_string());
    }
    if profile.norm_range_mode != PATH2_TWO_VIEW_NORM_RANGE_HYBRID_BASE128_HIDDEN_ROLES {
        return Err("Path 2 two-view column profile norm/range mode mismatch".to_string());
    }
    if profile.extraction_mode != PATH2_TWO_VIEW_EXTRACTION_FULL_TRACE_EXTRACTABLE {
        return Err("Path 2 two-view column profile extraction mode mismatch".to_string());
    }
    if profile.relation_knowledge_mode != PATH2_TWO_VIEW_RELATION_FULL_WITNESS_RELATION_KNOWLEDGE {
        return Err("Path 2 two-view column profile relation knowledge mode mismatch".to_string());
    }
    if profile.rejection_policy_id != PATH2_TWO_VIEW_REJECTION_POLICY_UNKNOWN_PROFILE_REJECT {
        return Err("Path 2 two-view column profile rejection policy mismatch".to_string());
    }

    let mut roles = BTreeSet::new();
    let mut hidden_sets = BTreeSet::new();
    let mut masked_sets = BTreeSet::new();
    let mut mask_domains = BTreeSet::new();
    for entry in profile.entries {
        if entry.role_id == 0 || !roles.insert(entry.role_id) {
            return Err("Path 2 two-view column profile duplicate or unknown role".to_string());
        }
        if entry.hidden_column_set_id == entry.masked_column_set_id {
            return Err(
                "Path 2 two-view column profile identifies hidden and masked columns".to_string(),
            );
        }
        if !hidden_sets.insert(entry.hidden_column_set_id) {
            return Err("Path 2 two-view column profile duplicate hidden column set".to_string());
        }
        if !masked_sets.insert(entry.masked_column_set_id) {
            return Err("Path 2 two-view column profile duplicate masked column set".to_string());
        }
        match entry.visibility_class {
            PATH2_TWO_VIEW_VISIBILITY_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_DERIVED_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_MASKED_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_COMMITTED_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_RANGE_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_BLINDING_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_SIMULATOR_ONLY => {}
            _ => {
                return Err("Path 2 two-view column profile unknown visibility class".to_string());
            }
        }
        match entry.authentication_mode {
            PATH2_TWO_VIEW_AUTH_PUBLIC_PATH_TO_MASKED_LEAF
            | PATH2_TWO_VIEW_AUTH_SIMULATOR_ONLY_PATH
            | PATH2_TWO_VIEW_AUTH_EXTRACTOR_ONLY_OPENING => {}
            PATH2_TWO_VIEW_AUTH_PUBLIC_PATH_TO_RAW_LEAF
            | PATH2_TWO_VIEW_AUTH_PUBLIC_LINEAR_COMMITMENT => {
                return Err(
                    "Path 2 two-view column profile forbidden authentication mode".to_string(),
                );
            }
            _ => {
                return Err(
                    "Path 2 two-view column profile unknown authentication mode".to_string()
                );
            }
        }
        if matches!(
            entry.visibility_class,
            PATH2_TWO_VIEW_VISIBILITY_COMMITTED_HIDDEN
                | PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN
                | PATH2_TWO_VIEW_VISIBILITY_RANGE_PRIVATE
                | PATH2_TWO_VIEW_VISIBILITY_BLINDING_PRIVATE
                | PATH2_TWO_VIEW_VISIBILITY_SIMULATOR_ONLY
        ) && entry.mask_domain_id == 0
        {
            return Err("Path 2 two-view column profile hidden role lacks mask domain".to_string());
        }
        if entry.mask_domain_id != 0 && !mask_domains.insert(entry.mask_domain_id) {
            return Err("Path 2 two-view column profile duplicate mask domain".to_string());
        }
        if entry.query_policy_id != PATH2_TWO_VIEW_QUERY_POLICY_ZK_TYPED_ROLE_OPENINGS {
            return Err("Path 2 two-view column profile query policy mismatch".to_string());
        }
    }

    for role in [
        PATH2_TWO_VIEW_ROLE_CONTEXT_PUBLIC,
        PATH2_TWO_VIEW_ROLE_PACKED_WITNESS,
        PATH2_TWO_VIEW_ROLE_RANDOMIZER,
        PATH2_TWO_VIEW_ROLE_PAD_SOURCE,
        PATH2_TWO_VIEW_ROLE_OPENING_TUPLE,
        PATH2_TWO_VIEW_ROLE_PROJECTION_RELATION,
        PATH2_TWO_VIEW_ROLE_RANGE_WITNESS,
        PATH2_TWO_VIEW_ROLE_BLINDING,
        PATH2_TWO_VIEW_ROLE_CONSTRAINT,
    ] {
        if !roles.contains(&role) {
            return Err("Path 2 two-view column profile missing mandatory role".to_string());
        }
    }
    Ok(())
}

pub fn verify_path2_two_view_column_profile_id(column_profile: u16) -> Result<(), String> {
    if column_profile != PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1 {
        return Err("Path 2 transparent proof unknown column profile".to_string());
    }
    verify_path2_two_view_column_profile(&path2_two_view_column_profile_v1())
}

pub fn path2_two_view_column_profile_v1_digest() -> Result<[u8; DIGEST_BYTES], String> {
    let profile = path2_two_view_column_profile_v1();
    verify_path2_two_view_column_profile(&profile)?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TWO_VIEW_COLUMN_PROFILE_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"profile_id", profile.profile_id as u64);
    append_u64(
        &mut frame,
        b"norm_range_mode",
        profile.norm_range_mode as u64,
    );
    append_u64(
        &mut frame,
        b"extraction_mode",
        profile.extraction_mode as u64,
    );
    append_u64(
        &mut frame,
        b"relation_knowledge_mode",
        profile.relation_knowledge_mode as u64,
    );
    append_u64(
        &mut frame,
        b"rejection_policy_id",
        profile.rejection_policy_id as u64,
    );
    for entry in profile.entries {
        append_u64(&mut frame, b"role_id", entry.role_id as u64);
        append_u64(
            &mut frame,
            b"hidden_column_set_id",
            entry.hidden_column_set_id as u64,
        );
        append_u64(
            &mut frame,
            b"masked_column_set_id",
            entry.masked_column_set_id as u64,
        );
        append_u64(
            &mut frame,
            b"visibility_class",
            entry.visibility_class as u64,
        );
        append_u64(
            &mut frame,
            b"authentication_mode",
            entry.authentication_mode as u64,
        );
        append_u64(&mut frame, b"mask_domain_id", entry.mask_domain_id as u64);
        append_u64(&mut frame, b"range_policy_id", entry.range_policy_id as u64);
        append_u64(&mut frame, b"query_policy_id", entry.query_policy_id as u64);
    }
    Ok(Sha256::digest(frame).into())
}

fn path2_two_view_column_profile_entry(
    role_id: u8,
) -> Result<Path2TwoViewColumnProfileEntryV1, String> {
    path2_two_view_column_profile_v1()
        .entries
        .into_iter()
        .find(|entry| entry.role_id == role_id)
        .ok_or_else(|| "Path 2 transparent query opening unknown role".to_string())
}

fn path2_two_view_entry_is_hidden_or_private(entry: &Path2TwoViewColumnProfileEntryV1) -> bool {
    matches!(
        entry.visibility_class,
        PATH2_TWO_VIEW_VISIBILITY_COMMITTED_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_RANGE_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_BLINDING_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_SIMULATOR_ONLY
    )
}

fn path2_transparent_query_opening_expected_mask_domain_id(
    query_index: u16,
    entry: &Path2TwoViewColumnProfileEntryV1,
) -> Result<u16, String> {
    if !path2_two_view_entry_is_hidden_or_private(entry) {
        return Ok(0);
    }
    query_index
        .checked_mul(PATH2_TWO_VIEW_COLUMN_PROFILE_ENTRY_COUNT as u16)
        .and_then(|base| base.checked_add(entry.mask_domain_id))
        .ok_or_else(|| "Path 2 transparent query opening mask domain id overflow".to_string())
}

pub fn path2_transparent_query_row_index(
    public_view: &Path2TransparentDescentPublicViewV1,
    query_index: u16,
) -> Result<u16, String> {
    verify_path2_transparent_query_schedule_pair(public_view.trace_rows, public_view.query_count)?;
    if !public_view.trace_rows.is_power_of_two() {
        return Err("Path 2 transparent query row trace size is not power of two".to_string());
    }
    if query_index >= public_view.query_count {
        return Err("Path 2 transparent query row index outside schedule".to_string());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_QUERY_ROW_DERIVATION_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", &public_view.proof_system_id);
    append_frame(&mut frame, b"relation_id", &public_view.relation_id);
    append_frame(
        &mut frame,
        b"transparent_transcript_digest",
        &public_view.transparent_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"query_schedule_digest",
        &path2_transparent_query_schedule_v1_digest()?,
    );
    append_frame(
        &mut frame,
        b"column_profile",
        &public_view.column_profile.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"trace_rows",
        &public_view.trace_rows.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"query_count",
        &public_view.query_count.to_le_bytes(),
    );
    append_frame(&mut frame, b"query_index", &query_index.to_le_bytes());
    let digest = Sha256::digest(frame);
    Ok(u16::from_le_bytes([digest[0], digest[1]]) & (public_view.trace_rows - 1))
}

pub fn path2_transparent_query_opening_mask_domain_digest(
    public_view: &Path2TransparentDescentPublicViewV1,
    record: &Path2TransparentQueryOpeningRecordV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_descent_public_view(public_view)?;
    let entry = path2_two_view_column_profile_entry(record.role_id)?;
    if !path2_two_view_entry_is_hidden_or_private(&entry) {
        return Ok([0_u8; DIGEST_BYTES]);
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_QUERY_OPENING_MASK_DOMAIN_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", &public_view.proof_system_id);
    append_frame(&mut frame, b"relation_id", &public_view.relation_id);
    append_frame(
        &mut frame,
        b"transparent_transcript_digest",
        &public_view.transparent_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"leaf_context_digest",
        &public_view.leaf_context_digest,
    );
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        &public_view.creation_proof_binding_digest,
    );
    append_frame(
        &mut frame,
        b"matrix_domain_transcript_digest",
        &public_view.matrix_domain_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"aggregation_context_digest",
        &public_view.aggregation_context_digest,
    );
    append_frame(
        &mut frame,
        b"trace_commitment_root",
        &public_view.trace_commitment_root,
    );
    append_frame(
        &mut frame,
        b"constraint_commitment_root",
        &public_view.constraint_commitment_root,
    );
    for value in public_view.masked_projection {
        append_frame(&mut frame, b"masked_projection", &value.to_le_bytes());
    }
    append_frame(
        &mut frame,
        b"column_profile",
        &public_view.column_profile.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"trace_rows",
        &public_view.trace_rows.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"query_count",
        &public_view.query_count.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"public_view_query_index",
        &public_view.query_index.to_le_bytes(),
    );
    append_frame(&mut frame, b"role_id", &[record.role_id]);
    append_frame(
        &mut frame,
        b"profile_mask_domain_id",
        &entry.mask_domain_id.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"column_set_id",
        &record.column_set_id.to_le_bytes(),
    );
    append_frame(&mut frame, b"row_index", &record.row_index.to_le_bytes());
    append_frame(
        &mut frame,
        b"query_index",
        &record.query_index.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"mask_domain_id",
        &record.mask_domain_id.to_le_bytes(),
    );
    Ok(Sha256::digest(frame).into())
}

pub fn verify_path2_transparent_query_opening_manifest(
    manifest: &Path2TransparentQueryOpeningManifestV1,
) -> Result<(), String> {
    if manifest.schema != PATH2_TRANSPARENT_QUERY_OPENING_MANIFEST_SCHEMA {
        return Err("Path 2 transparent query opening manifest schema mismatch".to_string());
    }
    if manifest.proof_system_id != path2_transparent_descent_proof_system_id() {
        return Err("Path 2 transparent query opening proof system mismatch".to_string());
    }
    if manifest.relation_id != path2_transparent_descent_relation_id() {
        return Err("Path 2 transparent query opening relation mismatch".to_string());
    }
    verify_path2_two_view_column_profile_id(manifest.column_profile)?;
    if manifest.query_count == 0 {
        return Err("Path 2 transparent query opening count is zero".to_string());
    }
    verify_path2_transparent_query_schedule_count(manifest.query_count)?;
    let expected_record_count =
        manifest.query_count as usize * PATH2_TWO_VIEW_COLUMN_PROFILE_ENTRY_COUNT;
    if manifest.records.len() != expected_record_count {
        return Err("Path 2 transparent query opening manifest count mismatch".to_string());
    }

    let profile = path2_two_view_column_profile_v1();
    let mut query_role_pairs = BTreeSet::new();
    let mut query_rows = BTreeMap::new();
    let mut mask_domains = BTreeSet::new();
    for record in &manifest.records {
        if record.query_index >= manifest.query_count
            || !query_role_pairs.insert((record.query_index, record.role_id))
        {
            return Err("Path 2 transparent query opening duplicate query role".to_string());
        }
        if let Some(row_index) = query_rows.insert(record.query_index, record.row_index) {
            if row_index != record.row_index {
                return Err("Path 2 transparent query opening row mismatch".to_string());
            }
        }
        if record.component_digest == [0_u8; DIGEST_BYTES] {
            return Err("Path 2 transparent query opening digest is zero".to_string());
        }
        let entry = path2_two_view_column_profile_entry(record.role_id)?;
        match record.visibility_class {
            PATH2_TWO_VIEW_VISIBILITY_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_DERIVED_PUBLIC
            | PATH2_TWO_VIEW_VISIBILITY_MASKED_PUBLIC => {}
            PATH2_TWO_VIEW_VISIBILITY_COMMITTED_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN
            | PATH2_TWO_VIEW_VISIBILITY_RANGE_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_BLINDING_PRIVATE
            | PATH2_TWO_VIEW_VISIBILITY_SIMULATOR_ONLY => {
                return Err(
                    "Path 2 transparent query opening exposes hidden visibility class".to_string(),
                );
            }
            _ => {
                return Err("Path 2 transparent query opening unknown visibility class".to_string());
            }
        }

        if record.column_set_id == entry.hidden_column_set_id {
            return Err("Path 2 transparent query opening uses hidden column set".to_string());
        }
        if record.column_set_id != entry.masked_column_set_id {
            return Err("Path 2 transparent query opening column set mismatch".to_string());
        }

        if path2_two_view_entry_is_hidden_or_private(&entry) {
            if record.visibility_class != PATH2_TWO_VIEW_VISIBILITY_MASKED_PUBLIC {
                return Err(
                    "Path 2 transparent query opening hidden role is not masked".to_string()
                );
            }
            let expected_mask_domain_id = path2_transparent_query_opening_expected_mask_domain_id(
                record.query_index,
                &entry,
            )?;
            if expected_mask_domain_id == 0 {
                return Err(
                    "Path 2 transparent query opening masked role lacks mask domain".to_string(),
                );
            }
            if record.mask_domain_id != expected_mask_domain_id {
                return Err("Path 2 transparent query opening mask domain id mismatch".to_string());
            }
            if !mask_domains.insert(record.mask_domain_id) {
                return Err("Path 2 transparent query opening duplicate mask domain".to_string());
            }
            if record.mask_domain_digest == [0_u8; DIGEST_BYTES] {
                return Err(
                    "Path 2 transparent query opening mask domain digest is zero".to_string(),
                );
            }
        } else if record.mask_domain_id != 0 {
            return Err("Path 2 transparent query opening public role has mask domain".to_string());
        } else if record.mask_domain_digest != [0_u8; DIGEST_BYTES] {
            return Err(
                "Path 2 transparent query opening public role has mask domain digest".to_string(),
            );
        }
    }

    for (index, record) in manifest.records.iter().enumerate() {
        let expected_query_index = (index / PATH2_TWO_VIEW_COLUMN_PROFILE_ENTRY_COUNT) as u16;
        let expected_entry = profile.entries[index % PATH2_TWO_VIEW_COLUMN_PROFILE_ENTRY_COUNT];
        if record.query_index != expected_query_index || record.role_id != expected_entry.role_id {
            return Err("Path 2 transparent query opening manifest order mismatch".to_string());
        }
    }

    for query_index in 0..manifest.query_count {
        for entry in profile.entries {
            if !query_role_pairs.contains(&(query_index, entry.role_id)) {
                return Err("Path 2 transparent query opening missing mandatory role".to_string());
            }
        }
    }

    Ok(())
}

pub fn path2_transparent_query_opening_manifest_v1(
    query_count: u16,
    records: Vec<Path2TransparentQueryOpeningRecordV1>,
) -> Result<Path2TransparentQueryOpeningManifestV1, String> {
    let manifest = Path2TransparentQueryOpeningManifestV1 {
        schema: PATH2_TRANSPARENT_QUERY_OPENING_MANIFEST_SCHEMA,
        proof_system_id: path2_transparent_descent_proof_system_id(),
        relation_id: path2_transparent_descent_relation_id(),
        column_profile: PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
        query_count,
        records,
    };
    verify_path2_transparent_query_opening_manifest(&manifest)?;
    Ok(manifest)
}

pub fn path2_transparent_query_opening_manifest_digest(
    manifest: &Path2TransparentQueryOpeningManifestV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_query_opening_manifest(manifest)?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_QUERY_OPENING_MANIFEST_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", &manifest.proof_system_id);
    append_frame(&mut frame, b"relation_id", &manifest.relation_id);
    append_frame(
        &mut frame,
        b"column_profile",
        &manifest.column_profile.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"query_count",
        &manifest.query_count.to_le_bytes(),
    );
    for record in &manifest.records {
        append_frame(
            &mut frame,
            b"query_index",
            &record.query_index.to_le_bytes(),
        );
        append_frame(&mut frame, b"role_id", &[record.role_id]);
        append_frame(
            &mut frame,
            b"column_set_id",
            &record.column_set_id.to_le_bytes(),
        );
        append_frame(&mut frame, b"row_index", &record.row_index.to_le_bytes());
        append_frame(&mut frame, b"visibility_class", &[record.visibility_class]);
        append_frame(
            &mut frame,
            b"mask_domain_id",
            &record.mask_domain_id.to_le_bytes(),
        );
        append_frame(
            &mut frame,
            b"mask_domain_digest",
            &record.mask_domain_digest,
        );
        append_frame(&mut frame, b"component_digest", &record.component_digest);
    }
    Ok(Sha256::digest(frame).into())
}

pub fn verify_path2_transparent_query_opening_manifest_for_public_view(
    public_view: &Path2TransparentDescentPublicViewV1,
    manifest: &Path2TransparentQueryOpeningManifestV1,
) -> Result<(), String> {
    verify_path2_transparent_descent_public_view(public_view)?;
    verify_path2_transparent_query_opening_manifest(manifest)?;
    if manifest.proof_system_id != public_view.proof_system_id
        || manifest.relation_id != public_view.relation_id
        || manifest.column_profile != public_view.column_profile
        || manifest.query_count != public_view.query_count
    {
        return Err(
            "Path 2 transparent descent query opening manifest context mismatch".to_string(),
        );
    }
    for record in &manifest.records {
        if record.row_index >= public_view.trace_rows {
            return Err("Path 2 transparent query opening row is outside trace".to_string());
        }
        if record.row_index != path2_transparent_query_row_index(public_view, record.query_index)? {
            return Err("Path 2 transparent query opening row does not match schedule".to_string());
        }
        let expected_mask_domain_digest =
            path2_transparent_query_opening_mask_domain_digest(public_view, record)?;
        if record.mask_domain_digest != expected_mask_domain_digest {
            return Err("Path 2 transparent query opening mask domain digest mismatch".to_string());
        }
    }
    Ok(())
}

pub fn path2_transparent_descent_transcript_digest(
    proof_system_id: &[u8; DIGEST_BYTES],
    trace_rows: u16,
    query_count: u16,
    column_profile: u16,
    leaf_context_digest: &[u8; DIGEST_BYTES],
    creation_proof_binding_digest: &[u8; DIGEST_BYTES],
    matrix_domain_transcript_digest: &[u8; DIGEST_BYTES],
    masked_projection: &[u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
    aggregation_context_digest: &[u8; DIGEST_BYTES],
    trace_commitment_root: &[u8; DIGEST_BYTES],
    constraint_commitment_root: &[u8; DIGEST_BYTES],
    query_index: u16,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_query_schedule_pair(trace_rows, query_count)?;
    if query_index >= query_count {
        return Err("Path 2 transparent proof query index outside schedule".to_string());
    }
    if *trace_commitment_root == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof trace commitment root is zero".to_string());
    }
    if *constraint_commitment_root == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof constraint commitment root is zero".to_string());
    }
    if masked_projection.iter().any(|&value| value >= Q) {
        return Err("Path 2 transparent proof masked projection is noncanonical".to_string());
    }
    verify_path2_two_view_column_profile_id(column_profile)?;
    let column_profile_digest = path2_two_view_column_profile_v1_digest()?;
    let relation_id = path2_transparent_descent_relation_id();
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        PATH2_TRANSPARENT_DESCENT_PROOF_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", proof_system_id);
    append_frame(&mut frame, b"relation_id", &relation_id);
    append_frame(&mut frame, b"trace_rows", &trace_rows.to_le_bytes());
    append_frame(&mut frame, b"query_count", &query_count.to_le_bytes());
    append_frame(&mut frame, b"column_profile", &column_profile.to_le_bytes());
    append_frame(&mut frame, b"column_profile_digest", &column_profile_digest);
    append_frame(&mut frame, b"leaf_context_digest", leaf_context_digest);
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        creation_proof_binding_digest,
    );
    append_frame(
        &mut frame,
        b"matrix_domain_transcript_digest",
        matrix_domain_transcript_digest,
    );
    for value in masked_projection {
        append_frame(&mut frame, b"masked_projection", &value.to_le_bytes());
    }
    append_frame(
        &mut frame,
        b"aggregation_context_digest",
        aggregation_context_digest,
    );
    append_frame(&mut frame, b"trace_commitment_root", trace_commitment_root);
    append_frame(
        &mut frame,
        b"constraint_commitment_root",
        constraint_commitment_root,
    );
    append_frame(&mut frame, b"query_index", &query_index.to_le_bytes());
    Ok(Sha256::digest(frame).into())
}

pub fn verify_path2_transparent_descent_public_view(
    public_view: &Path2TransparentDescentPublicViewV1,
) -> Result<(), String> {
    if public_view.schema != PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA {
        return Err("Path 2 transparent public view schema mismatch".to_string());
    }
    if public_view.proof_system_id != path2_transparent_descent_proof_system_id() {
        return Err("Path 2 transparent proof system id mismatch".to_string());
    }
    if public_view.relation_id != path2_transparent_descent_relation_id() {
        return Err("Path 2 transparent relation id mismatch".to_string());
    }
    let expected_transcript = path2_transparent_descent_transcript_digest(
        &public_view.proof_system_id,
        public_view.trace_rows,
        public_view.query_count,
        public_view.column_profile,
        &public_view.leaf_context_digest,
        &public_view.creation_proof_binding_digest,
        &public_view.matrix_domain_transcript_digest,
        &public_view.masked_projection,
        &public_view.aggregation_context_digest,
        &public_view.trace_commitment_root,
        &public_view.constraint_commitment_root,
        public_view.query_index,
    )?;
    if public_view.transparent_transcript_digest != expected_transcript {
        return Err("Path 2 transparent transcript digest mismatch".to_string());
    }
    Ok(())
}

pub fn path2_transparent_descent_public_view_digest(
    public_view: &Path2TransparentDescentPublicViewV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_descent_public_view(public_view)?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"proof_system_id", &public_view.proof_system_id);
    append_frame(&mut frame, b"relation_id", &public_view.relation_id);
    append_frame(
        &mut frame,
        b"trace_rows",
        &public_view.trace_rows.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"query_count",
        &public_view.query_count.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"column_profile",
        &public_view.column_profile.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"leaf_context_digest",
        &public_view.leaf_context_digest,
    );
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        &public_view.creation_proof_binding_digest,
    );
    append_frame(
        &mut frame,
        b"matrix_domain_transcript_digest",
        &public_view.matrix_domain_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"aggregation_context_digest",
        &public_view.aggregation_context_digest,
    );
    for value in public_view.masked_projection {
        append_frame(&mut frame, b"masked_projection", &value.to_le_bytes());
    }
    append_frame(
        &mut frame,
        b"trace_commitment_root",
        &public_view.trace_commitment_root,
    );
    append_frame(
        &mut frame,
        b"constraint_commitment_root",
        &public_view.constraint_commitment_root,
    );
    append_frame(
        &mut frame,
        b"query_index",
        &public_view.query_index.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"transparent_transcript_digest",
        &public_view.transparent_transcript_digest,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_descent_public_view_v1(
    proof_system_id: [u8; DIGEST_BYTES],
    trace_rows: u16,
    query_count: u16,
    column_profile: u16,
    leaf_context_digest: [u8; DIGEST_BYTES],
    creation_proof_binding_digest: [u8; DIGEST_BYTES],
    matrix_domain_transcript_digest: [u8; DIGEST_BYTES],
    masked_projection: [u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
    aggregation_context_digest: [u8; DIGEST_BYTES],
    trace_commitment_root: [u8; DIGEST_BYTES],
    constraint_commitment_root: [u8; DIGEST_BYTES],
    query_index: u16,
) -> Result<Path2TransparentDescentPublicViewV1, String> {
    let transparent_transcript_digest = path2_transparent_descent_transcript_digest(
        &proof_system_id,
        trace_rows,
        query_count,
        column_profile,
        &leaf_context_digest,
        &creation_proof_binding_digest,
        &matrix_domain_transcript_digest,
        &masked_projection,
        &aggregation_context_digest,
        &trace_commitment_root,
        &constraint_commitment_root,
        query_index,
    )?;
    Ok(Path2TransparentDescentPublicViewV1 {
        schema: PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA,
        proof_system_id,
        relation_id: path2_transparent_descent_relation_id(),
        trace_rows,
        query_count,
        column_profile,
        leaf_context_digest,
        creation_proof_binding_digest,
        matrix_domain_transcript_digest,
        aggregation_context_digest,
        masked_projection,
        trace_commitment_root,
        constraint_commitment_root,
        query_index,
        transparent_transcript_digest,
    })
}

