pub fn path2_transparent_proof_bytes_envelope_v1_bytes(
    public_view: &Path2TransparentDescentPublicViewV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
    merkle_paths_digest: &[u8; DIGEST_BYTES],
    consistency_messages_digest: &[u8; DIGEST_BYTES],
    proof_body: &[u8],
) -> Result<Vec<u8>, String> {
    if proof_body.is_empty() {
        return Err("Path 2 transparent proof body is empty".to_string());
    }
    if *merkle_paths_digest == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof merkle paths digest is zero".to_string());
    }
    if *consistency_messages_digest == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof consistency messages digest is zero".to_string());
    }
    verify_path2_transparent_query_opening_manifest_for_public_view(
        public_view,
        query_opening_manifest,
    )?;
    if proof_body.len() > u32::MAX as usize {
        return Err("Path 2 transparent proof body is too large".to_string());
    }
    if path2_transparent_proof_bytes_envelope_fixed_len() + proof_body.len()
        > PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as usize
    {
        return Err("Path 2 transparent proof bytes exceed active fallback threshold".to_string());
    }
    let mut bytes = Vec::new();
    bytes.extend_from_slice(PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA.as_bytes());
    bytes.extend_from_slice(&PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_VERSION.to_le_bytes());
    bytes.extend_from_slice(&public_view.proof_system_id);
    bytes.extend_from_slice(&public_view.relation_id);
    bytes.extend_from_slice(&path2_transparent_relation_layout_v1_digest()?);
    bytes.extend_from_slice(&public_view.transparent_transcript_digest);
    bytes.extend_from_slice(&path2_transparent_query_opening_manifest_digest(
        query_opening_manifest,
    )?);
    bytes.extend_from_slice(&public_view.column_profile.to_le_bytes());
    bytes.extend_from_slice(&public_view.trace_rows.to_le_bytes());
    bytes.extend_from_slice(&public_view.query_count.to_le_bytes());
    bytes.extend_from_slice(merkle_paths_digest);
    bytes.extend_from_slice(consistency_messages_digest);
    let proof_body_digest = path2_transparent_proof_body_digest(proof_body)?;
    bytes.extend_from_slice(&proof_body_digest);
    bytes.extend_from_slice(&(proof_body.len() as u32).to_le_bytes());
    bytes.extend_from_slice(proof_body);
    Ok(bytes)
}

pub fn path2_transparent_proof_body_digest(
    proof_body: &[u8],
) -> Result<[u8; DIGEST_BYTES], String> {
    if proof_body.is_empty() {
        return Err("Path 2 transparent proof body is empty".to_string());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_PROOF_BODY_DIGEST_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"proof_body_byte_len", proof_body.len() as u64);
    append_frame(&mut frame, b"proof_body", proof_body);
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_proof_bytes_digest(
    proof_bytes: &[u8],
) -> Result<[u8; DIGEST_BYTES], String> {
    if proof_bytes.is_empty() {
        return Err("Path 2 transparent proof bytes are empty".to_string());
    }
    if proof_bytes.len() > PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as usize {
        return Err("Path 2 transparent proof bytes exceed active fallback threshold".to_string());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"schema",
        PATH2_TRANSPARENT_PROOF_BYTES_DIGEST_SCHEMA.as_bytes(),
    );
    append_u64(&mut frame, b"proof_bytes_len", proof_bytes.len() as u64);
    append_frame(&mut frame, b"proof_bytes", proof_bytes);
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_proof_bytes_envelope_fixed_len() -> usize {
    PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA.len() + 2 + DIGEST_BYTES * 8 + 2 + 2 + 2 + 4
}

pub fn decode_path2_transparent_proof_bytes_envelope_v1(
    bytes: &[u8],
) -> Result<Path2TransparentProofBytesEnvelopeV1, String> {
    let schema = PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA.as_bytes();
    let fixed_len = path2_transparent_proof_bytes_envelope_fixed_len();
    if bytes.len() < fixed_len {
        return Err("Path 2 transparent proof bytes envelope is truncated".to_string());
    }
    if bytes.len() > PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as usize {
        return Err("Path 2 transparent proof bytes exceed active fallback threshold".to_string());
    }
    if &bytes[..schema.len()] != schema {
        return Err("Path 2 transparent proof bytes envelope schema mismatch".to_string());
    }
    let mut offset = schema.len();
    let version = u16::from_le_bytes(bytes[offset..offset + 2].try_into().unwrap());
    offset += 2;
    if version != PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_VERSION {
        return Err("Path 2 transparent proof bytes envelope version mismatch".to_string());
    }
    let proof_system_id: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let relation_id: [u8; DIGEST_BYTES] = bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let relation_layout_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let transparent_transcript_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let query_opening_manifest_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let column_profile = u16::from_le_bytes(bytes[offset..offset + 2].try_into().unwrap());
    offset += 2;
    let trace_rows = u16::from_le_bytes(bytes[offset..offset + 2].try_into().unwrap());
    offset += 2;
    let query_count = u16::from_le_bytes(bytes[offset..offset + 2].try_into().unwrap());
    offset += 2;
    let merkle_paths_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    if merkle_paths_digest == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof merkle paths digest is zero".to_string());
    }
    let consistency_messages_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    if consistency_messages_digest == [0_u8; DIGEST_BYTES] {
        return Err("Path 2 transparent proof consistency messages digest is zero".to_string());
    }
    let proof_body_digest: [u8; DIGEST_BYTES] =
        bytes[offset..offset + DIGEST_BYTES].try_into().unwrap();
    offset += DIGEST_BYTES;
    let proof_body_byte_len = u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap());
    offset += 4;
    if proof_body_byte_len == 0 {
        return Err("Path 2 transparent proof body is empty".to_string());
    }
    if bytes.len() != offset + proof_body_byte_len as usize {
        return Err("Path 2 transparent proof body length mismatch".to_string());
    }
    let actual_body_digest = path2_transparent_proof_body_digest(&bytes[offset..])?;
    if actual_body_digest != proof_body_digest {
        return Err("Path 2 transparent proof body digest mismatch".to_string());
    }
    Ok(Path2TransparentProofBytesEnvelopeV1 {
        schema: PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA,
        version,
        proof_system_id,
        relation_id,
        relation_layout_digest,
        transparent_transcript_digest,
        query_opening_manifest_digest,
        column_profile,
        trace_rows,
        query_count,
        merkle_paths_digest,
        consistency_messages_digest,
        proof_body_digest,
        proof_body_byte_len,
    })
}

pub fn verify_path2_transparent_proof_bytes_envelope_v1(
    public_view: &Path2TransparentDescentPublicViewV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
    merkle_paths_digest: &[u8; DIGEST_BYTES],
    consistency_messages_digest: &[u8; DIGEST_BYTES],
    proof_bytes: &[u8],
) -> Result<Path2TransparentProofBytesEnvelopeV1, String> {
    let envelope = decode_path2_transparent_proof_bytes_envelope_v1(proof_bytes)?;
    verify_path2_transparent_query_opening_manifest_for_public_view(
        public_view,
        query_opening_manifest,
    )?;
    if envelope.proof_system_id != public_view.proof_system_id
        || envelope.relation_id != public_view.relation_id
        || envelope.relation_layout_digest != path2_transparent_relation_layout_v1_digest()?
        || envelope.transparent_transcript_digest != public_view.transparent_transcript_digest
        || envelope.query_opening_manifest_digest
            != path2_transparent_query_opening_manifest_digest(query_opening_manifest)?
        || envelope.column_profile != public_view.column_profile
        || envelope.trace_rows != public_view.trace_rows
        || envelope.query_count != public_view.query_count
        || &envelope.merkle_paths_digest != merkle_paths_digest
        || &envelope.consistency_messages_digest != consistency_messages_digest
    {
        return Err("Path 2 transparent proof bytes envelope context mismatch".to_string());
    }
    Ok(envelope)
}

pub fn path2_prevalidated_slot_leaf_context_digest(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        PATH2_PREVALIDATED_SLOT_LEAF_CONTEXT_SCHEMA.as_bytes(),
    );
    append_frame(&mut frame, b"account_id", &leaf.account_id);
    append_frame(
        &mut frame,
        b"public_key_identity",
        &leaf.public_key_identity,
    );
    append_frame(&mut frame, b"slot_id", &leaf.slot_id.to_le_bytes());
    append_frame(
        &mut frame,
        b"verifier_version_digest",
        &leaf.verifier_version_digest,
    );
    append_frame(
        &mut frame,
        b"account_state_root_before",
        &leaf.account_state_root_before,
    );
    append_frame(&mut frame, b"lifecycle_anchor", &leaf.lifecycle_anchor);
    append_frame(
        &mut frame,
        b"live_status_marker",
        &[leaf.live_status_marker],
    );
    append_frame(
        &mut frame,
        b"hidden_source_statement_digest",
        &leaf.hidden_source_statement_digest,
    );
    append_frame(
        &mut frame,
        b"relation_transcript_digest",
        &certificate.relation_transcript_digest,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn path2_transparent_descent_proof_payload_digest(
    public_view: &Path2TransparentDescentPublicViewV1,
    payload_byte_len: u64,
    proof_bytes_digest: &[u8; DIGEST_BYTES],
    query_openings_digest: &[u8; DIGEST_BYTES],
    merkle_paths_digest: &[u8; DIGEST_BYTES],
    consistency_messages_digest: &[u8; DIGEST_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_transparent_descent_public_view(public_view)?;
    if payload_byte_len == 0 {
        return Err("Path 2 transparent descent payload length is zero".to_string());
    }
    if payload_byte_len > PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as u64 {
        return Err(
            "Path 2 transparent descent payload length exceeds active fallback threshold"
                .to_string(),
        );
    }
    for (label, digest) in [
        ("proof bytes", proof_bytes_digest),
        ("query openings", query_openings_digest),
        ("merkle paths", merkle_paths_digest),
        ("consistency messages", consistency_messages_digest),
    ] {
        if *digest == [0_u8; DIGEST_BYTES] {
            return Err(format!("Path 2 transparent descent {label} digest is zero"));
        }
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"payload_schema",
        PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"proof_kind",
        PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT as u64,
    );
    append_frame(
        &mut frame,
        b"transparent_transcript_digest",
        &public_view.transparent_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"transparent_public_view_digest",
        &path2_transparent_descent_public_view_digest(public_view)?,
    );
    append_frame(&mut frame, b"proof_system_id", &public_view.proof_system_id);
    append_frame(&mut frame, b"relation_id", &public_view.relation_id);
    append_frame(
        &mut frame,
        b"creation_proof_binding_digest",
        &public_view.creation_proof_binding_digest,
    );
    append_u64(&mut frame, b"payload_byte_len", payload_byte_len);
    append_frame(&mut frame, b"proof_bytes_digest", proof_bytes_digest);
    append_frame(&mut frame, b"query_openings_digest", query_openings_digest);
    append_frame(&mut frame, b"merkle_paths_digest", merkle_paths_digest);
    append_frame(
        &mut frame,
        b"consistency_messages_digest",
        consistency_messages_digest,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn path2_creation_hidden_source_statement_v1_frame(
    statement: &Path2CreationHiddenSourceStatementV1,
) -> Vec<u8> {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        PATH2_CREATION_HIDDEN_SOURCE_STATEMENT_DOMAIN.as_bytes(),
    );
    append_u64(&mut frame, b"frame_version", statement.frame_version as u64);
    append_frame(
        &mut frame,
        b"profile_version_digest",
        &statement.profile_version_digest,
    );
    append_frame(&mut frame, b"account_id", &statement.account_id);
    append_frame(
        &mut frame,
        b"public_key_identity",
        &statement.public_key_identity,
    );
    append_frame(&mut frame, b"slot_id", &statement.slot_id.to_le_bytes());
    append_frame(
        &mut frame,
        b"verifier_version_digest",
        &statement.verifier_version_digest,
    );
    append_frame(
        &mut frame,
        b"account_state_root_before",
        &statement.account_state_root_before,
    );
    append_frame(
        &mut frame,
        b"opening_commitment",
        &statement.opening_commitment,
    );
    append_frame(&mut frame, b"pad_seed_digest", &statement.pad_seed_digest);
    append_frame(&mut frame, b"lifecycle_anchor", &statement.lifecycle_anchor);
    append_frame(
        &mut frame,
        b"witness_commitment",
        &statement.witness_commitment,
    );
    append_frame(
        &mut frame,
        b"randomizer_commitment",
        &statement.randomizer_commitment,
    );
    append_frame(
        &mut frame,
        b"pad_opening_statement_digest",
        &statement.pad_opening_statement_digest,
    );
    append_u64(
        &mut frame,
        b"pad_observed_block_count",
        statement.pad_observed_block_count,
    );
    append_frame(
        &mut frame,
        b"pad_observed_bitmap",
        &statement.pad_observed_bitmap.to_le_bytes(),
    );
    append_frame(
        &mut frame,
        b"active_lane_profile_digest",
        &statement.active_lane_profile_digest,
    );
    append_frame(
        &mut frame,
        b"aggregation_context_digest",
        &statement.aggregation_context_digest,
    );
    frame
}

fn path2_pad_observed_bitmap(observed_blocks: &[bool; GROUPS]) -> u16 {
    let mut observed_bitmap = 0_u16;
    for (block, &observed) in observed_blocks.iter().enumerate() {
        if observed {
            observed_bitmap |= 1_u16 << block;
        }
    }
    observed_bitmap
}

pub fn path2_prevalidated_slot_leaf_v1_bytes(
    leaf: &Path2PrevalidatedSlotLeafV1,
) -> Result<[u8; PATH2_PREVALIDATED_SLOT_LEAF_V1_BYTES], String> {
    if PATH2_PREVALIDATED_SLOT_LEAF_DOMAIN.len() != 22 {
        return Err("Path 2 slot leaf domain length mismatch".to_string());
    }
    if leaf.frame_version != PATH2_PREVALIDATED_SLOT_LEAF_FRAME_VERSION {
        return Err("Path 2 slot leaf frame version mismatch".to_string());
    }
    if leaf.live_status_marker != PATH2_PREVALIDATED_SLOT_LIVE_STATUS_MARKER {
        return Err("Path 2 slot leaf is not live".to_string());
    }

    let mut out = [0_u8; PATH2_PREVALIDATED_SLOT_LEAF_V1_BYTES];
    let mut offset = 0;
    out[offset..offset + PATH2_PREVALIDATED_SLOT_LEAF_DOMAIN.len()]
        .copy_from_slice(PATH2_PREVALIDATED_SLOT_LEAF_DOMAIN.as_bytes());
    offset += PATH2_PREVALIDATED_SLOT_LEAF_DOMAIN.len();
    out[offset..offset + 2].copy_from_slice(&leaf.frame_version.to_le_bytes());
    offset += 2;
    for digest in [
        &leaf.profile_version_digest,
        &leaf.account_id,
        &leaf.public_key_identity,
    ] {
        out[offset..offset + DIGEST_BYTES].copy_from_slice(digest);
        offset += DIGEST_BYTES;
    }
    out[offset..offset + 8].copy_from_slice(&leaf.slot_id.to_le_bytes());
    offset += 8;
    for digest in [
        &leaf.verifier_version_digest,
        &leaf.account_state_root_before,
        &leaf.opening_commitment,
        &leaf.pad_seed_digest,
        &leaf.hidden_source_statement_digest,
        &leaf.prevalidation_transcript_digest,
        &leaf.lifecycle_anchor,
    ] {
        out[offset..offset + DIGEST_BYTES].copy_from_slice(digest);
        offset += DIGEST_BYTES;
    }
    out[offset] = leaf.live_status_marker;
    offset += 1;
    debug_assert_eq!(offset, PATH2_PREVALIDATED_SLOT_LEAF_V1_BYTES);
    Ok(out)
}

pub fn path2_prevalidated_slot_leaf_digest(
    leaf: &Path2PrevalidatedSlotLeafV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_prevalidated_slot_leaf_v1_bytes(leaf)?).into())
}

pub fn path2_prevalidated_slot_leaf_v2_from_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    creation_proof_binding_digest: [u8; DIGEST_BYTES],
) -> Path2PrevalidatedSlotLeafV2 {
    Path2PrevalidatedSlotLeafV2 {
        frame_version: leaf.frame_version,
        profile_version_digest: leaf.profile_version_digest,
        account_id: leaf.account_id,
        public_key_identity: leaf.public_key_identity,
        slot_id: leaf.slot_id,
        verifier_version_digest: leaf.verifier_version_digest,
        account_state_root_before: leaf.account_state_root_before,
        opening_commitment: leaf.opening_commitment,
        pad_seed_digest: leaf.pad_seed_digest,
        hidden_source_statement_digest: leaf.hidden_source_statement_digest,
        prevalidation_transcript_digest: leaf.prevalidation_transcript_digest,
        lifecycle_anchor: leaf.lifecycle_anchor,
        creation_proof_binding_digest,
        live_status_marker: leaf.live_status_marker,
    }
}

pub fn path2_prevalidated_slot_leaf_v2_bytes(
    leaf: &Path2PrevalidatedSlotLeafV2,
) -> Result<[u8; PATH2_PREVALIDATED_SLOT_LEAF_V2_BYTES], String> {
    if PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.len() != 22 {
        return Err("Path 2 slot leaf v2 domain length mismatch".to_string());
    }
    if leaf.frame_version != PATH2_PREVALIDATED_SLOT_LEAF_FRAME_VERSION {
        return Err("Path 2 slot leaf v2 frame version mismatch".to_string());
    }
    if leaf.live_status_marker != PATH2_PREVALIDATED_SLOT_LIVE_STATUS_MARKER {
        return Err("Path 2 slot leaf v2 is not live".to_string());
    }

    let mut out = [0_u8; PATH2_PREVALIDATED_SLOT_LEAF_V2_BYTES];
    let mut offset = 0;
    out[offset..offset + PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.len()]
        .copy_from_slice(PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.as_bytes());
    offset += PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.len();
    out[offset..offset + 2].copy_from_slice(&leaf.frame_version.to_le_bytes());
    offset += 2;
    for digest in [
        &leaf.profile_version_digest,
        &leaf.account_id,
        &leaf.public_key_identity,
    ] {
        out[offset..offset + DIGEST_BYTES].copy_from_slice(digest);
        offset += DIGEST_BYTES;
    }
    out[offset..offset + 8].copy_from_slice(&leaf.slot_id.to_le_bytes());
    offset += 8;
    for digest in [
        &leaf.verifier_version_digest,
        &leaf.account_state_root_before,
        &leaf.opening_commitment,
        &leaf.pad_seed_digest,
        &leaf.hidden_source_statement_digest,
        &leaf.prevalidation_transcript_digest,
        &leaf.lifecycle_anchor,
        &leaf.creation_proof_binding_digest,
    ] {
        out[offset..offset + DIGEST_BYTES].copy_from_slice(digest);
        offset += DIGEST_BYTES;
    }
    out[offset] = leaf.live_status_marker;
    offset += 1;
    debug_assert_eq!(offset, PATH2_PREVALIDATED_SLOT_LEAF_V2_BYTES);
    Ok(out)
}

pub fn path2_prevalidated_slot_leaf_v2_digest(
    leaf: &Path2PrevalidatedSlotLeafV2,
) -> Result<[u8; DIGEST_BYTES], String> {
    Ok(Sha256::digest(path2_prevalidated_slot_leaf_v2_bytes(leaf)?).into())
}

pub fn path2_slot_authorization_digest(
    leaf: &Path2PrevalidatedSlotLeafV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    if PATH2_SLOT_AUTHORIZATION_DOMAIN.len() != 31 {
        return Err("Path 2 slot authorization domain length mismatch".to_string());
    }
    let leaf_bytes = path2_prevalidated_slot_leaf_v1_bytes(leaf)?;
    let mut hasher = Sha256::new();
    hasher.update(PATH2_SLOT_AUTHORIZATION_DOMAIN.as_bytes());
    hasher.update(leaf_bytes);
    Ok(hasher.finalize().into())
}

pub fn path2_slot_authorization_v2_digest(
    leaf: &Path2PrevalidatedSlotLeafV2,
) -> Result<[u8; DIGEST_BYTES], String> {
    if PATH2_SLOT_AUTHORIZATION_V2_DOMAIN.len() != 31 {
        return Err("Path 2 slot authorization v2 domain length mismatch".to_string());
    }
    let leaf_bytes = path2_prevalidated_slot_leaf_v2_bytes(leaf)?;
    let mut hasher = Sha256::new();
    hasher.update(PATH2_SLOT_AUTHORIZATION_V2_DOMAIN.as_bytes());
    hasher.update(leaf_bytes);
    Ok(hasher.finalize().into())
}

pub fn path2_account_creation_evidence_transcript_digest(
    evidence: &Path2AccountCreationEvidenceV1,
) -> Result<[u8; DIGEST_BYTES], String> {
    if evidence.evidence_domain != PATH2_SLOT_PREVALIDATE_SINGLE_DOMAIN {
        return Err("Path 2 evidence domain mismatch".to_string());
    }
    if evidence.evidence_version != 1 {
        return Err("Path 2 evidence version mismatch".to_string());
    }
    if evidence.evidence_kind != PATH2_EVIDENCE_KIND_DIRECT_REPLAYABLE_RELATION_CERTIFICATE {
        return Err("Path 2 unsupported evidence kind".to_string());
    }
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"evidence_domain",
        evidence.evidence_domain.as_bytes(),
    );
    append_u64(
        &mut frame,
        b"evidence_version",
        evidence.evidence_version as u64,
    );
    append_u64(&mut frame, b"evidence_kind", evidence.evidence_kind as u64);
    append_frame(
        &mut frame,
        b"creation_verifier_version_digest",
        &evidence.creation_verifier_version_digest,
    );
    append_frame(
        &mut frame,
        b"hidden_source_statement_digest",
        &evidence.hidden_source_statement_digest,
    );
    append_frame(
        &mut frame,
        b"opening_commitment",
        &evidence.opening_commitment,
    );
    append_frame(&mut frame, b"pad_seed_digest", &evidence.pad_seed_digest);
    append_frame(
        &mut frame,
        b"account_identity_digest",
        &evidence.account_identity_digest,
    );
    append_frame(
        &mut frame,
        b"public_key_identity",
        &evidence.public_key_identity,
    );
    append_frame(&mut frame, b"slot_id", &evidence.slot_id.to_le_bytes());
    append_frame(
        &mut frame,
        b"state_root_before",
        &evidence.state_root_before,
    );
    append_frame(&mut frame, b"lifecycle_anchor", &evidence.lifecycle_anchor);
    append_frame(
        &mut frame,
        b"relation_transcript_digest",
        &evidence.relation_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"evidence_payload_digest",
        &evidence.evidence_payload_digest,
    );
    Ok(Sha256::digest(frame).into())
}

pub fn path2_direct_replayable_relation_certificate_digest(
    certificate: &Path2DirectReplayableRelationCertificateV1,
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"evidence_domain",
        PATH2_SLOT_PREVALIDATE_SINGLE_DOMAIN.as_bytes(),
    );
    append_frame(
        &mut frame,
        b"certificate_kind",
        b"direct_replayable_relation",
    );
    append_frame(&mut frame, b"account_id", &certificate.account_id);
    append_frame(
        &mut frame,
        b"public_key_identity",
        &certificate.public_key_identity,
    );
    append_frame(&mut frame, b"slot_id", &certificate.slot_id.to_le_bytes());
    append_frame(
        &mut frame,
        b"verifier_version_digest",
        &certificate.verifier_version_digest,
    );
    append_frame(
        &mut frame,
        b"account_state_root_before",
        &certificate.account_state_root_before,
    );
    append_frame(
        &mut frame,
        b"opening_commitment",
        &certificate.opening_commitment,
    );
    append_frame(&mut frame, b"pad_seed_digest", &certificate.pad_seed_digest);
    append_frame(
        &mut frame,
        b"hidden_source_statement_digest",
        &certificate.hidden_source_statement_digest,
    );
    append_frame(
        &mut frame,
        b"reviewed_active_lane_statement_digest",
        &certificate.reviewed_active_lane_statement_digest,
    );
    append_frame(
        &mut frame,
        b"lifecycle_anchor",
        &certificate.lifecycle_anchor,
    );
    append_frame(
        &mut frame,
        b"relation_transcript_digest",
        &certificate.relation_transcript_digest,
    );
    append_frame(
        &mut frame,
        b"public_replay_payload_digest",
        &certificate.public_replay_payload_digest,
    );
    Sha256::digest(frame).into()
}

pub fn verify_path2_prevalidated_slot_creation_frame_bindings(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
) -> Result<(), String> {
    let slot_leaf_digest = path2_prevalidated_slot_leaf_digest(leaf)?;
    if evidence.slot_leaf_digest != slot_leaf_digest {
        return Err("Path 2 slot leaf digest mismatch".to_string());
    }
    let slot_authorization_digest = path2_slot_authorization_digest(leaf)?;
    if evidence.slot_authorization_digest != slot_authorization_digest {
        return Err("Path 2 slot authorization digest mismatch".to_string());
    }
    if evidence.creation_verifier_version_digest != leaf.verifier_version_digest {
        return Err("Path 2 creation verifier version mismatch".to_string());
    }
    if evidence.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 hidden-source statement digest mismatch".to_string());
    }
    if evidence.opening_commitment != leaf.opening_commitment {
        return Err("Path 2 opening commitment mismatch".to_string());
    }
    if evidence.pad_seed_digest != leaf.pad_seed_digest {
        return Err("Path 2 pad-seed digest mismatch".to_string());
    }
    if evidence.account_identity_digest != leaf.account_id {
        return Err("Path 2 account id mismatch".to_string());
    }
    if evidence.public_key_identity != leaf.public_key_identity {
        return Err("Path 2 public-key identity mismatch".to_string());
    }
    if evidence.slot_id != leaf.slot_id {
        return Err("Path 2 slot id mismatch".to_string());
    }
    if evidence.state_root_before != leaf.account_state_root_before {
        return Err("Path 2 account state root mismatch".to_string());
    }
    if evidence.lifecycle_anchor != leaf.lifecycle_anchor {
        return Err("Path 2 lifecycle anchor mismatch".to_string());
    }
    if path2_account_creation_evidence_transcript_digest(evidence)?
        != leaf.prevalidation_transcript_digest
    {
        return Err("Path 2 prevalidation transcript digest mismatch".to_string());
    }
    Ok(())
}

pub fn verify_path2_prevalidated_slot_creation_payload_bindings(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: Option<&Path2DirectReplayableRelationCertificateV1>,
) -> Result<(), String> {
    verify_path2_prevalidated_slot_creation_frame_bindings(leaf, evidence)?;
    let certificate =
        certificate.ok_or_else(|| "Path 2 evidence payload unavailable".to_string())?;
    if path2_direct_replayable_relation_certificate_digest(certificate)
        != evidence.evidence_payload_digest
    {
        return Err("Path 2 evidence payload digest mismatch".to_string());
    }
    if certificate.account_id != leaf.account_id {
        return Err("Path 2 certificate account id mismatch".to_string());
    }
    if certificate.public_key_identity != leaf.public_key_identity {
        return Err("Path 2 certificate public-key identity mismatch".to_string());
    }
    if certificate.slot_id != leaf.slot_id {
        return Err("Path 2 certificate slot id mismatch".to_string());
    }
    if certificate.verifier_version_digest != leaf.verifier_version_digest {
        return Err("Path 2 certificate verifier version mismatch".to_string());
    }
    if certificate.account_state_root_before != leaf.account_state_root_before {
        return Err("Path 2 certificate account state root mismatch".to_string());
    }
    if certificate.opening_commitment != leaf.opening_commitment {
        return Err("Path 2 certificate opening commitment mismatch".to_string());
    }
    if certificate.pad_seed_digest != leaf.pad_seed_digest {
        return Err("Path 2 certificate pad-seed digest mismatch".to_string());
    }
    if certificate.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 certificate hidden-source statement mismatch".to_string());
    }
    if certificate.lifecycle_anchor != leaf.lifecycle_anchor {
        return Err("Path 2 certificate lifecycle anchor mismatch".to_string());
    }
    if certificate.relation_transcript_digest != evidence.relation_transcript_digest {
        return Err("Path 2 certificate relation transcript mismatch".to_string());
    }
    Ok(())
}

pub fn verify_path2_prevalidated_slot_admission_namespace(
    leaves: &[Path2PrevalidatedSlotLeafV1],
) -> Result<(), String> {
    let mut account_slots = BTreeSet::new();
    let mut pad_seed_digests = BTreeSet::new();
    for leaf in leaves {
        path2_prevalidated_slot_leaf_v1_bytes(leaf)?;
        if !account_slots.insert((leaf.account_id, leaf.slot_id)) {
            return Err("Path 2 duplicate account slot admission".to_string());
        }
        if !pad_seed_digests.insert(leaf.pad_seed_digest) {
            return Err("Path 2 duplicate pad-seed digest admission".to_string());
        }
    }
    Ok(())
}

pub fn verify_path2_prevalidated_slot_consume_once(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    consumed_authorizations: &mut BTreeSet<[u8; DIGEST_BYTES]>,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    let authorization = path2_slot_authorization_digest(leaf)?;
    if !consumed_authorizations.insert(authorization) {
        return Err("Path 2 slot authorization already consumed".to_string());
    }
    Ok(authorization)
}

pub fn verify_path2_prevalidated_slot_creation_relation_replay(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature_with_carrier: &ProductionSignature,
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<(), ProductionAccountBindingError> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))
        .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let public_key_identity: [u8; DIGEST_BYTES] = Sha256::digest(public_key.as_bytes()).into();
    if leaf.public_key_identity != public_key_identity {
        return Err(ProductionAccountBindingError::new(
            None,
            "Path 2 relation replay public-key identity mismatch",
        ));
    }
    let reviewed_certificate =
        verify_reviewed_fq12_state_assisted_masked_projection_soundness_certificate(
            public_key,
            message,
            account,
            signature_with_carrier,
            opening,
            statement,
            pad_seed,
        )?;
    let creation_statement =
        path2_creation_hidden_source_statement_v1_from_reviewed(leaf, statement);
    if creation_statement.digest != leaf.hidden_source_statement_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 creation statement digest mismatch",
        ));
    }
    if reviewed_certificate.slot_id as u64 != leaf.slot_id {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay slot id mismatch",
        ));
    }
    if reviewed_certificate.statement_digest != certificate.reviewed_active_lane_statement_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay reviewed statement digest mismatch",
        ));
    }
    if reviewed_certificate.opening_commitment != leaf.opening_commitment {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay opening commitment mismatch",
        ));
    }
    if reviewed_certificate.pad_seed_digest != leaf.pad_seed_digest {
        return Err(ProductionAccountBindingError::new(
            Some(reviewed_certificate.slot_id),
            "Path 2 relation replay pad-seed digest mismatch",
        ));
    }
    Ok(())
}

fn verify_path2_direct_creation_proof_payload_common(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
) -> Result<(), String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    if binding.schema != PATH2_CREATION_PROOF_BINDING_SCHEMA {
        return Err("Path 2 creation proof binding schema mismatch".to_string());
    }
    if binding.proof_binding_version != 1 {
        return Err("Path 2 creation proof binding version mismatch".to_string());
    }
    if binding.digest != path2_creation_proof_binding_v1_digest(binding) {
        return Err("Path 2 creation proof binding digest mismatch".to_string());
    }
    if binding.account_id != leaf.account_id
        || binding.public_key_identity != leaf.public_key_identity
        || binding.slot_id != leaf.slot_id
        || binding.verifier_version_digest != leaf.verifier_version_digest
        || binding.account_state_root_before != leaf.account_state_root_before
        || binding.lifecycle_anchor != leaf.lifecycle_anchor
        || binding.opening_tuple_commitment != leaf.opening_commitment
        || binding.creation_statement_digest != leaf.hidden_source_statement_digest
    {
        return Err("Path 2 creation proof binding leaf context mismatch".to_string());
    }
    if payload.schema != PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA {
        return Err("Path 2 direct creation proof payload schema mismatch".to_string());
    }
    if payload.payload_version != 1 {
        return Err("Path 2 direct creation proof payload version mismatch".to_string());
    }
    if payload.proof_binding_digest != binding.digest {
        return Err("Path 2 direct creation proof binding digest mismatch".to_string());
    }
    if payload.hidden_source_statement_digest != leaf.hidden_source_statement_digest {
        return Err("Path 2 direct creation proof statement mismatch".to_string());
    }
    if payload.relation_transcript_digest != certificate.relation_transcript_digest {
        return Err("Path 2 direct creation proof transcript mismatch".to_string());
    }
    if payload.payload_digest != certificate.public_replay_payload_digest {
        return Err("Path 2 direct creation proof payload digest mismatch".to_string());
    }
    Ok(())
}

pub fn verify_path2_direct_creation_proof_payload_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind == PATH2_DIRECT_CREATION_PROOF_KIND_UNINSTANTIATED {
        return Err("Path 2 direct creation proof payload verifier is not implemented".to_string());
    }
    if payload.proof_kind == PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT {
        return Err("Path 2 transparent descent proof verifier is not implemented".to_string());
    }
    Err("Path 2 direct creation proof payload kind is unsupported".to_string())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
) -> Result<(), String> {
    verify_path2_direct_creation_proof_payload_common(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
    )?;
    if payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT {
        return Err("Path 2 transparent descent payload kind mismatch".to_string());
    }
    if payload.proof_system_id != path2_transparent_descent_proof_system_id() {
        return Err("Path 2 transparent descent proof system mismatch".to_string());
    }
    if transparent_payload.payload_digest != payload.payload_digest
        || transparent_payload.payload_byte_len != payload.payload_byte_len
    {
        return Err("Path 2 transparent descent payload header mismatch".to_string());
    }
    let view = &transparent_payload.public_view;
    if view.creation_proof_binding_digest != binding.digest {
        return Err("Path 2 transparent descent binding digest mismatch".to_string());
    }
    if view.leaf_context_digest
        != path2_prevalidated_slot_leaf_context_digest(leaf, evidence, certificate)?
    {
        return Err("Path 2 transparent descent leaf context mismatch".to_string());
    }
    if view.aggregation_context_digest != binding.aggregation_context_digest {
        return Err("Path 2 transparent descent aggregation context mismatch".to_string());
    }
    path2_transparent_commitment_api_v1(view, binding)?;
    let expected_payload_digest = path2_transparent_descent_proof_payload_digest(
        view,
        transparent_payload.payload_byte_len,
        &transparent_payload.proof_bytes_digest,
        &transparent_payload.query_openings_digest,
        &transparent_payload.merkle_paths_digest,
        &transparent_payload.consistency_messages_digest,
    )?;
    if transparent_payload.payload_digest != expected_payload_digest {
        return Err("Path 2 transparent descent payload digest mismatch".to_string());
    }
    Err("Path 2 transparent descent proof verifier is not implemented".to_string())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
) -> Result<(), String> {
    match verify_path2_direct_creation_transparent_descent_payload_boundary(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        transparent_payload,
    ) {
        Err(err) if err == "Path 2 transparent descent proof verifier is not implemented" => {}
        result => return result,
    }
    let view = &transparent_payload.public_view;
    verify_path2_transparent_query_opening_manifest_for_public_view(view, query_opening_manifest)?;
    if path2_transparent_query_opening_manifest_digest(query_opening_manifest)?
        != transparent_payload.query_openings_digest
    {
        return Err(
            "Path 2 transparent descent query opening manifest digest mismatch".to_string(),
        );
    }
    Err("Path 2 transparent descent proof verifier is not implemented".to_string())
}

pub fn verify_path2_direct_creation_transparent_descent_payload_boundary_with_proof_bytes(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    transparent_payload: &Path2TransparentDescentProofPayloadV1,
    query_opening_manifest: &Path2TransparentQueryOpeningManifestV1,
    proof_bytes: &[u8],
) -> Result<(), String> {
    match verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
        leaf,
        evidence,
        certificate,
        binding,
        payload,
        transparent_payload,
        query_opening_manifest,
    ) {
        Err(err) if err == "Path 2 transparent descent proof verifier is not implemented" => {}
        result => return result,
    }
    let proof_bytes_digest = path2_transparent_proof_bytes_digest(proof_bytes)?;
    if proof_bytes_digest != transparent_payload.proof_bytes_digest {
        return Err("Path 2 transparent descent proof bytes digest mismatch".to_string());
    }
    if transparent_payload.payload_byte_len != proof_bytes.len() as u64 {
        return Err("Path 2 transparent descent proof bytes length mismatch".to_string());
    }
    verify_path2_transparent_proof_bytes_envelope_v1(
        &transparent_payload.public_view,
        query_opening_manifest,
        &transparent_payload.merkle_paths_digest,
        &transparent_payload.consistency_messages_digest,
        proof_bytes,
    )?;
    Err("Path 2 transparent descent proof verifier is not implemented".to_string())
}

pub fn verify_path2_direct_creation_toy_q_linear_proof_v1(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    binding: &Path2CreationProofBindingV1,
    payload: &Path2DirectCreationProofPayloadV1,
    proof: &Path2ToyQLinearCreationProofV1,
) -> Result<(), String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    if payload.schema != PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA
        || payload.payload_version != 1
        || payload.proof_kind != PATH2_DIRECT_CREATION_PROOF_KIND_TOY_Q_LINEAR
    {
        return Err("Path 2 toy q-linear payload header mismatch".to_string());
    }
    if payload.proof_binding_digest != binding.digest {
        return Err("Path 2 toy q-linear binding digest mismatch".to_string());
    }
    if payload.hidden_source_statement_digest != leaf.hidden_source_statement_digest
        || payload.relation_transcript_digest != certificate.relation_transcript_digest
        || payload.payload_digest != certificate.public_replay_payload_digest
    {
        return Err("Path 2 toy q-linear payload binding mismatch".to_string());
    }
    if binding.digest != path2_creation_proof_binding_v1_digest(binding) {
        return Err("Path 2 toy q-linear binding digest is noncanonical".to_string());
    }
    if binding.account_id != leaf.account_id
        || binding.public_key_identity != leaf.public_key_identity
        || binding.slot_id != leaf.slot_id
        || binding.verifier_version_digest != leaf.verifier_version_digest
        || binding.account_state_root_before != leaf.account_state_root_before
        || binding.lifecycle_anchor != leaf.lifecycle_anchor
        || binding.opening_tuple_commitment != leaf.opening_commitment
        || binding.creation_statement_digest != leaf.hidden_source_statement_digest
    {
        return Err("Path 2 toy q-linear binding leaf context mismatch".to_string());
    }
    let residues = unpack_reviewed_fq12_packed_witness_state18(&binding.packed_witness_commitment)
        .map_err(|err| format!("Path 2 toy q-linear packed witness opening: {err}"))?;
    let mut masked_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
    for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        masked_projection[lane] =
            residues[REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET + lane];
    }
    let pad_commitment = path2_toy_q_linear_commitment_value_from_bytes(
        &binding.pad_source_commitment,
        PATH2_TOY_Q_COMMITMENT_ROLE_PAD_SOURCE,
    )?;
    let projection_commitment = path2_toy_q_linear_commitment_value_from_bytes(
        &binding.projection_relation_commitment,
        PATH2_TOY_Q_COMMITMENT_ROLE_PROJECTION_RELATION,
    )?;
    for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        if proof.pad_lane_responses[lane] >= Q || proof.projection_lane_responses[lane] >= Q {
            return Err("Path 2 toy q-linear proof response is noncanonical".to_string());
        }
    }
    if proof.pad_blinding_response >= Q
        || proof.projection_blinding_response >= Q
        || proof.pad_commitment_nonce >= Q
        || proof.projection_commitment_nonce >= Q
    {
        return Err("Path 2 toy q-linear proof scalar is noncanonical".to_string());
    }
    let challenge = path2_toy_q_linear_challenge(leaf, binding, payload, proof, &masked_projection);
    for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
        let lhs = add_mod(
            proof.pad_lane_responses[lane],
            proof.projection_lane_responses[lane],
        );
        let rhs = ((challenge as u32 * masked_projection[lane] as u32) % Q as u32) as u16;
        if lhs != rhs {
            return Err("Path 2 toy q-linear masked projection relation mismatch".to_string());
        }
    }
    let pad_response_commitment = path2_toy_q_linear_commitment_value(
        PATH2_TOY_Q_COMMITMENT_ROLE_PAD_SOURCE,
        &proof.pad_lane_responses,
        proof.pad_blinding_response,
    )?;
    let expected_pad = add_mod(
        proof.pad_commitment_nonce,
        ((challenge as u32 * pad_commitment as u32) % Q as u32) as u16,
    );
    if pad_response_commitment != expected_pad {
        return Err("Path 2 toy q-linear pad commitment equation mismatch".to_string());
    }
    let projection_response_commitment = path2_toy_q_linear_commitment_value(
        PATH2_TOY_Q_COMMITMENT_ROLE_PROJECTION_RELATION,
        &proof.projection_lane_responses,
        proof.projection_blinding_response,
    )?;
    let expected_projection = add_mod(
        proof.projection_commitment_nonce,
        ((challenge as u32 * projection_commitment as u32) % Q as u32) as u16,
    );
    if projection_response_commitment != expected_projection {
        return Err("Path 2 toy q-linear projection commitment equation mismatch".to_string());
    }
    Ok(())
}

pub fn validate_path2_direct_slot_authorization_admission(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    admitted_authorizations: &BTreeSet<[u8; DIGEST_BYTES]>,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    let authorization = path2_slot_authorization_digest(leaf)?;
    if !admitted_authorizations.contains(&authorization) {
        return Err("Path 2 slot authorization was not admitted".to_string());
    }
    Ok(authorization)
}

pub fn validate_path2_direct_slot_authorization_state_namespace(
    leaf: &Path2PrevalidatedSlotLeafV1,
    evidence: &Path2AccountCreationEvidenceV1,
    certificate: &Path2DirectReplayableRelationCertificateV1,
    admitted_state_authorizations: &BTreeSet<(
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
        [u8; DIGEST_BYTES],
    )>,
) -> Result<[u8; DIGEST_BYTES], String> {
    verify_path2_prevalidated_slot_creation_payload_bindings(leaf, evidence, Some(certificate))?;
    let authorization = path2_slot_authorization_digest(leaf)?;
    let namespace = (
        leaf.account_id,
        leaf.account_state_root_before,
        authorization,
    );
    if !admitted_state_authorizations.contains(&namespace) {
        return Err("Path 2 slot authorization was not admitted in state namespace".to_string());
    }
    Ok(authorization)
}

