pub fn path2_native_signer_pipeline_public_output_v1(
    bundle: &Path2NativeProjectionBundleV1,
    checked_core_proof_bytes: &[u8],
) -> Result<Path2NativeSignerPipelinePublicOutputV1, String> {
    let assembly = assemble_path2_native_boundary_v1(bundle, checked_core_proof_bytes)?;
    let projection_preimage_da_digest = path2_native_projection_preimage_da_digest_v1(bundle)?;
    let carrier =
        path2_native_consensus_carrier_v1_from_assembly(&assembly, projection_preimage_da_digest);
    let carrier_digest = path2_native_consensus_carrier_v1_digest(&carrier)?;
    let core_proof_digest: [u8; DIGEST_BYTES] = Sha256::digest(checked_core_proof_bytes).into();
    let core_proof_len = u16::try_from(checked_core_proof_bytes.len())
        .map_err(|_| "Path 2 native core proof too large for signer public output".to_string())?;
    let deployment_preflight = path2_native_deployment_preflight_v1();
    let signer_pipeline_ready = deployment_preflight.signer_verifier_pipeline_present
        && deployment_preflight.constant_time_audit_complete;
    let rejection_code = if signer_pipeline_ready {
        None
    } else {
        Some("reject_active_native_signer_not_productized")
    };

    Ok(Path2NativeSignerPipelinePublicOutputV1 {
        schema: PATH2_NATIVE_SIGNER_PIPELINE_PUBLIC_OUTPUT_SCHEMA,
        signer_pipeline_ready,
        rejection_code,
        carrier,
        carrier_digest,
        core_proof_digest,
        core_proof_len,
        projection_preimage_da_digest,
        native_boundary_digest: assembly.native_boundary_digest,
        p_transcript_digest: assembly.p_transcript_digest,
        deployment_preflight,
    })
}

