pub fn path2_native_signer_rejection_cleanup_audit_v1(
    success_report: &Path2NativeSignerExecutionReportV1,
    constructor_rejection_report: &Path2NativeSignerExecutionReportV1,
    entropy_rejection_report: &Path2NativeSignerExecutionReportV1,
) -> Result<Path2NativeSignerRejectionCleanupAuditV1, String> {
    let success_report_digest = path2_native_signer_execution_report_v1_digest(success_report)?;
    let constructor_rejection_report_digest =
        path2_native_signer_execution_report_v1_digest(constructor_rejection_report)?;
    let entropy_rejection_report_digest =
        path2_native_signer_execution_report_v1_digest(entropy_rejection_report)?;
    let all_rejection_digests_absent =
        path2_native_signer_execution_report_has_no_private_digests_v1(
            constructor_rejection_report,
        ) && path2_native_signer_execution_report_has_no_private_digests_v1(
            entropy_rejection_report,
        );
    let all_rejection_codes_public_only =
        path2_native_signer_rejection_code_is_public_v1(success_report.rejection_code)
            && path2_native_signer_rejection_code_is_public_v1(
                constructor_rejection_report.rejection_code,
            )
            && path2_native_signer_rejection_code_is_public_v1(
                entropy_rejection_report.rejection_code,
            );
    let success_rendered = serde_json::to_string(success_report)
        .map_err(|err| format!("encode signer success cleanup report: {err}"))?;
    let constructor_rendered = serde_json::to_string(constructor_rejection_report)
        .map_err(|err| format!("encode signer constructor rejection cleanup report: {err}"))?;
    let entropy_rendered = serde_json::to_string(entropy_rejection_report)
        .map_err(|err| format!("encode signer entropy rejection cleanup report: {err}"))?;
    let all_reports_private_material_absent =
        path2_native_public_report_excludes_private_material_v1(&success_rendered)
            && path2_native_public_report_excludes_private_material_v1(&constructor_rendered)
            && path2_native_public_report_excludes_private_material_v1(&entropy_rendered);
    let public_error_surface_complete = success_report.schema
        == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && constructor_rejection_report.schema == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && entropy_rejection_report.schema == PATH2_NATIVE_SIGNER_EXECUTION_REPORT_SCHEMA
        && constructor_rejection_report.rejection_code
            == Some("reject_active_native_signer_constructor_failed")
        && entropy_rejection_report.rejection_code
            == Some("reject_active_native_signer_entropy_failed")
        && all_rejection_digests_absent
        && all_rejection_codes_public_only
        && all_reports_private_material_absent;

    Ok(Path2NativeSignerRejectionCleanupAuditV1 {
        schema: PATH2_NATIVE_SIGNER_REJECTION_CLEANUP_AUDIT_SCHEMA,
        audit_complete: false,
        public_error_surface_complete,
        cleanup_zeroization_claim_complete: false,
        success_report_digest,
        constructor_rejection_report_digest,
        entropy_rejection_report_digest,
        constructor_rejection_code: constructor_rejection_report.rejection_code,
        entropy_rejection_code: entropy_rejection_report.rejection_code,
        all_rejection_digests_absent,
        all_rejection_codes_public_only,
        all_reports_private_material_absent,
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        deployment_preflight: path2_native_deployment_preflight_v1(),
        explicit_non_claims: [
            "public report cleanup is not whole-signer timing evidence",
            "public report cleanup is not allocator memory inspection",
            "public report cleanup is not operating-system entropy validation",
        ],
    })
}

