pub fn path2_native_signer_sha256_boundary_audit_v1() -> Path2NativeSignerSha256BoundaryAuditV1 {
    let digest_source = path2_native_signer_entropy_digest_source_window_v1();
    let derivation_source = path2_native_secret_material_derivation_source_window_v1();
    let public_binding_words = derivation_source
        .matches("public_binding.extend_from_slice")
        .count();
    let derivation_labels_are_static_public = derivation_source
        .contains("b\"authorization_local_seed\"")
        && derivation_source.contains("b\"gauge_seed\"")
        && derivation_source.contains("b\"randomizer_seed\"")
        && derivation_source.contains("b\"wallet_recovery_seed\"")
        && derivation_source.contains("b\"proof_randomizer_syndrome\"");
    let q_sampler_fixed_digest_call_schedule = derivation_source
        .contains("for (idx, value) in proof_randomizer_syndrome")
        && digest_source.contains("counter")
        && path2_native_signer_entropy_q_source_window_v1()
            .contains("0_u16..PATH2_NATIVE_SIGNER_ENTROPY_Q_FIXED_ATTEMPTS");
    let source_boundary_complete = digest_source
        .contains("PATH2_NATIVE_SIGNER_ENTROPY_DERIVATION_DOMAIN")
        && digest_source.contains("Path2NativeSignerDigestFrameV1::new()")
        && digest_source.contains("frame.append_frame(b\"label\", label)")
        && digest_source.contains("frame.append_frame(b\"public_binding\", public_binding)")
        && digest_source.contains("frame.append_frame(b\"root_entropy\", &root.root_entropy)")
        && digest_source.contains("frame.append_frame(b\"account_nonce\", &root.account_nonce)")
        && digest_source.contains("frame.append_frame(b\"counter\", &counter.to_le_bytes())")
        && digest_source
            .contains("path2_native_private_sha256_digest_v1(frame.as_slice(), &mut digest)")
        && digest_source.contains("frame.zeroize();")
        && public_binding_words == 6
        && derivation_labels_are_static_public
        && q_sampler_fixed_digest_call_schedule;

    Path2NativeSignerSha256BoundaryAuditV1 {
        schema: PATH2_NATIVE_SIGNER_SHA256_BOUNDARY_AUDIT_SCHEMA,
        audit_complete: false,
        source_boundary_complete,
        sha256_backend_constant_time_claim_complete: false,
        digest_domain_frame_present: digest_source
            .contains("PATH2_NATIVE_SIGNER_ENTROPY_DERIVATION_DOMAIN"),
        digest_label_frame_present: digest_source.contains("frame.append_frame(b\"label\", label)"),
        digest_public_binding_frame_present: digest_source
            .contains("frame.append_frame(b\"public_binding\", public_binding)"),
        digest_owned_entropy_frames_present: digest_source
            .contains("frame.append_frame(b\"root_entropy\", &root.root_entropy)")
            && digest_source
                .contains("frame.append_frame(b\"account_nonce\", &root.account_nonce)"),
        digest_counter_frame_present: digest_source
            .contains("frame.append_frame(b\"counter\", &counter.to_le_bytes())"),
        public_binding_fixed_six_digest_words: public_binding_words == 6,
        derivation_labels_are_static_public,
        q_sampler_fixed_digest_call_schedule,
        secret_dependent_sha_input_lengths_absent: source_boundary_complete,
        entropy_digest_source_digest: Sha256::digest(digest_source.as_bytes()).into(),
        secret_derivation_source_digest: Sha256::digest(derivation_source.as_bytes()).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "source boundary audit is not a SHA-256 backend audit",
            "source boundary audit is not microarchitectural timing evidence",
            "source boundary audit is limited to signer entropy derivation",
        ],
    }
}

pub fn path2_native_signer_sha256_call_schedule_audit_v1()
-> Path2NativeSignerSha256CallScheduleAuditV1 {
    let derivation_source = path2_native_secret_material_derivation_source_window_v1();
    let q_sampler_source = path2_native_signer_entropy_q_source_window_v1();
    let secret_component_source = path2_native_secret_component_digest_source_window_v1();
    let entropy_seed_digest_calls = [
        "b\"authorization_local_seed\"",
        "b\"gauge_seed\"",
        "b\"randomizer_seed\"",
        "b\"wallet_recovery_seed\"",
    ]
    .iter()
    .filter(|label| derivation_source.contains(**label))
    .count() as u16;
    let q_sampler_invocations = REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS as u16;
    let q_sampler_digest_attempts_per_invocation = PATH2_NATIVE_SIGNER_ENTROPY_Q_FIXED_ATTEMPTS;
    let q_sampler_total_digest_calls =
        q_sampler_invocations * q_sampler_digest_attempts_per_invocation;
    let total_entropy_digest_calls = entropy_seed_digest_calls + q_sampler_total_digest_calls;
    let secret_component_digest_calls = [
        "b\"authorization_local\"",
        "b\"gauge\"",
        "b\"randomizer\"",
        "b\"wallet_recovery\"",
    ]
    .iter()
    .filter(|label| include_str!("production_reference.rs").contains(**label))
    .count() as u16;
    let secret_component_labels_are_static = secret_component_digest_calls == 4
        && secret_component_source.contains("Path2NativeSignerDigestFrameV1::new()")
        && secret_component_source.contains("frame.append_frame(b\"label\", label)")
        && secret_component_source
            .contains("path2_native_private_sha256_digest_v1(frame.as_slice(), &mut digest)")
        && secret_component_source.contains("frame.zeroize();");
    let secret_component_seeds_zeroized_after_digest =
        secret_component_source.contains("path2_native_zeroize_bytes_v1(seed);");
    let no_secret_dependent_sha_loop_bounds = derivation_source
        .contains("for (idx, value) in proof_randomizer_syndrome.iter_mut().enumerate()")
        && q_sampler_source.contains("0_u16..PATH2_NATIVE_SIGNER_ENTROPY_Q_FIXED_ATTEMPTS")
        && !secret_component_source.contains("for ");
    let source_schedule_complete = entropy_seed_digest_calls == 4
        && q_sampler_invocations == 12
        && q_sampler_digest_attempts_per_invocation == 4
        && q_sampler_total_digest_calls == 48
        && total_entropy_digest_calls == 52
        && secret_component_digest_calls == 4
        && secret_component_labels_are_static
        && secret_component_seeds_zeroized_after_digest
        && no_secret_dependent_sha_loop_bounds;

    Path2NativeSignerSha256CallScheduleAuditV1 {
        schema: PATH2_NATIVE_SIGNER_SHA256_CALL_SCHEDULE_AUDIT_SCHEMA,
        audit_complete: false,
        source_schedule_complete,
        sha256_backend_constant_time_claim_complete: false,
        entropy_seed_digest_calls,
        q_sampler_invocations,
        q_sampler_digest_attempts_per_invocation,
        q_sampler_total_digest_calls,
        total_entropy_digest_calls,
        secret_component_digest_calls,
        secret_component_labels_are_static,
        secret_component_seeds_zeroized_after_digest,
        no_secret_dependent_sha_loop_bounds,
        entropy_schedule_source_digest: Sha256::digest(derivation_source.as_bytes()).into(),
        secret_component_source_digest: Sha256::digest(secret_component_source.as_bytes()).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "call-schedule audit is not a SHA-256 compression backend audit",
            "call-schedule audit is not microarchitectural timing evidence",
            "call-schedule audit covers the signer-owned valid private path only",
        ],
    }
}

