pub fn path2_native_signer_os_entropy_boundary_audit_v1()
-> Path2NativeSignerOsEntropyBoundaryAuditV1 {
    let source_window = path2_native_signer_os_entropy_source_window_v1();
    let root_call = "getrandom::getrandom(&mut root.root_entropy)";
    let nonce_call = "getrandom::getrandom(&mut root.account_nonce)";
    let root_call_pos = source_window.find(root_call);
    let nonce_call_pos = source_window.find(nonce_call);
    let exactly_two_os_entropy_calls = source_window.matches("getrandom::getrandom").count() == 2;
    let zero_initialized_before_os_calls = source_window
        .find("root_entropy: [0_u8; DIGEST_BYTES]")
        .zip(source_window.find("account_nonce: [0_u8; DIGEST_BYTES]"))
        .zip(root_call_pos)
        .map(|((root_init, nonce_init), call)| root_init < call && nonce_init < call)
        .unwrap_or(false);
    let root_call_before_nonce_call = root_call_pos
        .zip(nonce_call_pos)
        .map(|(root, nonce)| root < nonce)
        .unwrap_or(false);
    let zeroizes_after_first_failure = root_call_pos
        .zip(
            source_window.find("return Err(\"Path 2 native OS entropy root failure\".to_string())"),
        )
        .map(|(call, ret)| {
            call < ret
                && source_window[call..ret].contains("root.zeroize();")
                && source_window[call..ret].contains(".is_err()")
        })
        .unwrap_or(false);
    let zeroizes_after_second_failure = nonce_call_pos
        .zip(
            source_window
                .find("return Err(\"Path 2 native OS entropy nonce failure\".to_string())"),
        )
        .map(|(call, ret)| {
            call < ret
                && source_window[call..ret].contains("root.zeroize();")
                && source_window[call..ret].contains(".is_err()")
        })
        .unwrap_or(false);
    let no_backend_error_detail_exported =
        !source_window.contains("format!(") && !source_window.contains("{err}");
    let entropy_failure_report = path2_native_signer_execution_failure_report_v1(
        "reject_active_native_signer_entropy_failed",
    );
    let entropy_failure_report_digest_absent =
        path2_native_signer_execution_report_has_no_private_digests_v1(&entropy_failure_report);
    let public_execution_report_sanitizes_entropy_failure = entropy_failure_report.rejection_code
        == Some("reject_active_native_signer_entropy_failed")
        && path2_native_signer_rejection_code_is_public_v1(entropy_failure_report.rejection_code)
        && entropy_failure_report_digest_absent;
    let source_boundary_complete = zero_initialized_before_os_calls
        && exactly_two_os_entropy_calls
        && root_call_before_nonce_call
        && zeroizes_after_first_failure
        && zeroizes_after_second_failure
        && no_backend_error_detail_exported
        && public_execution_report_sanitizes_entropy_failure;

    Path2NativeSignerOsEntropyBoundaryAuditV1 {
        schema: PATH2_NATIVE_SIGNER_OS_ENTROPY_BOUNDARY_AUDIT_SCHEMA,
        audit_complete: false,
        source_boundary_complete,
        os_backend_health_claim_complete: false,
        zero_initialized_before_os_calls,
        exactly_two_os_entropy_calls,
        root_call_before_nonce_call,
        zeroizes_after_first_failure,
        zeroizes_after_second_failure,
        no_partial_entropy_success: zeroizes_after_first_failure && zeroizes_after_second_failure,
        no_backend_error_detail_exported,
        public_execution_report_sanitizes_entropy_failure,
        entropy_failure_report_digest_absent,
        entropy_failure_rejection_code: entropy_failure_report.rejection_code,
        source_window_digest: Sha256::digest(source_window.as_bytes()).into(),
        blocker: PATH2_NATIVE_DEPLOYMENT_BLOCKER_CONSTANT_TIME,
        explicit_non_claims: [
            "OS entropy boundary audit is not an operating-system RNG health proof",
            "OS entropy boundary audit is not a hardware entropy validation",
            "OS entropy boundary audit is not whole-signer timing evidence",
        ],
    }
}

