pub fn validate_production_deployment_preflight_certificate(
    report: &ProductionDeploymentPreflightReport,
    certificate: &ProductionDeploymentPreflightCertificate,
) -> Result<(), String> {
    let expected = production_deployment_preflight_certificate(report)?;
    if expected != *certificate {
        return Err("production deployment preflight certificate mismatch".to_string());
    }
    if production_deployment_preflight_certificate_digest(certificate) != certificate.digest {
        return Err("production deployment preflight certificate digest mismatch".to_string());
    }
    Ok(())
}

pub fn require_production_deployment_preflight_ready(
    report: &ProductionDeploymentPreflightReport,
    verdict: &ProductionDeploymentPreflightVerdict,
) -> Result<(), String> {
    let assertion = production_deployment_preflight_ready_assertion(report, verdict)?;
    if !assertion.assertion_passed {
        return Err(assertion.blocker.to_string());
    }
    Ok(())
}

