impl ProductionReviewedFq12StateAssistedAccountState {
    pub fn new(slots: Vec<ProductionReviewedFq12StateAssistedAccountSlot>) -> Result<Self, String> {
        let mut pad_seed_digests = BTreeSet::new();
        for (idx, slot) in slots.iter().enumerate() {
            if slot.slot_id() as usize != idx {
                return Err("state-assisted account slots must be sorted by slot id".to_string());
            }
            validate_reviewed_fq12_state_assisted_account_commitment(slot.commitment())?;
            if slot.hidden_source_opening_commitment() == [0_u8; DIGEST_BYTES] {
                return Err(
                    "state-assisted hidden-source opening commitment must be nonzero".to_string(),
                );
            }
            if slot.restore_anchor_digest() == [0_u8; DIGEST_BYTES] {
                return Err("state-assisted restore anchor must be nonzero".to_string());
            }
            if slot.pad_seed_digest() == [0_u8; DIGEST_BYTES] {
                return Err("state-assisted pad seed digest must be nonzero".to_string());
            }
            if !pad_seed_digests.insert(slot.pad_seed_digest()) {
                return Err("state-assisted pad seed digest must be unique per account".to_string());
            }
        }
        Ok(Self { slots })
    }

    pub fn slots(&self) -> &[ProductionReviewedFq12StateAssistedAccountSlot] {
        &self.slots
    }

    pub fn get_slot(
        &self,
        slot_id: u32,
    ) -> Option<&ProductionReviewedFq12StateAssistedAccountSlot> {
        self.slots.get(slot_id as usize)
    }

    pub fn checked_slot_records(
        &self,
    ) -> Result<Vec<ProductionReviewedFq12StateAssistedAccountSlotRecord>, String> {
        let mut records = Vec::with_capacity(self.slots.len());
        let mut pad_seed_digests = BTreeSet::new();
        for (idx, slot) in self.slots.iter().enumerate() {
            if slot.slot_id() as usize != idx {
                return Err("state-assisted account slots must be sorted by slot id".to_string());
            }
            validate_reviewed_fq12_state_assisted_account_commitment(slot.commitment())?;
            if slot.hidden_source_opening_commitment() == [0_u8; DIGEST_BYTES] {
                return Err(
                    "state-assisted hidden-source opening commitment must be nonzero".to_string(),
                );
            }
            if slot.restore_anchor_digest() == [0_u8; DIGEST_BYTES] {
                return Err("state-assisted restore anchor must be nonzero".to_string());
            }
            if slot.pad_seed_digest() == [0_u8; DIGEST_BYTES] {
                return Err("state-assisted pad seed digest must be nonzero".to_string());
            }
            if !pad_seed_digests.insert(slot.pad_seed_digest()) {
                return Err("state-assisted pad seed digest must be unique per account".to_string());
            }
            records.push(ProductionReviewedFq12StateAssistedAccountSlotRecord {
                slot_id: slot.slot_id(),
                witness_commitment: slot.commitment().witness_commitment(),
                randomizer_commitment: slot.commitment().randomizer_commitment(),
                hidden_source_opening_commitment: slot.hidden_source_opening_commitment(),
                restore_anchor_digest: slot.restore_anchor_digest(),
                pad_seed_digest: slot.pad_seed_digest(),
                unused: slot.is_unused(),
            });
        }
        Ok(records)
    }

    pub fn mark_consumed(&mut self, slot_id: u32) -> Result<(), String> {
        let slot = self
            .slots
            .get_mut(slot_id as usize)
            .ok_or_else(|| "state-assisted slot id is out of range".to_string())?;
        slot.mark_consumed();
        Ok(())
    }
}

pub fn verify_reviewed_fq12_state_assisted_slot_opening(
    slot: &ProductionReviewedFq12StateAssistedAccountSlot,
    opening: &ProductionReviewedFq12StateAssistedOpening,
) -> Result<[u8; DIGEST_BYTES], String> {
    validate_reviewed_fq12_state_assisted_account_commitment(slot.commitment())?;
    if !slot.is_unused() {
        return Err("state-assisted slot is already consumed".to_string());
    }
    if opening.slot_id != slot.slot_id() as u64 {
        return Err("state-assisted opening slot id mismatch".to_string());
    }
    if opening.account_witness_commitment != slot.commitment().witness_commitment() {
        return Err("state-assisted witness commitment mismatch".to_string());
    }
    if opening.account_randomizer_commitment != slot.commitment().randomizer_commitment() {
        return Err("state-assisted randomizer commitment mismatch".to_string());
    }
    if opening.restore_anchor_digest != slot.restore_anchor_digest() {
        return Err("state-assisted restore anchor mismatch".to_string());
    }
    if opening.pad_seed_digest != slot.pad_seed_digest() {
        return Err("state-assisted pad seed digest mismatch".to_string());
    }
    let opening_commitment = reviewed_fq12_state_assisted_opening_commitment_digest(opening);
    if opening_commitment != slot.hidden_source_opening_commitment() {
        return Err("state-assisted hidden-source opening commitment mismatch".to_string());
    }
    Ok(opening_commitment)
}

