pub fn encode_reviewed_account_carried_masked_response(
    residues: &[u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES],
) -> Result<[u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES], String> {
    let mut out = [0_u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES];
    for (idx, &value) in residues.iter().enumerate() {
        if value >= Q {
            return Err(format!(
                "reviewed masked response residue {idx} is non-canonical: {value}"
            ));
        }
        write_bits_le(&mut out, idx * FIELD_BITS, FIELD_BITS, value);
    }
    Ok(out)
}

