pub fn pack_reviewed_fq12_packed_witness_state18_from_parts(
    syndrome: &[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
    account_projection: &[u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
) -> Result<[u8; DIGEST_BYTES], String> {
    let mut residues = [0_u16; REVIEWED_FQ12_PACKED_WITNESS_STATE18_ROWS];
    residues[..REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS].copy_from_slice(syndrome);
    residues[REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET
        ..REVIEWED_FQ12_PACKED_WITNESS_STATE18_PROJECTION_OFFSET
            + HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES]
        .copy_from_slice(account_projection);
    pack_reviewed_fq12_packed_witness_state18(&residues)
}

pub fn reviewed_account_carried_matrix_entry(row: usize, col: usize) -> u16 {
    assert!(row < REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS);
    assert!(col < REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES);
    domain_matrix_entry(REVIEWED_ACCOUNT_CARRIED_MATRIX_DOMAIN, row, col)
}

pub fn reviewed_fq12_account_carried_matrix_entry(row: usize, col: usize) -> u16 {
    assert!(row < REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS);
    assert!(col < REVIEWED_FQ12_ACCOUNT_CARRIED_RESPONSE_RESIDUES);
    domain_matrix_entry(REVIEWED_FQ12_ACCOUNT_CARRIED_MATRIX_DOMAIN, row, col)
}

pub fn reviewed_account_carried_response_syndrome(
    masked_quotient_response: &[u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS], String> {
    let vector = unpack_reviewed_account_carried_masked_response(masked_quotient_response)?;
    let mut syndrome = [0_u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS];
    for (row, out) in syndrome.iter_mut().enumerate() {
        let mut acc = 0_u32;
        for (col, &value) in vector.iter().enumerate() {
            acc += reviewed_account_carried_matrix_entry(row, col) as u32 * value as u32;
            acc %= Q as u32;
        }
        *out = acc as u16;
    }
    Ok(syndrome)
}

pub fn reviewed_fq12_account_carried_response_syndrome(
    masked_quotient_response: &[u8; REVIEWED_FQ12_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS], String> {
    let vector = unpack_reviewed_fq12_account_carried_masked_response(masked_quotient_response)?;
    let mut syndrome = [0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS];
    for (row, out) in syndrome.iter_mut().enumerate() {
        let mut acc = 0_u32;
        for (col, &value) in vector.iter().enumerate() {
            acc += reviewed_fq12_account_carried_matrix_entry(row, col) as u32 * value as u32;
            acc %= Q as u32;
        }
        *out = acc as u16;
    }
    Ok(syndrome)
}

pub fn reviewed_fq12_masked_response_for_response_syndrome(
    target: &[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
) -> Result<[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_RESPONSE_RESIDUES], String> {
    const ROWS: usize = REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS;
    const COLS: usize = REVIEWED_FQ12_ACCOUNT_CARRIED_RESPONSE_RESIDUES;
    let mut matrix = [[0_u16; COLS + 1]; ROWS];
    for row in 0..ROWS {
        for col in 0..COLS {
            matrix[row][col] = reviewed_fq12_account_carried_matrix_entry(row, col);
        }
        matrix[row][COLS] = target[row];
    }

    let mut rank = 0;
    let mut pivots = Vec::with_capacity(ROWS);
    for col in 0..COLS {
        let Some(pivot) = (rank..ROWS).find(|&row| matrix[row][col] != 0) else {
            continue;
        };
        matrix.swap(rank, pivot);
        let inverse = mod_inverse_q(matrix[rank][col])
            .ok_or_else(|| "reviewed Fq12 response matrix pivot is not invertible".to_string())?;
        for entry in matrix[rank].iter_mut().take(COLS + 1) {
            *entry = ((*entry as u32 * inverse as u32) % Q as u32) as u16;
        }
        for row in 0..ROWS {
            if row == rank {
                continue;
            }
            let factor = matrix[row][col];
            if factor == 0 {
                continue;
            }
            for idx in col..=COLS {
                let product = ((factor as u32 * matrix[rank][idx] as u32) % Q as u32) as u16;
                matrix[row][idx] = sub_mod(matrix[row][idx], product);
            }
        }
        pivots.push(col);
        rank += 1;
        if rank == ROWS {
            break;
        }
    }
    for row in rank..ROWS {
        if matrix[row][COLS] != 0 {
            return Err("reviewed Fq12 response syndrome is outside matrix image".to_string());
        }
    }
    let mut response = [0_u16; COLS];
    for (row, &col) in pivots.iter().enumerate() {
        response[col] = matrix[row][COLS];
    }
    Ok(response)
}

pub fn reviewed_account_carried_response_syndrome_digest(
    masked_quotient_response: &[u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    let syndrome = reviewed_account_carried_response_syndrome(masked_quotient_response)?;
    pack_reviewed_account_carried_syndrome_digest(&syndrome)
}

pub fn reviewed_fq12_account_carried_response_syndrome_digest(
    masked_quotient_response: &[u8; REVIEWED_FQ12_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    let syndrome = reviewed_fq12_account_carried_response_syndrome(masked_quotient_response)?;
    pack_reviewed_fq12_account_carried_syndrome_digest(&syndrome)
}

pub fn reviewed_fq12_challenge_action_vector(
    challenge: &[u8; CHALLENGE_BYTES],
) -> [u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS] {
    let mut out = [0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS];
    for (idx, value) in out.iter_mut().enumerate() {
        *value = uniform_mod_from_hash(
            REVIEWED_FQ12_ACCOUNT_CARRIED_CHALLENGE_ACTION_DOMAIN.as_bytes(),
            challenge,
            0,
            idx as u64,
            Q,
        );
    }
    out
}

pub fn reviewed_fq12_account_carried_expected_response_syndrome(
    challenge: &[u8; CHALLENGE_BYTES],
    witness_commitment: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> Result<[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS], String> {
    let witness = unpack_reviewed_fq12_account_carried_syndrome_digest(witness_commitment)?;
    let randomizer = unpack_reviewed_fq12_account_carried_syndrome_digest(proof_commitment)?;
    Ok(fq12_syndrome_add(
        &randomizer,
        &fq12_syndrome_mul(&reviewed_fq12_challenge_action_vector(challenge), &witness),
    ))
}

pub fn reviewed_fq12_state_assisted_witness_syndrome(
    witness_commitment: &[u8; DIGEST_BYTES],
) -> Result<[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS], String> {
    if let Ok(syndrome) = unpack_reviewed_fq12_account_carried_syndrome_digest(witness_commitment) {
        return Ok(syndrome);
    }
    let state18 = unpack_reviewed_fq12_packed_witness_state18(witness_commitment)?;
    let mut syndrome = [0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS];
    syndrome.copy_from_slice(&state18[..REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS]);
    Ok(syndrome)
}

pub fn reviewed_fq12_state_assisted_expected_response_syndrome(
    challenge: &[u8; CHALLENGE_BYTES],
    witness_commitment: &[u8; DIGEST_BYTES],
    proof_commitment: &[u8; LINEAR_SIGMA_PROOF_COMMITMENT_BYTES],
) -> Result<[u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS], String> {
    let witness = reviewed_fq12_state_assisted_witness_syndrome(witness_commitment)?;
    let randomizer = unpack_reviewed_fq12_account_carried_syndrome_digest(proof_commitment)?;
    Ok(fq12_syndrome_add(
        &randomizer,
        &fq12_syndrome_mul(&reviewed_fq12_challenge_action_vector(challenge), &witness),
    ))
}

pub fn verify_public_local_fiber_consistency(
    public_key: &ProductionPublicKey,
    challenge: &ProductionCompactChallenge,
    responses: &ProductionCompactResponses,
) -> Result<ProductionPublicLocalConsistency, String> {
    let public_view = decode_public_view(public_key.as_bytes())?;
    let mut expected_state = None;
    for rep in 0..REPS {
        let mask_view = reconstructed_mask_view(&public_view, challenge, responses, rep)?;
        let state = local_state(mask_view);
        match expected_state {
            Some(expected) if expected != state => {
                return Err(format!(
                    "public local fiber-state mismatch in round {rep}: expected {expected}, got {state}"
                ));
            }
            Some(_) => {}
            None => expected_state = Some(state),
        }
    }
    Ok(ProductionPublicLocalConsistency {
        fiber_state: expected_state.unwrap_or(0),
    })
}

pub fn verify_public_pad_opening_consistency(
    public_key: &ProductionPublicKey,
    challenge: &ProductionCompactChallenge,
    responses: &ProductionCompactResponses,
    openings: &ProductionLocalOpenings,
) -> Result<ProductionPublicPadOpeningConsistency, String> {
    let public_view = decode_public_view(public_key.as_bytes())?;
    let mut block_pads = [[0_u16; LOCAL_FREE]; GROUPS];
    let mut observed_blocks = [false; GROUPS];
    for rep in 0..REPS {
        let block = challenge.active_block[rep];
        let mask_view = reconstructed_mask_view(&public_view, challenge, responses, rep)?;
        let mut pad = [0_u16; LOCAL_FREE];
        for coord in 0..LOCAL_FREE {
            pad[coord] = sub_mod(openings.active_free[rep][coord], mask_view[coord]);
        }
        if observed_blocks[block] && block_pads[block] != pad {
            return Err(format!(
                "public pad-opening mismatch for block {block} in round {rep}"
            ));
        }
        block_pads[block] = pad;
        observed_blocks[block] = true;
    }
    Ok(ProductionPublicPadOpeningConsistency {
        block_pads,
        observed_blocks,
    })
}

pub fn public_pad_opening_statement_from_consistency(
    consistency: &ProductionPublicPadOpeningConsistency,
) -> ProductionPublicPadOpeningStatement {
    let frame = public_pad_opening_statement_frame(consistency);
    let digest = Sha256::digest(&frame).into();
    ProductionPublicPadOpeningStatement {
        digest,
        observed_blocks: consistency.observed_blocks,
        observed_block_count: consistency
            .observed_blocks
            .iter()
            .filter(|&&observed| observed)
            .count(),
    }
}

pub fn public_pad_opening_statement(
    public_key: &ProductionPublicKey,
    challenge: &ProductionCompactChallenge,
    responses: &ProductionCompactResponses,
    openings: &ProductionLocalOpenings,
) -> Result<ProductionPublicPadOpeningStatement, String> {
    let consistency =
        verify_public_pad_opening_consistency(public_key, challenge, responses, openings)?;
    Ok(public_pad_opening_statement_from_consistency(&consistency))
}

pub fn reviewed_fq12_account_carried_pad_opening_statement(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
) -> Result<ProductionPublicPadOpeningStatement, ProductionAccountBindingError> {
    let parts =
        verify_reviewed_fq12_account_carried_checked_core(public_key, message, account, signature)?;
    public_pad_opening_statement(
        public_key,
        &parts.challenge,
        &parts.responses,
        &parts.openings,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))
}

pub fn reviewed_fq12_pad_residues_from_seed(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    block: usize,
) -> [u16; LOCAL_FREE] {
    let frame = reviewed_fq12_pad_frame(block);
    let rejection_cutoff = (u16::MAX as u32 + 1) / Q as u32 * Q as u32;
    let mut out = [0_u16; LOCAL_FREE];
    let mut filled = 0_usize;
    let mut counter = 0_u32;
    while filled < LOCAL_FREE {
        let digest = reviewed_fq12_pad_prf_block(pad_seed, &frame, counter);
        counter = counter
            .checked_add(1)
            .expect("reviewed Fq12 pad rejection sampler exhausted u32 counter space");
        for chunk in digest.chunks_exact(2) {
            let candidate = u16::from_le_bytes([chunk[0], chunk[1]]) as u32;
            if candidate < rejection_cutoff {
                out[filled] = (candidate % Q as u32) as u16;
                filled += 1;
                if filled == LOCAL_FREE {
                    break;
                }
            }
        }
    }
    out
}

pub fn reviewed_fq12_pad_prf_input_frame(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    block: usize,
    counter: u32,
) -> Result<Vec<u8>, String> {
    if block >= GROUPS {
        return Err(format!(
            "reviewed Fq12 pad PRF block {block} is out of range"
        ));
    }
    let frame = reviewed_fq12_pad_frame(block);
    let mut input =
        Vec::with_capacity(REVIEWED_FQ12_PAD_SEED_BYTES + REVIEWED_FQ12_PAD_FRAME_BYTES + 4);
    input.extend_from_slice(pad_seed);
    input.extend_from_slice(&frame);
    input.extend_from_slice(&counter.to_le_bytes());
    Ok(input)
}

pub fn reviewed_fq12_pad_residues_from_seed_bounded(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    block: usize,
) -> Result<[u16; LOCAL_FREE], String> {
    let frame = reviewed_fq12_pad_frame(block);
    let rejection_cutoff = (u16::MAX as u32 + 1) / Q as u32 * Q as u32;
    let mut out = [0_u16; LOCAL_FREE];
    let mut filled = 0_usize;
    for counter in 0..REVIEWED_FQ12_PAD_PRF_COUNTER_LIMIT {
        let digest = reviewed_fq12_pad_prf_block(pad_seed, &frame, counter);
        for chunk in digest.chunks_exact(2) {
            let candidate = u16::from_le_bytes([chunk[0], chunk[1]]) as u32;
            if candidate < rejection_cutoff {
                out[filled] = (candidate % Q as u32) as u16;
                filled += 1;
                if filled == LOCAL_FREE {
                    return Ok(out);
                }
            }
        }
    }
    Err(format!(
        "reviewed Fq12 bounded pad PRF exhausted {REVIEWED_FQ12_PAD_PRF_COUNTER_LIMIT} counters for block {block}"
    ))
}

pub fn reviewed_fq12_pad_opening_consistency_from_seed(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    observed_blocks: &[bool; GROUPS],
) -> ProductionPublicPadOpeningConsistency {
    let mut block_pads = [[0_u16; LOCAL_FREE]; GROUPS];
    for block in 0..GROUPS {
        if observed_blocks[block] {
            block_pads[block] = reviewed_fq12_pad_residues_from_seed(pad_seed, block);
        }
    }
    ProductionPublicPadOpeningConsistency {
        block_pads,
        observed_blocks: *observed_blocks,
    }
}

pub fn reviewed_fq12_pad_opening_statement_from_seed(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    observed_blocks: &[bool; GROUPS],
) -> ProductionPublicPadOpeningStatement {
    public_pad_opening_statement_from_consistency(&reviewed_fq12_pad_opening_consistency_from_seed(
        pad_seed,
        observed_blocks,
    ))
}

pub fn verify_reviewed_fq12_pad_opening_statement_witness(
    statement: &ProductionPublicPadOpeningStatement,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<(), String> {
    let expected =
        reviewed_fq12_pad_opening_statement_from_seed(pad_seed, &statement.observed_blocks);
    if &expected != statement {
        return Err("reviewed Fq12 pad-opening statement witness mismatch".to_string());
    }
    Ok(())
}

pub fn reviewed_fq12_pad_seed_opening_digest(
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> [u8; DIGEST_BYTES] {
    let mut frame = Vec::new();
    append_frame(
        &mut frame,
        b"domain",
        REVIEWED_FQ12_PAD_SEED_OPENING_DOMAIN.as_bytes(),
    );
    append_frame(&mut frame, b"profile", PROFILE.as_bytes());
    append_u64(&mut frame, b"q", Q as u64);
    append_u64(&mut frame, b"groups", GROUPS as u64);
    append_u64(&mut frame, b"local_free", LOCAL_FREE as u64);
    append_u64(
        &mut frame,
        b"pad_seed_bytes",
        REVIEWED_FQ12_PAD_SEED_BYTES as u64,
    );
    append_frame(&mut frame, b"pad_seed", pad_seed);
    Sha256::digest(frame).into()
}

pub fn verify_reviewed_fq12_pad_seed_opening(
    statement: &ProductionPublicPadOpeningStatement,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
    expected_pad_seed_digest: &[u8; DIGEST_BYTES],
) -> Result<(), String> {
    let actual_pad_seed_digest = reviewed_fq12_pad_seed_opening_digest(pad_seed);
    if &actual_pad_seed_digest != expected_pad_seed_digest {
        return Err("reviewed Fq12 pad seed opening digest mismatch".to_string());
    }
    verify_reviewed_fq12_pad_opening_statement_witness(statement, pad_seed)
}

pub fn verify_reviewed_fq12_state_assisted_pad_seed_opening(
    slot: &ProductionReviewedFq12StateAssistedAccountSlot,
    opening: &ProductionReviewedFq12StateAssistedOpening,
    statement: &ProductionPublicPadOpeningStatement,
    pad_seed: &[u8; REVIEWED_FQ12_PAD_SEED_BYTES],
) -> Result<[u8; DIGEST_BYTES], String> {
    let opening_commitment = verify_reviewed_fq12_state_assisted_slot_opening(slot, opening)?;
    verify_reviewed_fq12_pad_seed_opening(statement, pad_seed, &opening.pad_seed_digest)?;
    Ok(opening_commitment)
}

pub fn reviewed_fq12_account_carried_hidden_source_statement(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
) -> Result<ProductionReviewedFq12HiddenSourceStatement, ProductionAccountBindingError> {
    let parts =
        verify_reviewed_fq12_account_carried_checked_core(public_key, message, account, signature)?;
    let slot = account.get_slot(parts.slot_id).ok_or_else(|| {
        ProductionAccountBindingError::new(Some(parts.slot_id), "slot id is out of range")
    })?;
    let public_statement = public_pad_opening_statement(
        public_key,
        &parts.challenge,
        &parts.responses,
        &parts.openings,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    Ok(reviewed_fq12_hidden_source_statement_from_public(
        public_key,
        message,
        parts.slot_id,
        slot.commitment(),
        signature,
        public_statement,
    ))
}

pub fn reviewed_fq12_state_assisted_hidden_source_statement(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionReviewedFq12StateAssistedAccountState,
    signature: &ProductionSignature,
) -> Result<ProductionReviewedFq12HiddenSourceStatement, ProductionAccountBindingError> {
    let parts =
        verify_reviewed_fq12_state_assisted_checked_core(public_key, message, account, signature)?;
    let slot = account.get_slot(parts.slot_id).ok_or_else(|| {
        ProductionAccountBindingError::new(Some(parts.slot_id), "slot id is out of range")
    })?;
    let public_statement = public_pad_opening_statement(
        public_key,
        &parts.challenge,
        &parts.responses,
        &parts.openings,
    )
    .map_err(|err| ProductionAccountBindingError::new(Some(parts.slot_id), err))?;
    Ok(reviewed_fq12_hidden_source_statement_from_public(
        public_key,
        message,
        parts.slot_id,
        slot.commitment(),
        signature,
        public_statement,
    ))
}

pub fn verify_reviewed_fq12_hidden_source_statement_witness(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    hidden_source: &ProductionReviewedFq12HiddenSourceWitness,
) -> Result<(), String> {
    if reviewed_fq12_hidden_source_statement_digest(statement) != statement.digest {
        return Err("reviewed Fq12 hidden-source statement digest mismatch".to_string());
    }
    let expected_witness_commitment =
        pack_reviewed_fq12_account_carried_syndrome_digest(&hidden_source.witness_syndrome)?;
    if expected_witness_commitment != statement.witness_commitment {
        return Err("reviewed Fq12 hidden-source witness syndrome commitment mismatch".to_string());
    }
    verify_reviewed_fq12_pad_opening_statement_witness(
        &statement.pad_opening_statement,
        &hidden_source.pad_seed,
    )?;
    Ok(())
}

pub fn reviewed_fq12_hidden_source_statement_digest(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_statement_frame(statement)).into()
}

pub fn reviewed_fq12_hidden_source_proof_transcript_digest(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    proof: &ProductionReviewedFq12HiddenSourceProof,
) -> [u8; DIGEST_BYTES] {
    reviewed_fq12_hidden_source_proof_transcript(statement, proof).digest
}

pub fn reviewed_fq12_hidden_source_proof_transcript(
    statement: &ProductionReviewedFq12HiddenSourceStatement,
    proof: &ProductionReviewedFq12HiddenSourceProof,
) -> ProductionReviewedFq12HiddenSourceProofTranscript {
    let statement_digest = reviewed_fq12_hidden_source_statement_digest(statement);
    let digest = Sha256::digest(reviewed_fq12_hidden_source_proof_transcript_frame(
        statement, proof,
    ))
    .into();
    ProductionReviewedFq12HiddenSourceProofTranscript {
        digest,
        statement_digest,
        proof_bytes: REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_BYTES,
    }
}

pub fn reviewed_fq12_deployment_blocker_report_digest(
    report: &ProductionReviewedFq12DeploymentBlockerReport,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_deployment_blocker_report_frame(report)).into()
}

pub fn reviewed_fq12_hidden_source_proof_semantics_gate(
    report: &ProductionReviewedFq12DeploymentBlockerReport,
) -> Result<ProductionReviewedFq12HiddenSourceProofSemanticsGate, String> {
    let report_digest = reviewed_fq12_deployment_blocker_report_digest(report);
    if report_digest != report.digest {
        return Err("reviewed Fq12 deployment blocker report digest mismatch".to_string());
    }
    let transcript = reviewed_fq12_hidden_source_proof_transcript(
        &report.context.statement,
        &report.context.proof,
    );
    if transcript != report.context.transcript {
        return Err("reviewed Fq12 hidden-source proof transcript mismatch".to_string());
    }
    let semantics_bridge_audit = path2_reviewed_fq12_hidden_source_semantics_bridge_audit();
    validate_path2_reviewed_fq12_hidden_source_semantics_bridge_audit(&semantics_bridge_audit)?;
    let mut gate = ProductionReviewedFq12HiddenSourceProofSemanticsGate {
        digest: [0_u8; DIGEST_BYTES],
        profile: REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_SEMANTICS_PROFILE,
        deployment_report_digest: report_digest,
        semantics_bridge_audit_digest: semantics_bridge_audit.digest,
        transcript_digest: transcript.digest,
        proof_bytes: transcript.proof_bytes,
        semantics_bridge_complete: semantics_bridge_audit.semantics_bridge_complete,
        acceptance_implemented: false,
        blocker: report.blocker,
    };
    gate.digest = reviewed_fq12_hidden_source_proof_semantics_gate_digest(&gate);
    Ok(gate)
}

pub fn reviewed_fq12_hidden_source_proof_semantics_gate_digest(
    gate: &ProductionReviewedFq12HiddenSourceProofSemanticsGate,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_semantics_gate_frame(gate)).into()
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_contract(
    gate: &ProductionReviewedFq12HiddenSourceProofSemanticsGate,
) -> Result<ProductionReviewedFq12HiddenSourceProofAcceptanceContract, String> {
    let gate_digest = reviewed_fq12_hidden_source_proof_semantics_gate_digest(gate);
    if gate_digest != gate.digest {
        return Err("reviewed Fq12 hidden-source proof semantics gate digest mismatch".to_string());
    }
    let expected_semantics_bridge_audit =
        path2_reviewed_fq12_hidden_source_semantics_bridge_audit();
    if gate.semantics_bridge_audit_digest != expected_semantics_bridge_audit.digest {
        return Err(
            "reviewed Fq12 hidden-source proof semantics gate bridge audit digest mismatch"
                .to_string(),
        );
    }
    if gate.semantics_bridge_complete != expected_semantics_bridge_audit.semantics_bridge_complete {
        return Err(
            "reviewed Fq12 hidden-source proof semantics gate bridge completion flag mismatch"
                .to_string(),
        );
    }
    let required_obligation_bitmap = REVIEWED_FQ12_ACCEPTANCE_REQUIRED_OBLIGATIONS;
    let implemented_obligation_bitmap = REVIEWED_FQ12_ACCEPTANCE_EXECUTABLE_RELATION_OBLIGATIONS;
    let missing_obligation_bitmap = required_obligation_bitmap & !implemented_obligation_bitmap;
    let mut contract = ProductionReviewedFq12HiddenSourceProofAcceptanceContract {
        digest: [0_u8; DIGEST_BYTES],
        semantics_gate_digest: gate_digest,
        required_obligation_bitmap,
        implemented_obligation_bitmap,
        missing_obligation_bitmap,
        required_obligation_count: required_obligation_bitmap.count_ones() as u8,
        implemented_obligation_count: implemented_obligation_bitmap.count_ones() as u8,
        missing_obligation_count: missing_obligation_bitmap.count_ones() as u8,
        requires_statement_binding: true,
        requires_witness_commitment_opening: true,
        requires_pad_seed_opening: true,
        requires_transcript_binding: true,
        requires_soundness_analysis: true,
        requires_zero_knowledge_analysis: true,
        requires_mask_prf_domain_separation: true,
        all_obligations_implemented: false,
        blocker: gate.blocker,
    };
    contract.digest = reviewed_fq12_hidden_source_proof_acceptance_contract_digest(&contract);
    Ok(contract)
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_contract_digest(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_acceptance_contract_frame(
        contract,
    ))
    .into()
}

pub fn validate_reviewed_fq12_hidden_source_proof_acceptance_contract(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
) -> Result<(), String> {
    if reviewed_fq12_hidden_source_proof_acceptance_contract_digest(contract) != contract.digest {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract digest mismatch".to_string(),
        );
    }
    if contract.required_obligation_bitmap != REVIEWED_FQ12_ACCEPTANCE_REQUIRED_OBLIGATIONS {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract required bitmap mismatch"
                .to_string(),
        );
    }
    if contract.required_obligation_count != REVIEWED_FQ12_ACCEPTANCE_REQUIRED_OBLIGATION_COUNT {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract required count mismatch"
                .to_string(),
        );
    }
    if contract.required_obligation_count != contract.required_obligation_bitmap.count_ones() as u8
    {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract required bitmap/count mismatch"
                .to_string(),
        );
    }
    if contract.implemented_obligation_bitmap & !contract.required_obligation_bitmap != 0 {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract implements unknown obligation"
                .to_string(),
        );
    }
    if contract.missing_obligation_bitmap
        != contract.required_obligation_bitmap & !contract.implemented_obligation_bitmap
    {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract missing bitmap mismatch"
                .to_string(),
        );
    }
    if contract.implemented_obligation_count
        != contract.implemented_obligation_bitmap.count_ones() as u8
    {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract implemented bitmap/count mismatch"
                .to_string(),
        );
    }
    if contract.missing_obligation_count != contract.missing_obligation_bitmap.count_ones() as u8 {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract missing bitmap/count mismatch"
                .to_string(),
        );
    }
    if contract.all_obligations_implemented != (contract.missing_obligation_bitmap == 0) {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance contract acceptance flag mismatch"
                .to_string(),
        );
    }
    Ok(())
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_obligations(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
) -> Result<
    [ProductionReviewedFq12HiddenSourceProofAcceptanceObligation;
        REVIEWED_FQ12_ACCEPTANCE_REQUIRED_OBLIGATION_COUNT as usize],
    String,
> {
    validate_reviewed_fq12_hidden_source_proof_acceptance_contract(contract)?;
    Ok(std::array::from_fn(|index| {
        let bit = REVIEWED_FQ12_ACCEPTANCE_OBLIGATION_BITS[index];
        let mut obligation = ProductionReviewedFq12HiddenSourceProofAcceptanceObligation {
            digest: [0_u8; DIGEST_BYTES],
            contract_digest: contract.digest,
            index: index as u8,
            bit,
            label: REVIEWED_FQ12_ACCEPTANCE_OBLIGATION_LABELS[index],
            implemented: contract.implemented_obligation_bitmap & bit != 0,
            missing: contract.missing_obligation_bitmap & bit != 0,
            blocker: contract.blocker,
        };
        obligation.digest =
            reviewed_fq12_hidden_source_proof_acceptance_obligation_digest(&obligation);
        obligation
    }))
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_obligation_digest(
    obligation: &ProductionReviewedFq12HiddenSourceProofAcceptanceObligation,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_acceptance_obligation_frame(obligation)).into()
}

pub fn validate_reviewed_fq12_hidden_source_proof_acceptance_obligation(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
    obligation: &ProductionReviewedFq12HiddenSourceProofAcceptanceObligation,
) -> Result<(), String> {
    validate_reviewed_fq12_hidden_source_proof_acceptance_contract(contract)?;
    if obligation.index as usize >= REVIEWED_FQ12_ACCEPTANCE_REQUIRED_OBLIGATION_COUNT as usize {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation index out of range"
                .to_string(),
        );
    }
    let expected_bit = REVIEWED_FQ12_ACCEPTANCE_OBLIGATION_BITS[obligation.index as usize];
    let expected_label = REVIEWED_FQ12_ACCEPTANCE_OBLIGATION_LABELS[obligation.index as usize];
    if obligation.contract_digest != contract.digest {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation contract digest mismatch"
                .to_string(),
        );
    }
    if obligation.bit != expected_bit {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation bit mismatch".to_string(),
        );
    }
    if obligation.label != expected_label {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation label mismatch".to_string(),
        );
    }
    if obligation.implemented != (contract.implemented_obligation_bitmap & obligation.bit != 0) {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation implemented flag mismatch"
                .to_string(),
        );
    }
    if obligation.missing != (contract.missing_obligation_bitmap & obligation.bit != 0) {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation missing flag mismatch"
                .to_string(),
        );
    }
    if obligation.implemented && obligation.missing {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation cannot be both implemented and missing"
                .to_string(),
        );
    }
    if reviewed_fq12_hidden_source_proof_acceptance_obligation_digest(obligation)
        != obligation.digest
    {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_obligation_report(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
) -> Result<ProductionReviewedFq12HiddenSourceProofAcceptanceObligationReport, String> {
    validate_reviewed_fq12_hidden_source_proof_acceptance_contract(contract)?;
    let obligations = reviewed_fq12_hidden_source_proof_acceptance_obligations(contract)?;
    for obligation in &obligations {
        validate_reviewed_fq12_hidden_source_proof_acceptance_obligation(contract, obligation)?;
    }
    let obligation_digests = std::array::from_fn(|index| obligations[index].digest);
    let mut report = ProductionReviewedFq12HiddenSourceProofAcceptanceObligationReport {
        digest: [0_u8; DIGEST_BYTES],
        contract_digest: contract.digest,
        obligation_digests,
        required_obligation_count: contract.required_obligation_count,
        implemented_obligation_count: contract.implemented_obligation_count,
        missing_obligation_count: contract.missing_obligation_count,
        all_obligations_implemented: contract.all_obligations_implemented,
        blocker: contract.blocker,
    };
    report.digest = reviewed_fq12_hidden_source_proof_acceptance_obligation_report_digest(&report);
    Ok(report)
}

pub fn reviewed_fq12_hidden_source_proof_acceptance_obligation_report_digest(
    report: &ProductionReviewedFq12HiddenSourceProofAcceptanceObligationReport,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_acceptance_obligation_report_frame(report))
        .into()
}

pub fn validate_reviewed_fq12_hidden_source_proof_acceptance_obligation_report(
    contract: &ProductionReviewedFq12HiddenSourceProofAcceptanceContract,
    report: &ProductionReviewedFq12HiddenSourceProofAcceptanceObligationReport,
) -> Result<(), String> {
    validate_reviewed_fq12_hidden_source_proof_acceptance_contract(contract)?;
    if report.contract_digest != contract.digest {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report contract digest mismatch"
                .to_string(),
        );
    }
    if report.required_obligation_count != contract.required_obligation_count {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report required count mismatch"
                .to_string(),
        );
    }
    if report.implemented_obligation_count != contract.implemented_obligation_count {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report implemented count mismatch"
                .to_string(),
        );
    }
    if report.missing_obligation_count != contract.missing_obligation_count {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report missing count mismatch"
                .to_string(),
        );
    }
    if report.all_obligations_implemented != contract.all_obligations_implemented {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report acceptance flag mismatch"
                .to_string(),
        );
    }
    let obligations = reviewed_fq12_hidden_source_proof_acceptance_obligations(contract)?;
    for (index, obligation) in obligations.iter().enumerate() {
        if report.obligation_digests[index] != obligation.digest {
            return Err(
                "reviewed Fq12 hidden-source proof acceptance obligation report row digest mismatch"
                    .to_string(),
            );
        }
    }
    if reviewed_fq12_hidden_source_proof_acceptance_obligation_report_digest(report)
        != report.digest
    {
        return Err(
            "reviewed Fq12 hidden-source proof acceptance obligation report digest mismatch"
                .to_string(),
        );
    }
    Ok(())
}

pub fn reviewed_fq12_hidden_source_proof_readiness_report(
    deployment_report: &ProductionReviewedFq12DeploymentBlockerReport,
) -> Result<ProductionReviewedFq12HiddenSourceProofReadinessReport, String> {
    let deployment_report_digest =
        reviewed_fq12_deployment_blocker_report_digest(deployment_report);
    if deployment_report_digest != deployment_report.digest {
        return Err("reviewed Fq12 deployment blocker report digest mismatch".to_string());
    }
    let semantics_gate = reviewed_fq12_hidden_source_proof_semantics_gate(deployment_report)?;
    let acceptance_contract =
        reviewed_fq12_hidden_source_proof_acceptance_contract(&semantics_gate)?;
    let obligation_report =
        reviewed_fq12_hidden_source_proof_acceptance_obligation_report(&acceptance_contract)?;
    validate_reviewed_fq12_hidden_source_proof_acceptance_obligation_report(
        &acceptance_contract,
        &obligation_report,
    )?;
    let statement_digest =
        reviewed_fq12_hidden_source_statement_digest(&deployment_report.context.statement);
    let transcript = reviewed_fq12_hidden_source_proof_transcript(
        &deployment_report.context.statement,
        &deployment_report.context.proof,
    );
    if transcript != deployment_report.context.transcript {
        return Err("reviewed Fq12 hidden-source proof transcript mismatch".to_string());
    }
    let deployment_ready = semantics_gate.semantics_bridge_complete
        && semantics_gate.acceptance_implemented
        && acceptance_contract.all_obligations_implemented
        && obligation_report.all_obligations_implemented;
    let mut report = ProductionReviewedFq12HiddenSourceProofReadinessReport {
        digest: [0_u8; DIGEST_BYTES],
        deployment_report_digest,
        semantics_gate_digest: semantics_gate.digest,
        semantics_bridge_audit_digest: semantics_gate.semantics_bridge_audit_digest,
        acceptance_contract_digest: acceptance_contract.digest,
        obligation_report_digest: obligation_report.digest,
        hidden_source_statement_digest: statement_digest,
        hidden_source_transcript_digest: transcript.digest,
        proof_bytes: transcript.proof_bytes,
        semantics_bridge_complete: semantics_gate.semantics_bridge_complete,
        acceptance_implemented: semantics_gate.acceptance_implemented,
        required_obligation_count: obligation_report.required_obligation_count,
        implemented_obligation_count: obligation_report.implemented_obligation_count,
        missing_obligation_count: obligation_report.missing_obligation_count,
        all_obligations_implemented: obligation_report.all_obligations_implemented,
        deployment_ready,
        blocker: deployment_report.blocker,
    };
    report.digest = reviewed_fq12_hidden_source_proof_readiness_report_digest(&report);
    Ok(report)
}

pub fn reviewed_fq12_hidden_source_proof_readiness_report_digest(
    report: &ProductionReviewedFq12HiddenSourceProofReadinessReport,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_readiness_report_frame(
        report,
    ))
    .into()
}

pub fn validate_reviewed_fq12_hidden_source_proof_readiness_report(
    deployment_report: &ProductionReviewedFq12DeploymentBlockerReport,
    readiness_report: &ProductionReviewedFq12HiddenSourceProofReadinessReport,
) -> Result<(), String> {
    let expected = reviewed_fq12_hidden_source_proof_readiness_report(deployment_report)?;
    if expected != *readiness_report {
        return Err("reviewed Fq12 hidden-source proof readiness report mismatch".to_string());
    }
    if reviewed_fq12_hidden_source_proof_readiness_report_digest(readiness_report)
        != readiness_report.digest
    {
        return Err(
            "reviewed Fq12 hidden-source proof readiness report digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn reviewed_fq12_hidden_source_proof_readiness_verdict(
    readiness_report: &ProductionReviewedFq12HiddenSourceProofReadinessReport,
) -> Result<ProductionReviewedFq12HiddenSourceProofReadinessVerdict, String> {
    if reviewed_fq12_hidden_source_proof_readiness_report_digest(readiness_report)
        != readiness_report.digest
    {
        return Err(
            "reviewed Fq12 hidden-source proof readiness report digest mismatch".to_string(),
        );
    }
    let verdict = if readiness_report.deployment_ready {
        REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_READINESS_VERDICT_DEPLOYABLE
    } else {
        REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_READINESS_VERDICT_BLOCKED
    };
    let mut readiness_verdict = ProductionReviewedFq12HiddenSourceProofReadinessVerdict {
        digest: [0_u8; DIGEST_BYTES],
        readiness_report_digest: readiness_report.digest,
        verdict,
        deployment_ready: readiness_report.deployment_ready,
        missing_obligation_count: readiness_report.missing_obligation_count,
        blocker: readiness_report.blocker,
    };
    readiness_verdict.digest =
        reviewed_fq12_hidden_source_proof_readiness_verdict_digest(&readiness_verdict);
    Ok(readiness_verdict)
}

pub fn reviewed_fq12_hidden_source_proof_readiness_verdict_digest(
    verdict: &ProductionReviewedFq12HiddenSourceProofReadinessVerdict,
) -> [u8; DIGEST_BYTES] {
    Sha256::digest(reviewed_fq12_hidden_source_proof_readiness_verdict_frame(
        verdict,
    ))
    .into()
}

pub fn validate_reviewed_fq12_hidden_source_proof_readiness_verdict(
    readiness_report: &ProductionReviewedFq12HiddenSourceProofReadinessReport,
    verdict: &ProductionReviewedFq12HiddenSourceProofReadinessVerdict,
) -> Result<(), String> {
    let expected = reviewed_fq12_hidden_source_proof_readiness_verdict(readiness_report)?;
    if expected != *verdict {
        return Err("reviewed Fq12 hidden-source proof readiness verdict mismatch".to_string());
    }
    if reviewed_fq12_hidden_source_proof_readiness_verdict_digest(verdict) != verdict.digest {
        return Err(
            "reviewed Fq12 hidden-source proof readiness verdict digest mismatch".to_string(),
        );
    }
    Ok(())
}

pub fn require_reviewed_fq12_hidden_source_proof_deployable_verdict(
    readiness_report: &ProductionReviewedFq12HiddenSourceProofReadinessReport,
    verdict: &ProductionReviewedFq12HiddenSourceProofReadinessVerdict,
) -> Result<(), String> {
    validate_reviewed_fq12_hidden_source_proof_readiness_verdict(readiness_report, verdict)?;
    if verdict.verdict != REVIEWED_FQ12_HIDDEN_SOURCE_PROOF_READINESS_VERDICT_DEPLOYABLE {
        return Err(verdict.blocker.to_string());
    }
    if !verdict.deployment_ready {
        return Err(verdict.blocker.to_string());
    }
    if verdict.missing_obligation_count != 0 {
        return Err(verdict.blocker.to_string());
    }
    Ok(())
}

pub fn verify_reviewed_fq12_hidden_source_proof_acceptance_contract(
    gate: &ProductionReviewedFq12HiddenSourceProofSemanticsGate,
) -> Result<ProductionReviewedFq12HiddenSourceProofAcceptanceContract, String> {
    let contract = reviewed_fq12_hidden_source_proof_acceptance_contract(gate)?;
    validate_reviewed_fq12_hidden_source_proof_acceptance_contract(&contract)?;
    if !contract.all_obligations_implemented {
        return Err(contract.blocker.to_string());
    }
    Ok(contract)
}

pub fn verify_reviewed_fq12_hidden_source_proof_semantics_gate(
    report: &ProductionReviewedFq12DeploymentBlockerReport,
) -> Result<ProductionReviewedFq12HiddenSourceProofSemanticsGate, String> {
    let gate = reviewed_fq12_hidden_source_proof_semantics_gate(report)?;
    if reviewed_fq12_hidden_source_proof_semantics_gate_digest(&gate) != gate.digest {
        return Err("reviewed Fq12 hidden-source proof semantics gate digest mismatch".to_string());
    }
    if !gate.acceptance_implemented {
        return Err(gate.blocker.to_string());
    }
    Ok(gate)
}

