pub fn verify_reviewed_fq12_account_carried_hidden_source_proof<F>(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
    proof: &ProductionReviewedFq12HiddenSourceProof,
    verify_hidden_source_proof: F,
) -> Result<ProductionReviewedFq12HiddenSourceStatement, ProductionAccountBindingError>
where
    F: FnOnce(
        &ProductionReviewedFq12HiddenSourceStatement,
        &ProductionReviewedFq12HiddenSourceProof,
    ) -> Result<(), String>,
{
    verify_reviewed_fq12_account_carried_hidden_source_proof_with_transcript(
        public_key,
        message,
        account,
        signature,
        proof,
        |statement, proof, _transcript| verify_hidden_source_proof(statement, proof),
    )
}

pub fn verify_reviewed_fq12_account_carried_hidden_source_proof_with_transcript<F>(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
    proof: &ProductionReviewedFq12HiddenSourceProof,
    verify_hidden_source_proof: F,
) -> Result<ProductionReviewedFq12HiddenSourceStatement, ProductionAccountBindingError>
where
    F: FnOnce(
        &ProductionReviewedFq12HiddenSourceStatement,
        &ProductionReviewedFq12HiddenSourceProof,
        &ProductionReviewedFq12HiddenSourceProofTranscript,
    ) -> Result<(), String>,
{
    let statement = reviewed_fq12_account_carried_hidden_source_statement(
        public_key, message, account, signature,
    )?;
    let transcript = reviewed_fq12_hidden_source_proof_transcript(&statement, proof);
    verify_hidden_source_proof(&statement, proof, &transcript).map_err(|_| {
        ProductionAccountBindingError::new(
            Some(statement.slot_id),
            PRODUCTION_HIDDEN_SOURCE_PROOF_FAILURE_REASON,
        )
    })?;
    Ok(statement)
}

