pub fn reviewed_fq12_account_carried_signature_carried_hidden_source_proof_context(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature_with_proof: &ProductionSignature,
) -> Result<ProductionReviewedFq12HiddenSourceProofContext, ProductionAccountBindingError> {
    let decoded = decode_reviewed_fq12_account_carried_with_hidden_source_proof(
        signature_with_proof.as_bytes(),
    )
    .map_err(|err| ProductionAccountBindingError::new(None, err))?;
    let statement = reviewed_fq12_account_carried_hidden_source_statement(
        public_key,
        message,
        account,
        &decoded.signature,
    )?;
    let transcript =
        reviewed_fq12_hidden_source_proof_transcript(&statement, &decoded.hidden_source_proof);
    Ok(ProductionReviewedFq12HiddenSourceProofContext {
        statement,
        proof: decoded.hidden_source_proof,
        transcript,
    })
}

