fn require_reviewed_account_carried_challenge_binding(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    witness_commitment: &[u8; DIGEST_BYTES],
    signature: &ProductionSignature,
) -> Result<(), ProductionAccountBindingError> {
    if signature.as_bytes().len() != REVIEWED_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            format!(
                "reviewed account-carried signature has {} bytes, expected {REVIEWED_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES}",
                signature.as_bytes().len()
            ),
        ));
    }
    let parts = decode_reviewed_account_carried_signature(signature.as_bytes())
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let expected = challenge_bytes(
        public_key,
        message,
        slot_id,
        witness_commitment,
        &parts.proof.proof_commitment,
    );
    let claimed = &signature.as_bytes()[SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES];
    if claimed != expected {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            "reviewed account-carried challenge mismatch",
        ));
    }
    Ok(())
}

fn require_reviewed_fq12_account_carried_challenge_binding(
    public_key: &[u8],
    message: &[u8],
    slot_id: u32,
    witness_commitment: &[u8; DIGEST_BYTES],
    signature: &ProductionSignature,
) -> Result<(), ProductionAccountBindingError> {
    if signature.as_bytes().len() != REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            format!(
                "reviewed Fq12 account-carried signature has {} bytes, expected {REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES}",
                signature.as_bytes().len()
            ),
        ));
    }
    let parts = decode_reviewed_fq12_account_carried_signature(signature.as_bytes())
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    let expected = challenge_bytes(
        public_key,
        message,
        slot_id,
        witness_commitment,
        &parts.proof.proof_commitment,
    );
    let claimed = &signature.as_bytes()[SLOT_ID_BYTES..SLOT_ID_BYTES + CHALLENGE_BYTES];
    if claimed != expected {
        return Err(ProductionAccountBindingError::new(
            Some(slot_id),
            "reviewed Fq12 account-carried challenge mismatch",
        ));
    }
    Ok(())
}

pub fn verify_with_account_binding<R, F>(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
    verify_signature: F,
) -> Result<(ProductionVerifiedSignature, R), ProductionAccountBindingError>
where
    F: FnOnce(
        &ProductionPublicKey,
        &[u8],
        &ProductionAccountState,
        &ProductionSignature,
        &ProductionVerifiedSignature,
    ) -> Result<R, String>,
{
    let checked = verify_account_binding(account, signature)?;
    let slot_id = checked.slot_id();
    let result = verify_signature(public_key, message, account, signature, &checked)
        .map_err(|err| ProductionAccountBindingError::new(Some(slot_id), err))?;
    Ok((checked, result))
}

pub fn verify_with_account_binding_sanitized<R, F>(
    public_key: &ProductionPublicKey,
    message: &[u8],
    account: &ProductionAccountState,
    signature: &ProductionSignature,
    verify_signature: F,
) -> Result<(ProductionVerifiedSignature, R), ProductionAccountBindingError>
where
    F: FnOnce(
        &ProductionPublicKey,
        &[u8],
        &ProductionAccountState,
        &ProductionSignature,
        &ProductionVerifiedSignature,
    ) -> Result<R, String>,
{
    let checked = verify_account_binding(account, signature)?;
    let slot_id = checked.slot_id();
    let result =
        verify_signature(public_key, message, account, signature, &checked).map_err(|_| {
            ProductionAccountBindingError::new(
                Some(slot_id),
                PRODUCTION_VERIFIER_CALLBACK_FAILURE_REASON,
            )
        })?;
    Ok((checked, result))
}

pub fn consume_verified_signature(
    account: &ProductionAccountState,
    checked: &ProductionVerifiedSignature,
) -> Result<ProductionAccountState, String> {
    let slot = account
        .get_slot(checked.slot_id())
        .ok_or_else(|| "slot id is out of range".to_string())?;
    if !slot.is_unused() {
        return Err("slot is already consumed".to_string());
    }
    let mut next_account = account.clone();
    next_account.mark_consumed(checked.slot_id())?;
    Ok(next_account)
}

pub fn complete_verified_signature<R>(
    account: &ProductionAccountState,
    checked: ProductionVerifiedSignature,
    report: R,
    accepted: bool,
) -> Result<ProductionVerification<R>, ProductionVerificationRejection> {
    let next_account = if accepted {
        consume_verified_signature(account, &checked)
            .map_err(|err| ProductionVerificationRejection::new(Some(checked.slot_id()), err))?
    } else {
        account.clone()
    };
    Ok(ProductionVerification {
        checked,
        report,
        next_account,
    })
}

