#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProductionTrustedRestoreAnchorRecord {
    pub public_key_sha256: [u8; DIGEST_BYTES],
    pub minimum_snapshot_sequence: u64,
    pub placement: String,
}

impl ProductionTrustedRestoreAnchorRecord {
    pub fn new(
        public_key: &ProductionPublicKey,
        minimum_snapshot_sequence: u64,
        placement: impl Into<String>,
    ) -> Result<Self, ProductionLifecycleError> {
        let placement = placement.into();
        if !matches!(
            placement.as_str(),
            PRODUCTION_TRUSTED_RESTORE_ANCHOR_CHAIN_OBSERVED_PLACEMENT
                | "hardware_monotonic_counter"
                | "quorum_monotonic_anchor"
        ) {
            return Err(ProductionLifecycleError::new(
                None,
                "trusted restore anchor placement is not deployment-approved",
            ));
        }
        Ok(Self {
            public_key_sha256: ProductionSpentSlotLedger::key(public_key, 0).public_key_sha256,
            minimum_snapshot_sequence,
            placement,
        })
    }

    pub fn anchor(&self) -> ProductionLifecycleRestoreAnchor {
        ProductionLifecycleRestoreAnchor {
            minimum_snapshot_sequence: self.minimum_snapshot_sequence,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProductionTargetChainDatabaseAdapterProfile {
    pub schema: String,
    pub chain_id: String,
    pub canonical_database_engine: String,
    pub transaction_semantics: String,
    pub trusted_anchor_placement: String,
    pub kv_namespace: String,
    pub lifecycle_value_schema: String,
    pub spent_slots_value_schema: String,
    pub trusted_anchor_value_schema: String,
    pub public_key_identity: String,
    pub spent_key_shape: String,
    pub external_storage_review_digest: [u8; DIGEST_BYTES],
}

impl ProductionTargetChainDatabaseAdapterProfile {
    pub fn new(
        chain_id: impl Into<String>,
        canonical_database_engine: impl Into<String>,
        trusted_anchor_placement: impl Into<String>,
        external_storage_review_digest: [u8; DIGEST_BYTES],
    ) -> Self {
        Self {
            schema: PRODUCTION_TARGET_CHAIN_DATABASE_ADAPTER_PROFILE_SCHEMA.to_string(),
            chain_id: chain_id.into(),
            canonical_database_engine: canonical_database_engine.into(),
            transaction_semantics: PRODUCTION_TARGET_CHAIN_SINGLE_TRANSACTION_SEMANTICS.to_string(),
            trusted_anchor_placement: trusted_anchor_placement.into(),
            kv_namespace: PRODUCTION_TARGET_CHAIN_KV_NAMESPACE.to_string(),
            lifecycle_value_schema: PRODUCTION_TARGET_CHAIN_KV_LIFECYCLE_SCHEMA.to_string(),
            spent_slots_value_schema: PRODUCTION_TARGET_CHAIN_KV_SPENT_SCHEMA.to_string(),
            trusted_anchor_value_schema: PRODUCTION_TARGET_CHAIN_KV_ANCHOR_SCHEMA.to_string(),
            public_key_identity: "sha256(canonical_public_key_bytes)".to_string(),
            spent_key_shape: "namespace || 0x00 || public_key_sha256 || 0x00 || key_kind"
                .to_string(),
            external_storage_review_digest,
        }
    }

    pub fn validate(&self) -> Result<(), ProductionLifecycleError> {
        if self.schema != PRODUCTION_TARGET_CHAIN_DATABASE_ADAPTER_PROFILE_SCHEMA {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile schema mismatch",
            ));
        }
        if self.chain_id.trim().is_empty() {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile missing chain id",
            ));
        }
        let database_engine = self.canonical_database_engine.trim();
        if database_engine.is_empty() {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile missing canonical database engine",
            ));
        }
        if matches!(
            database_engine,
            "in_memory"
                | "file_backed_reference"
                | "ProductionInMemoryTransactionalKv"
                | "ProductionFileBackedTransactionalKv"
                | "placeholder"
        ) {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile uses a reference database engine",
            ));
        }
        if self.transaction_semantics != PRODUCTION_TARGET_CHAIN_SINGLE_TRANSACTION_SEMANTICS {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile lacks single transaction semantics",
            ));
        }
        if !matches!(
            self.trusted_anchor_placement.as_str(),
            PRODUCTION_TRUSTED_RESTORE_ANCHOR_CHAIN_OBSERVED_PLACEMENT
                | "hardware_monotonic_counter"
                | "quorum_monotonic_anchor"
        ) {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile has unapproved trusted anchor placement",
            ));
        }
        if self.trusted_anchor_placement == "account_state_backup" {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile uses restorable account backup anchor",
            ));
        }
        if self.kv_namespace != PRODUCTION_TARGET_CHAIN_KV_NAMESPACE {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile kv namespace mismatch",
            ));
        }
        if self.lifecycle_value_schema != PRODUCTION_TARGET_CHAIN_KV_LIFECYCLE_SCHEMA
            || self.spent_slots_value_schema != PRODUCTION_TARGET_CHAIN_KV_SPENT_SCHEMA
            || self.trusted_anchor_value_schema != PRODUCTION_TARGET_CHAIN_KV_ANCHOR_SCHEMA
        {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile kv value schema mismatch",
            ));
        }
        if self.public_key_identity != "sha256(canonical_public_key_bytes)" {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile public key identity mismatch",
            ));
        }
        if self.spent_key_shape != "namespace || 0x00 || public_key_sha256 || 0x00 || key_kind" {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile spent key shape mismatch",
            ));
        }
        if self.external_storage_review_digest == [0_u8; DIGEST_BYTES] {
            return Err(ProductionLifecycleError::new(
                None,
                "target-chain database adapter profile missing external storage review digest",
            ));
        }
        Ok(())
    }
}

pub fn validate_production_target_chain_database_adapter_profile(
    profile: &ProductionTargetChainDatabaseAdapterProfile,
) -> Result<(), ProductionLifecycleError> {
    profile.validate()
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionProfiledTargetChainKvDb<Kv> {
    profile: ProductionTargetChainDatabaseAdapterProfile,
    db: ProductionSelectedProjectionTargetChainKvDb<Kv>,
}

impl<Kv> ProductionProfiledTargetChainKvDb<Kv> {
    pub fn new(
        profile: ProductionTargetChainDatabaseAdapterProfile,
        kv: Kv,
    ) -> Result<Self, ProductionLifecycleError> {
        profile.validate()?;
        let type_name = std::any::type_name::<Kv>();
        if type_name.contains("ProductionInMemoryTransactionalKv")
            || type_name.contains("ProductionFileBackedTransactionalKv")
        {
            return Err(ProductionLifecycleError::new(
                None,
                "profiled target-chain kv db cannot wrap a reference kv engine",
            ));
        }
        Ok(Self {
            profile,
            db: ProductionSelectedProjectionTargetChainKvDb::new(kv),
        })
    }

    pub fn profile(&self) -> &ProductionTargetChainDatabaseAdapterProfile {
        &self.profile
    }

    pub fn db(&self) -> &ProductionSelectedProjectionTargetChainKvDb<Kv> {
        &self.db
    }

    pub fn db_mut(&mut self) -> &mut ProductionSelectedProjectionTargetChainKvDb<Kv> {
        &mut self.db
    }

    pub fn into_parts(
        self,
    ) -> (
        ProductionTargetChainDatabaseAdapterProfile,
        ProductionSelectedProjectionTargetChainKvDb<Kv>,
    ) {
        (self.profile, self.db)
    }
}

impl<Kv> ProductionProfiledTargetChainKvDb<Kv>
where
    Kv: ProductionTargetChainTransactionalKv,
{
    pub fn initialize_account_state(
        &mut self,
        public_key: &ProductionPublicKey,
        lifecycle_snapshot: ProductionReviewedFq12StateAssistedLifecycleSnapshot,
        trusted_anchor: ProductionTrustedRestoreAnchorRecord,
    ) -> Result<(), ProductionLifecycleError> {
        if trusted_anchor.placement != self.profile.trusted_anchor_placement {
            return Err(ProductionLifecycleError::new(
                None,
                "profiled target-chain kv db trusted anchor placement mismatch",
            ));
        }
        self.db
            .initialize_account_state(public_key, lifecycle_snapshot, trusted_anchor)
    }
}

impl<Kv> ProductionSelectedProjectionTargetChainDb for ProductionProfiledTargetChainKvDb<Kv>
where
    Kv: ProductionTargetChainTransactionalKv,
{
    fn load_selected_projection_lifecycle_snapshot(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<
        Option<ProductionReviewedFq12StateAssistedLifecycleSnapshot>,
        ProductionLifecycleError,
    > {
        self.db
            .load_selected_projection_lifecycle_snapshot(public_key)
    }

    fn load_selected_projection_spent_slot_records(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Vec<ProductionSpentSlotRecord>, ProductionLifecycleError> {
        self.db
            .load_selected_projection_spent_slot_records(public_key)
    }

    fn load_selected_projection_trusted_anchor(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Option<ProductionTrustedRestoreAnchorRecord>, ProductionLifecycleError> {
        self.db.load_selected_projection_trusted_anchor(public_key)
    }

    fn commit_selected_projection_transition(
        &mut self,
        public_key: &ProductionPublicKey,
        transition: ProductionSelectedProjectionConsensusTransition,
        trusted_anchor: ProductionTrustedRestoreAnchorRecord,
    ) -> Result<(), ProductionLifecycleError> {
        if trusted_anchor.placement != self.profile.trusted_anchor_placement {
            return Err(ProductionLifecycleError::new(
                None,
                "profiled target-chain kv db trusted anchor placement mismatch",
            ));
        }
        self.db
            .commit_selected_projection_transition(public_key, transition, trusted_anchor)
    }
}

pub trait ProductionCanonicalNodeKvStore {
    fn canonical_database_engine(&self) -> &str;

    fn load_committed_value(
        &self,
        profile: &ProductionTargetChainDatabaseAdapterProfile,
        key: &[u8],
    ) -> Result<Option<Vec<u8>>, ProductionLifecycleError>;

    fn commit_canonical_batch(
        &mut self,
        profile: &ProductionTargetChainDatabaseAdapterProfile,
        writes: Vec<ProductionTargetChainKvWrite>,
    ) -> Result<(), ProductionLifecycleError>;
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionCanonicalNodeKvAdapter<Store> {
    profile: ProductionTargetChainDatabaseAdapterProfile,
    store: Store,
}

impl<Store> ProductionCanonicalNodeKvAdapter<Store>
where
    Store: ProductionCanonicalNodeKvStore,
{
    pub fn new(
        profile: ProductionTargetChainDatabaseAdapterProfile,
        store: Store,
    ) -> Result<Self, ProductionLifecycleError> {
        profile.validate()?;
        let type_name = std::any::type_name::<Store>();
        if type_name.contains("ProductionInMemoryTransactionalKv")
            || type_name.contains("ProductionFileBackedTransactionalKv")
            || type_name.contains("ProductionInMemorySelectedProjectionTargetChainDb")
        {
            return Err(ProductionLifecycleError::new(
                None,
                "canonical node kv adapter cannot wrap a reference store",
            ));
        }
        if store.canonical_database_engine() != profile.canonical_database_engine {
            return Err(ProductionLifecycleError::new(
                None,
                "canonical node kv adapter engine mismatch",
            ));
        }
        Ok(Self { profile, store })
    }

    pub fn profile(&self) -> &ProductionTargetChainDatabaseAdapterProfile {
        &self.profile
    }

    pub fn store(&self) -> &Store {
        &self.store
    }

    pub fn store_mut(&mut self) -> &mut Store {
        &mut self.store
    }

    pub fn into_parts(self) -> (ProductionTargetChainDatabaseAdapterProfile, Store) {
        (self.profile, self.store)
    }
}

impl<Store> ProductionTargetChainTransactionalKv for ProductionCanonicalNodeKvAdapter<Store>
where
    Store: ProductionCanonicalNodeKvStore,
{
    fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>, ProductionLifecycleError> {
        self.store.load_committed_value(&self.profile, key)
    }

    fn commit_batch(
        &mut self,
        writes: Vec<ProductionTargetChainKvWrite>,
    ) -> Result<(), ProductionLifecycleError> {
        self.store.commit_canonical_batch(&self.profile, writes)
    }
}

pub fn production_profiled_target_chain_db_from_canonical_store<Store>(
    profile: ProductionTargetChainDatabaseAdapterProfile,
    store: Store,
) -> Result<
    ProductionProfiledTargetChainKvDb<ProductionCanonicalNodeKvAdapter<Store>>,
    ProductionLifecycleError,
>
where
    Store: ProductionCanonicalNodeKvStore,
{
    let adapter = ProductionCanonicalNodeKvAdapter::new(profile.clone(), store)?;
    ProductionProfiledTargetChainKvDb::new(profile, adapter)
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProductionTargetChainCanonicalStoreConformanceReport {
    pub schema: String,
    pub chain_id: String,
    pub canonical_database_engine: String,
    pub trusted_anchor_placement: String,
    pub public_key_sha256: [u8; DIGEST_BYTES],
    pub slot_id: u32,
    pub accepted_spend: ProductionSelectedProjectionConsensusSpendRecord,
    pub reloaded_snapshot_sequence: u64,
    pub reloaded_spent_record_count: usize,
    pub checks: Vec<String>,
}

pub fn production_canonical_node_store_conformance_check<Store, OpenStore>(
    profile: ProductionTargetChainDatabaseAdapterProfile,
    mut open_store: OpenStore,
    public_key: &ProductionPublicKey,
    lifecycle_snapshot: ProductionReviewedFq12StateAssistedLifecycleSnapshot,
    trusted_anchor: ProductionTrustedRestoreAnchorRecord,
    slot_id: u32,
    account_witness_opening_frame: &[u8],
) -> Result<ProductionTargetChainCanonicalStoreConformanceReport, ProductionLifecycleError>
where
    Store: ProductionCanonicalNodeKvStore,
    OpenStore: FnMut() -> Result<Store, ProductionLifecycleError>,
{
    profile.validate()?;
    let public_key_sha256 =
        ProductionInMemorySelectedProjectionTargetChainDb::public_key_hash(public_key);
    if trusted_anchor.public_key_sha256 != public_key_sha256 {
        return Err(ProductionLifecycleError::new(
            None,
            "canonical store conformance trusted anchor public key mismatch",
        ));
    }
    if trusted_anchor.placement != profile.trusted_anchor_placement {
        return Err(ProductionLifecycleError::new(
            None,
            "canonical store conformance trusted anchor placement mismatch",
        ));
    }

    let mut initial_db =
        production_profiled_target_chain_db_from_canonical_store(profile.clone(), open_store()?)?;
    initial_db.initialize_account_state(public_key, lifecycle_snapshot, trusted_anchor)?;

    let mut commit_db =
        production_profiled_target_chain_db_from_canonical_store(profile.clone(), open_store()?)?;
    let anchor = commit_db
        .load_selected_projection_trusted_anchor(public_key)?
        .ok_or_else(|| {
            ProductionLifecycleError::new(None, "canonical store conformance missing anchor")
        })?;
    let snapshot = commit_db
        .load_selected_projection_lifecycle_snapshot(public_key)?
        .ok_or_else(|| {
            ProductionLifecycleError::new(None, "canonical store conformance missing lifecycle")
        })?;
    let spent_slot_records = commit_db.load_selected_projection_spent_slot_records(public_key)?;
    let transition = apply_selected_projection_consensus_opening_frame(
        snapshot,
        spent_slot_records,
        anchor.anchor(),
        public_key,
        slot_id,
        account_witness_opening_frame,
    )?;
    let next_anchor = ProductionTrustedRestoreAnchorRecord::new(
        public_key,
        transition.next_lifecycle_snapshot.snapshot_sequence,
        profile.trusted_anchor_placement.clone(),
    )?;
    let accepted_spend = transition.spend_record.clone();
    commit_db.commit_selected_projection_transition(public_key, transition, next_anchor)?;

    let reloaded_db =
        production_profiled_target_chain_db_from_canonical_store(profile.clone(), open_store()?)?;
    let reloaded_snapshot = reloaded_db
        .load_selected_projection_lifecycle_snapshot(public_key)?
        .ok_or_else(|| {
            ProductionLifecycleError::new(None, "canonical store conformance reload lost lifecycle")
        })?;
    let reloaded_anchor = reloaded_db
        .load_selected_projection_trusted_anchor(public_key)?
        .ok_or_else(|| {
            ProductionLifecycleError::new(None, "canonical store conformance reload lost anchor")
        })?;
    let reloaded_spent_slot_records =
        reloaded_db.load_selected_projection_spent_slot_records(public_key)?;
    if reloaded_snapshot.snapshot_sequence != accepted_spend.snapshot_sequence {
        return Err(ProductionLifecycleError::new(
            None,
            "canonical store conformance reloaded snapshot sequence mismatch",
        ));
    }
    if reloaded_anchor.minimum_snapshot_sequence != accepted_spend.snapshot_sequence {
        return Err(ProductionLifecycleError::new(
            None,
            "canonical store conformance reloaded anchor sequence mismatch",
        ));
    }
    if !reloaded_spent_slot_records
        .iter()
        .any(|record| record.key == accepted_spend.spent_record.key)
    {
        return Err(ProductionLifecycleError::new(
            None,
            "canonical store conformance reload lost spent record",
        ));
    }
    let replay_err = apply_selected_projection_consensus_opening_frame(
        reloaded_snapshot.clone(),
        reloaded_spent_slot_records.clone(),
        reloaded_anchor.anchor(),
        public_key,
        slot_id,
        account_witness_opening_frame,
    )
    .unwrap_err();
    if replay_err.reason() != "slot is already in spent ledger" {
        return Err(ProductionLifecycleError::new(
            None,
            format!(
                "canonical store conformance replay check failed: {}",
                replay_err.reason()
            ),
        ));
    }

    Ok(ProductionTargetChainCanonicalStoreConformanceReport {
        schema: "Descender.production_target_chain_canonical_store_conformance.v1".to_string(),
        chain_id: profile.chain_id,
        canonical_database_engine: profile.canonical_database_engine,
        trusted_anchor_placement: profile.trusted_anchor_placement,
        public_key_sha256,
        slot_id,
        accepted_spend,
        reloaded_snapshot_sequence: reloaded_snapshot.snapshot_sequence,
        reloaded_spent_record_count: reloaded_spent_slot_records.len(),
        checks: vec![
            "profile validates".to_string(),
            "account state initializes through profiled canonical store".to_string(),
            "selected-projection spend commits through canonical batch".to_string(),
            "lifecycle snapshot reloads after reopen".to_string(),
            "trusted anchor reloads after reopen".to_string(),
            "spent ledger reloads after reopen".to_string(),
            "replay is rejected from reloaded state".to_string(),
        ],
    })
}

