impl ProductionTrustedRestoreAnchorFileStore {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn lock_path(&self) -> PathBuf {
        let mut file_name = self
            .path
            .file_name()
            .map(|name| name.to_os_string())
            .unwrap_or_else(|| "trusted_restore_anchor".into());
        file_name.push(".lock");
        self.path.with_file_name(file_name)
    }

    pub fn try_lock(
        &self,
    ) -> Result<ProductionTrustedRestoreAnchorStoreLock, ProductionLifecycleError> {
        let lock_path = self.lock_path();
        if let Some(parent) = lock_path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
        {
            fs::create_dir_all(parent).map_err(|err| {
                self.io_error_for_path("create trusted restore anchor lock dir", parent, err)
            })?;
        }
        let mut file = match OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(file) => file,
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
                return Err(ProductionLifecycleError::new(
                    None,
                    "trusted restore anchor store is locked",
                ));
            }
            Err(err) => {
                return Err(self.io_error_for_path(
                    "create trusted restore anchor lock",
                    &lock_path,
                    err,
                ));
            }
        };
        writeln!(file, "pid={}", std::process::id()).map_err(|err| {
            self.io_error_for_path("write trusted restore anchor lock", &lock_path, err)
        })?;
        file.sync_all().map_err(|err| {
            self.io_error_for_path("sync trusted restore anchor lock", &lock_path, err)
        })?;
        Ok(ProductionTrustedRestoreAnchorStoreLock {
            path: lock_path,
            _file: file,
        })
    }

    pub fn load_records(
        &self,
    ) -> Result<Vec<ProductionTrustedRestoreAnchorRecord>, ProductionLifecycleError> {
        let bytes = match fs::read(&self.path) {
            Ok(bytes) => bytes,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(err) => return Err(self.io_error("read trusted restore anchor store", err)),
        };
        let file: ProductionTrustedRestoreAnchorStoreFile = serde_json::from_slice(&bytes)
            .map_err(|err| {
                ProductionLifecycleError::new(
                    None,
                    format!(
                        "decode trusted restore anchor store {}: {err}",
                        self.path.display()
                    ),
                )
            })?;
        if file.schema != PRODUCTION_TRUSTED_RESTORE_ANCHOR_SCHEMA {
            return Err(ProductionLifecycleError::new(
                None,
                "trusted restore anchor schema mismatch",
            ));
        }
        let mut seen = BTreeMap::new();
        for record in &file.records {
            if seen.insert(record.public_key_sha256, ()).is_some() {
                return Err(ProductionLifecycleError::new(
                    None,
                    "duplicate trusted restore anchor record",
                ));
            }
        }
        Ok(file.records)
    }

    pub fn load_anchor_record(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<Option<ProductionTrustedRestoreAnchorRecord>, ProductionLifecycleError> {
        let public_key_sha256 = ProductionSpentSlotLedger::key(public_key, 0).public_key_sha256;
        Ok(self
            .load_records()?
            .into_iter()
            .find(|record| record.public_key_sha256 == public_key_sha256))
    }

    pub fn require_anchor(
        &self,
        public_key: &ProductionPublicKey,
    ) -> Result<ProductionLifecycleRestoreAnchor, ProductionLifecycleError> {
        self.load_anchor_record(public_key)?
            .map(|record| record.anchor())
            .ok_or_else(|| {
                ProductionLifecycleError::new(None, "missing trusted restore anchor record")
            })
    }

    pub fn update_monotonic(
        &self,
        record: ProductionTrustedRestoreAnchorRecord,
    ) -> Result<ProductionTrustedRestoreAnchorRecord, ProductionLifecycleError> {
        let mut records = self.load_records()?;
        for existing in &mut records {
            if existing.public_key_sha256 == record.public_key_sha256 {
                if existing.placement != record.placement {
                    return Err(ProductionLifecycleError::new(
                        None,
                        "trusted restore anchor placement mismatch",
                    ));
                }
                existing.minimum_snapshot_sequence = existing
                    .minimum_snapshot_sequence
                    .max(record.minimum_snapshot_sequence);
                let out = existing.clone();
                self.save_records(&records)?;
                return Ok(out);
            }
        }
        records.push(record.clone());
        self.save_records(&records)?;
        Ok(record)
    }

    fn save_records(
        &self,
        records: &[ProductionTrustedRestoreAnchorRecord],
    ) -> Result<(), ProductionLifecycleError> {
        let file = ProductionTrustedRestoreAnchorStoreFile {
            schema: PRODUCTION_TRUSTED_RESTORE_ANCHOR_SCHEMA.to_string(),
            records: records.to_vec(),
        };
        let mut bytes = serde_json::to_vec_pretty(&file).map_err(|err| {
            ProductionLifecycleError::new(
                None,
                format!("encode trusted restore anchor store: {err}"),
            )
        })?;
        bytes.push(b'\n');
        self.atomic_write(&bytes)
    }

    fn atomic_write(&self, bytes: &[u8]) -> Result<(), ProductionLifecycleError> {
        if let Some(parent) = self
            .path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
        {
            fs::create_dir_all(parent)
                .map_err(|err| self.io_error("create trusted restore anchor store dir", err))?;
        }
        let tmp_path = self.tmp_path();
        let mut file = File::create(&tmp_path)
            .map_err(|err| self.io_error("create temp trusted restore anchor store", err))?;
        file.write_all(bytes)
            .map_err(|err| self.io_error("write temp trusted restore anchor store", err))?;
        file.sync_all()
            .map_err(|err| self.io_error("sync temp trusted restore anchor store", err))?;
        drop(file);
        fs::rename(&tmp_path, &self.path)
            .map_err(|err| self.io_error("commit trusted restore anchor store", err))?;
        Ok(())
    }

    fn tmp_path(&self) -> PathBuf {
        let mut file_name = self
            .path
            .file_name()
            .map(|name| name.to_os_string())
            .unwrap_or_else(|| "trusted_restore_anchor".into());
        file_name.push(".tmp");
        self.path.with_file_name(file_name)
    }

    fn io_error(&self, action: &str, err: std::io::Error) -> ProductionLifecycleError {
        self.io_error_for_path(action, &self.path, err)
    }

    fn io_error_for_path(
        &self,
        action: &str,
        path: &Path,
        err: std::io::Error,
    ) -> ProductionLifecycleError {
        ProductionLifecycleError::new(None, format!("{action} {}: {err}", path.display()))
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductionChainStateFileStores {
    lifecycle_store: ProductionLifecycleFileStore,
    spent_ledger_store: ProductionSpentSlotLedgerFileStore,
}

impl ProductionChainStateFileStores {
    pub fn new(lifecycle_path: impl Into<PathBuf>, spent_ledger_path: impl Into<PathBuf>) -> Self {
        Self {
            lifecycle_store: ProductionLifecycleFileStore::new(lifecycle_path),
            spent_ledger_store: ProductionSpentSlotLedgerFileStore::new(spent_ledger_path),
        }
    }

    pub fn lifecycle_store(&self) -> &ProductionLifecycleFileStore {
        &self.lifecycle_store
    }

    pub fn spent_ledger_store(&self) -> &ProductionSpentSlotLedgerFileStore {
        &self.spent_ledger_store
    }

    pub fn verify_consume_record_and_save<R, F>(
        &self,
        restore_anchor: Option<ProductionLifecycleRestoreAnchor>,
        public_key: &ProductionPublicKey,
        message: &[u8],
        signature: &ProductionSignature,
        verify_signature: F,
    ) -> Result<ProductionVerification<R>, ProductionLifecycleError>
    where
        F: FnOnce(
            &ProductionPublicKey,
            &[u8],
            &ProductionAccountState,
            &ProductionSignature,
            &ProductionVerifiedSignature,
        ) -> Result<R, String>,
    {
        let _lifecycle_lock = self.lifecycle_store.try_lock()?;
        let _ledger_lock = self.spent_ledger_store.try_lock()?;
        let mut manager = match restore_anchor {
            Some(anchor) => self
                .lifecycle_store
                .load_manager_with_restore_anchor(anchor)?,
            None => self.lifecycle_store.load_manager()?,
        }
        .ok_or_else(|| ProductionLifecycleError::new(None, "missing lifecycle account state"))?;
        let mut ledger = self
            .spent_ledger_store
            .load_ledger()?
            .unwrap_or_else(ProductionSpentSlotLedger::new);
        let verification = manager.verify_consume_and_record_spent(
            &mut ledger,
            public_key,
            message,
            signature,
            verify_signature,
        )?;
        self.spent_ledger_store.save_ledger(&ledger)?;
        self.lifecycle_store.save_manager(&manager)?;
        Ok(verification)
    }

    pub fn verify_consume_record_and_save_sanitized<R, F>(
        &self,
        restore_anchor: Option<ProductionLifecycleRestoreAnchor>,
        public_key: &ProductionPublicKey,
        message: &[u8],
        signature: &ProductionSignature,
        verify_signature: F,
    ) -> Result<ProductionVerification<R>, ProductionLifecycleError>
    where
        F: FnOnce(
            &ProductionPublicKey,
            &[u8],
            &ProductionAccountState,
            &ProductionSignature,
            &ProductionVerifiedSignature,
        ) -> Result<R, String>,
    {
        let _lifecycle_lock = self.lifecycle_store.try_lock()?;
        let _ledger_lock = self.spent_ledger_store.try_lock()?;
        let mut manager = match restore_anchor {
            Some(anchor) => self
                .lifecycle_store
                .load_manager_with_restore_anchor(anchor)?,
            None => self.lifecycle_store.load_manager()?,
        }
        .ok_or_else(|| ProductionLifecycleError::new(None, "missing lifecycle account state"))?;
        let mut ledger = self
            .spent_ledger_store
            .load_ledger()?
            .unwrap_or_else(ProductionSpentSlotLedger::new);
        let verification = manager.verify_consume_and_record_spent_sanitized(
            &mut ledger,
            public_key,
            message,
            signature,
            verify_signature,
        )?;
        self.spent_ledger_store.save_ledger(&ledger)?;
        self.lifecycle_store.save_manager(&manager)?;
        Ok(verification)
    }
}

