pub fn decode_reviewed_fq12_account_carried_with_hidden_source_proof(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12AccountCarriedWithHiddenSourceProof, String> {
    if bytes.len() != REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_HIDDEN_SOURCE_PROOF_BYTES {
        return Err(format!(
            "reviewed Fq12 account-carried signature plus hidden-source proof has {} bytes, expected {REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_HIDDEN_SOURCE_PROOF_BYTES}",
            bytes.len()
        ));
    }
    let signature = ProductionSignature::new(
        bytes[..REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES].to_vec(),
    );
    decode_reviewed_fq12_account_carried_signature(signature.as_bytes())?;
    let hidden_source_proof = ProductionReviewedFq12HiddenSourceProof::from_bytes(
        &bytes[REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES..],
    )?;
    Ok(ProductionReviewedFq12AccountCarriedWithHiddenSourceProof {
        signature,
        hidden_source_proof,
    })
}

pub fn decode_reviewed_fq12_account_carried_with_fallback_projection(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12AccountCarriedWithFallbackProjection, String> {
    if bytes.len() != REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_FALLBACK_PROJECTION_BYTES {
        return Err(format!(
            "reviewed Fq12 account-carried signature plus fallback projection carrier has {} bytes, expected {REVIEWED_FQ12_ACCOUNT_CARRIED_WITH_FALLBACK_PROJECTION_BYTES}",
            bytes.len()
        ));
    }
    let signature = ProductionSignature::new(
        bytes[..REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES].to_vec(),
    );
    decode_reviewed_fq12_account_carried_signature(signature.as_bytes())?;
    let projection_carrier = HiddenSourceFallbackProjectionCarrier::from_bytes(
        &bytes[REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES..],
    )?;
    let decoded_carrier = projection_carrier.decode()?;
    Ok(ProductionReviewedFq12AccountCarriedWithFallbackProjection {
        signature,
        projection_carrier,
        decoded_carrier,
    })
}

pub fn decode_challenge(bytes: &[u8]) -> Result<ProductionCompactChallenge, String> {
    if bytes.len() != CHALLENGE_BYTES {
        return Err(format!(
            "challenge has {} bytes, expected {CHALLENGE_BYTES}",
            bytes.len()
        ));
    }
    if (bytes[ALGEBRAIC_CHALLENGE_BYTES - 1] & !ALGEBRAIC_CHALLENGE_LAST_BYTE_MASK) != 0 {
        return Err("challenge is not canonical: high bits are set".to_string());
    }
    let mut active_block = [0_usize; REPS];
    let mut sign = [0_i8; REPS];
    for rep in 0..REPS {
        let bit = rep * CHALLENGE_BITS_PER_REP;
        active_block[rep] = read_bits_le(bytes, bit, 4) as usize;
        if active_block[rep] >= GROUPS {
            return Err(format!(
                "challenge active block in round {rep} is out of range: {}",
                active_block[rep]
            ));
        }
        sign[rep] = if read_bits_le(bytes, bit + 4, 1) == 0 {
            1
        } else {
            -1
        };
    }
    Ok(ProductionCompactChallenge { active_block, sign })
}

pub fn decode_responses(bytes: &[u8]) -> Result<ProductionCompactResponses, String> {
    if bytes.len() != ACTIVE_RESPONSE_BYTES {
        return Err(format!(
            "response payload has {} bytes, expected {ACTIVE_RESPONSE_BYTES}",
            bytes.len()
        ));
    }
    let mut active_free = [[0_i16; LOCAL_FREE]; REPS];
    for rep in 0..REPS {
        for coord in 0..LOCAL_FREE {
            let raw = bytes[rep * LOCAL_FREE + coord];
            if raw > (2 * RESPONSE_BOUND) as u8 {
                return Err(format!(
                    "active response coordinate {coord} in round {rep} is non-canonical: {raw}"
                ));
            }
            active_free[rep][coord] = raw as i16 - RESPONSE_BOUND;
        }
    }
    Ok(ProductionCompactResponses { active_free })
}

pub fn decode_openings(bytes: &[u8]) -> Result<ProductionLocalOpenings, String> {
    if bytes.len() != LOCAL_OPENING_BYTES {
        return Err(format!(
            "opening payload has {} bytes, expected {LOCAL_OPENING_BYTES}",
            bytes.len()
        ));
    }
    let mut active_free = [[0_u16; LOCAL_FREE]; REPS];
    for rep in 0..REPS {
        let base = rep * LOCAL_OPENING_BYTES_PER_REP;
        let pair = [
            u16::from_le_bytes(bytes[base..base + 2].try_into().unwrap()),
            u16::from_le_bytes(bytes[base + 2..base + 4].try_into().unwrap()),
        ];
        for (coord, &value) in pair.iter().enumerate() {
            if value >= Q {
                return Err(format!(
                    "opening coordinate {coord} in round {rep} is non-canonical: {value}"
                ));
            }
            active_free[rep][coord] = value;
        }
    }
    Ok(ProductionLocalOpenings { active_free })
}

pub fn decode_linear_sigma_target_proof(
    bytes: &[u8],
) -> Result<ProductionLinearSigmaTargetProof, String> {
    if bytes.len() != LINEAR_SIGMA_TARGET_PROOF_BYTES {
        return Err(format!(
            "linear sigma proof has {} bytes, expected {LINEAR_SIGMA_TARGET_PROOF_BYTES}",
            bytes.len()
        ));
    }
    Ok(ProductionLinearSigmaTargetProof {
        proof_commitment: bytes[..LINEAR_SIGMA_PROOF_COMMITMENT_BYTES]
            .try_into()
            .unwrap(),
        masked_witness_response: bytes[LINEAR_SIGMA_PROOF_COMMITMENT_BYTES..]
            .try_into()
            .unwrap(),
    })
}

pub fn decode_reviewed_account_carried_proof(
    bytes: &[u8],
) -> Result<ProductionReviewedAccountCarriedProof, String> {
    if bytes.len() != REVIEWED_ACCOUNT_CARRIED_PROOF_BYTES {
        return Err(format!(
            "reviewed account-carried proof has {} bytes, expected {REVIEWED_ACCOUNT_CARRIED_PROOF_BYTES}",
            bytes.len()
        ));
    }
    let masked_quotient_response: [u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES] = bytes
        [LINEAR_SIGMA_PROOF_COMMITMENT_BYTES..]
        .try_into()
        .unwrap();
    unpack_reviewed_account_carried_masked_response(&masked_quotient_response)?;
    Ok(ProductionReviewedAccountCarriedProof {
        proof_commitment: bytes[..LINEAR_SIGMA_PROOF_COMMITMENT_BYTES]
            .try_into()
            .unwrap(),
        masked_quotient_response,
    })
}

pub fn decode_reviewed_fq12_account_carried_proof(
    bytes: &[u8],
) -> Result<ProductionReviewedFq12AccountCarriedProof, String> {
    if bytes.len() != REVIEWED_FQ12_ACCOUNT_CARRIED_PROOF_BYTES {
        return Err(format!(
            "reviewed Fq12 account-carried proof has {} bytes, expected {REVIEWED_FQ12_ACCOUNT_CARRIED_PROOF_BYTES}",
            bytes.len()
        ));
    }
    let masked_quotient_response: [u8; REVIEWED_FQ12_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES] = bytes
        [LINEAR_SIGMA_PROOF_COMMITMENT_BYTES..]
        .try_into()
        .unwrap();
    unpack_reviewed_fq12_account_carried_masked_response(&masked_quotient_response)?;
    Ok(ProductionReviewedFq12AccountCarriedProof {
        proof_commitment: bytes[..LINEAR_SIGMA_PROOF_COMMITMENT_BYTES]
            .try_into()
            .unwrap(),
        masked_quotient_response,
    })
}

pub fn unpack_reviewed_account_carried_masked_response(
    bytes: &[u8; REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BYTES],
) -> Result<[u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES], String> {
    if any_bits_set_le(
        bytes,
        REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_BITS,
        REVIEWED_ACCOUNT_CARRIED_MASKED_RESPONSE_SLACK_BITS,
    ) {
        return Err("reviewed masked response is not canonical: high bits are set".to_string());
    }
    let mut out = [0_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES];
    for (idx, value) in out.iter_mut().enumerate() {
        let decoded = read_bits_le(bytes, idx * FIELD_BITS, FIELD_BITS);
        if decoded >= Q as u32 {
            return Err(format!(
                "reviewed masked response residue {idx} is non-canonical: {decoded}"
            ));
        }
        *value = decoded as u16;
    }
    Ok(out)
}

