    #[test]
    fn reviewed_account_carried_account_binding_checks_slot_and_randomizer() {
        let witness = pack_reviewed_account_carried_syndrome_digest(
            &[1_u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let randomizer = pack_reviewed_account_carried_syndrome_digest(
            &[7_u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let commitment = ProductionAccountCommitment::new(witness, randomizer);
        let account =
            ProductionAccountState::new(vec![ProductionAccountSlot::new(0, commitment)]).unwrap();
        let slot = account.get_slot(0).unwrap();
        let challenge_bytes = [0_u8; CHALLENGE_BYTES];
        let responses = ProductionCompactResponses {
            active_free: [[0_i16; LOCAL_FREE]; REPS],
        };
        let openings = ProductionLocalOpenings {
            active_free: [[1_u16; LOCAL_FREE]; REPS],
        };
        let proof = ProductionReviewedAccountCarriedProof {
            proof_commitment: randomizer,
            masked_quotient_response: encode_reviewed_account_carried_masked_response(
                &[0_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES],
            )
            .unwrap(),
        };
        let signature = encode_reviewed_account_carried_signature(
            0,
            &challenge_bytes,
            &responses,
            &openings,
            &proof,
        )
        .unwrap();

        let signed = sign_reviewed_account_carried_with_account_binding(
            slot,
            |slot_id, witness_commitment| {
                assert_eq!(slot_id, 0);
                assert_eq!(witness_commitment, witness);
                Ok(signature.clone())
            },
        )
        .unwrap();
        assert_eq!(signed, signature);

        let checked =
            verify_reviewed_account_carried_account_binding(&account, &signature).unwrap();
        assert_eq!(checked.slot_id, 0);

        let mut mismatch = signature.as_bytes().to_vec();
        let proof_start = STATEFUL_TRANSACTION_SIGNATURE_BYTES;
        mismatch[proof_start] ^= 1;
        let err = verify_reviewed_account_carried_account_binding(
            &account,
            &ProductionSignature::new(mismatch),
        )
        .unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(err.reason(), "account randomizer commitment mismatch");

        let mut loose_digest = witness;
        loose_digest[REVIEWED_ACCOUNT_CARRIED_SYNDROME_PACKED_BITS / 8] |=
            1 << (REVIEWED_ACCOUNT_CARRIED_SYNDROME_PACKED_BITS % 8);
        let loose_commitment = ProductionAccountCommitment::new(loose_digest, randomizer);
        let loose_account =
            ProductionAccountState::new(vec![ProductionAccountSlot::new(0, loose_commitment)])
                .unwrap();
        let err = verify_reviewed_account_carried_account_binding(&loose_account, &signature)
            .unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(
            err.reason(),
            "reviewed account-carried syndrome digest is not canonical: high bits are set"
        );
    }

    #[test]
    fn reviewed_account_carried_transcript_binding_checks_fiat_shamir_frame() {
        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let message = b"reviewed account-carried transcript binding";
        let witness = pack_reviewed_account_carried_syndrome_digest(
            &[1_u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let randomizer = pack_reviewed_account_carried_syndrome_digest(
            &[7_u16; REVIEWED_ACCOUNT_CARRIED_PUBLIC_ROWS],
        )
        .unwrap();
        let commitment = ProductionAccountCommitment::new(witness, randomizer);
        let account =
            ProductionAccountState::new(vec![ProductionAccountSlot::new(0, commitment)]).unwrap();
        let slot = account.get_slot(0).unwrap();
        let proof = ProductionReviewedAccountCarriedProof {
            proof_commitment: randomizer,
            masked_quotient_response: encode_reviewed_account_carried_masked_response(
                &[0_u16; REVIEWED_ACCOUNT_CARRIED_RESPONSE_RESIDUES],
            )
            .unwrap(),
        };
        let challenge = challenge_bytes(
            public_key.as_bytes(),
            message,
            0,
            &witness,
            &proof.proof_commitment,
        );
        let signature = encode_reviewed_account_carried_signature(
            0,
            &challenge,
            &ProductionCompactResponses {
                active_free: [[0_i16; LOCAL_FREE]; REPS],
            },
            &ProductionLocalOpenings {
                active_free: [[1_u16; LOCAL_FREE]; REPS],
            },
            &proof,
        )
        .unwrap();

        let signed = sign_reviewed_account_carried_with_transcript_binding(
            &public_key,
            message,
            slot,
            |_slot_id, _witness_commitment| Ok(signature.clone()),
        )
        .unwrap();
        assert_eq!(signed, signature);
        let checked = verify_reviewed_account_carried_transcript_binding(
            &public_key,
            message,
            &account,
            &signature,
        )
        .unwrap();
        assert_eq!(checked.slot_id, 0);

        let err = verify_reviewed_account_carried_transcript_binding(
            &public_key,
            b"different message",
            &account,
            &signature,
        )
        .unwrap_err();
        assert_eq!(err.slot_id(), Some(0));
        assert_eq!(err.reason(), "reviewed account-carried challenge mismatch");

        let stale_challenge = [0_u8; CHALLENGE_BYTES];
        let stale_signature = encode_reviewed_account_carried_signature(
            0,
            &stale_challenge,
            &ProductionCompactResponses {
                active_free: [[0_i16; LOCAL_FREE]; REPS],
            },
            &ProductionLocalOpenings {
                active_free: [[1_u16; LOCAL_FREE]; REPS],
            },
            &proof,
        )
        .unwrap();
        let err = sign_reviewed_account_carried_with_transcript_binding(
            &public_key,
            message,
            slot,
            |_slot_id, _witness_commitment| Ok(stale_signature),
        )
        .unwrap_err();
        assert_eq!(err, "reviewed account-carried challenge mismatch");
    }

