    #[test]
    fn path2_native_projection_preimage_encoders_have_stable_layouts() {
        let (context, account, spend, lifecycle, state) = native_projection_fixtures();

        let context_bytes = path2_native_context_projection_v1_bytes(&context).unwrap();
        assert!(context_bytes.starts_with(PATH2_NATIVE_PROJECTION_CONTEXT_DOMAIN.as_bytes()));
        let mut offset = PATH2_NATIVE_PROJECTION_CONTEXT_DOMAIN.len();
        assert_eq!(
            u16::from_le_bytes([context_bytes[offset], context_bytes[offset + 1]]),
            PATH2_NATIVE_CHECKED_CORE_FRAME_VERSION
        );
        offset += 2 + 2 + 2;
        assert_eq!(
            &context_bytes[offset..offset + DIGEST_BYTES],
            &repeated_digest(0x11)
        );
        assert_eq!(
            context_bytes[context_bytes.len() - 1],
            PATH2_NATIVE_AGGREGATION_MODE_DIRECT
        );
        let expected_context_digest: [u8; DIGEST_BYTES] = Sha256::digest(&context_bytes).into();
        assert_eq!(
            path2_native_context_projection_v1_digest(&context).unwrap(),
            expected_context_digest
        );

        let account_bytes = path2_native_account_projection_v1_bytes(&account);
        assert!(account_bytes.starts_with(PATH2_NATIVE_PROJECTION_ACCOUNT_DOMAIN.as_bytes()));
        assert_eq!(
            account_bytes.len(),
            PATH2_NATIVE_PROJECTION_ACCOUNT_DOMAIN.len() + DIGEST_BYTES * 5
        );
        let expected_account_digest: [u8; DIGEST_BYTES] = Sha256::digest(&account_bytes).into();
        assert_eq!(
            path2_native_account_projection_v1_digest(&account),
            expected_account_digest
        );

        let spend_bytes = path2_native_spend_projection_v1_bytes(&spend).unwrap();
        assert!(spend_bytes.starts_with(PATH2_NATIVE_PROJECTION_SPEND_DOMAIN.as_bytes()));
        assert!(
            spend_bytes
                .windows(DIGEST_BYTES)
                .any(|w| w == spend.spend_authorization_class_digest)
        );
        let expected_spend_digest: [u8; DIGEST_BYTES] = Sha256::digest(&spend_bytes).into();
        assert_eq!(
            path2_native_spend_projection_v1_digest(&spend).unwrap(),
            expected_spend_digest
        );

        let lifecycle_bytes = path2_native_lifecycle_projection_v1_bytes(&lifecycle);
        assert!(lifecycle_bytes.starts_with(PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN.as_bytes()));
        assert_eq!(
            u64::from_le_bytes(
                lifecycle_bytes[PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN.len()
                    ..PATH2_NATIVE_PROJECTION_LIFECYCLE_DOMAIN.len() + 8]
                    .try_into()
                    .unwrap()
            ),
            7
        );

        let state_bytes = path2_native_state_projection_v1_bytes(&state);
        assert!(state_bytes.starts_with(PATH2_NATIVE_PROJECTION_STATE_DOMAIN.as_bytes()));
        assert_eq!(
            state_bytes[PATH2_NATIVE_PROJECTION_STATE_DOMAIN.len() + DIGEST_BYTES * 2],
            1
        );
    }

    #[test]
    fn path2_native_projection_mutations_cascade_to_transcript_and_boundary() {
        let (context, account, spend, lifecycle, state) = native_projection_fixtures();
        let context_digest = path2_native_context_projection_v1_digest(&context).unwrap();
        let account_digest = path2_native_account_projection_v1_digest(&account);
        let spend_digest = path2_native_spend_projection_v1_digest(&spend).unwrap();
        let lifecycle_digest = path2_native_lifecycle_projection_v1_digest(&lifecycle);
        let state_digest = path2_native_state_projection_v1_digest(&state);
        let checked_core_frame_domain_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes()).into();
        let transcript = Path2NativeTranscriptProjectionV1 {
            native_boundary_digest: repeated_digest(0x61),
            p_context_digest: context_digest,
            p_account_digest: account_digest,
            p_spend_digest: spend_digest,
            p_lifecycle_digest: lifecycle_digest,
            p_state_digest: state_digest,
            checked_core_frame_domain_digest,
            aggregation_mode: PATH2_NATIVE_AGGREGATION_MODE_DIRECT,
        };
        let transcript_digest = path2_native_transcript_projection_v1_digest(&transcript).unwrap();
        let boundary_digest = path2_native_boundary_v1_digest(
            &context_digest,
            &account_digest,
            &spend_digest,
            &lifecycle_digest,
            &state_digest,
        );

        let mut mutated_account = account;
        mutated_account.account_id[0] ^= 1;
        let mutated_account_digest = path2_native_account_projection_v1_digest(&mutated_account);
        assert_ne!(mutated_account_digest, account_digest);
        let mut mutated_transcript = transcript;
        mutated_transcript.p_account_digest = mutated_account_digest;
        let mutated_transcript_digest =
            path2_native_transcript_projection_v1_digest(&mutated_transcript).unwrap();
        assert_ne!(mutated_transcript_digest, transcript_digest);
        assert_ne!(
            path2_native_boundary_v1_digest(
                &context_digest,
                &mutated_account_digest,
                &spend_digest,
                &lifecycle_digest,
                &state_digest,
            ),
            boundary_digest
        );

        let mut bad_context = context;
        bad_context.aggregation_mode = 9;
        assert!(
            path2_native_context_projection_v1_digest(&bad_context)
                .unwrap_err()
                .contains("reserved")
        );
        let mut bad_spend = spend;
        bad_spend.spend_verifier_family_id = 9;
        assert!(
            path2_native_spend_projection_v1_digest(&bad_spend)
                .unwrap_err()
                .contains("verifier family mismatch")
        );
    }

    #[test]
    fn path2_native_projection_preimages_exclude_private_sentinels() {
        let (context, account, spend, lifecycle, state) = native_projection_fixtures();
        let context_digest = path2_native_context_projection_v1_digest(&context).unwrap();
        let account_digest = path2_native_account_projection_v1_digest(&account);
        let spend_digest = path2_native_spend_projection_v1_digest(&spend).unwrap();
        let lifecycle_digest = path2_native_lifecycle_projection_v1_digest(&lifecycle);
        let state_digest = path2_native_state_projection_v1_digest(&state);
        let checked_core_frame_domain_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(PATH2_NATIVE_CHECKED_CORE_FRAME_DOMAIN.as_bytes()).into();
        let transcript = Path2NativeTranscriptProjectionV1 {
            native_boundary_digest: repeated_digest(0x61),
            p_context_digest: context_digest,
            p_account_digest: account_digest,
            p_spend_digest: spend_digest,
            p_lifecycle_digest: lifecycle_digest,
            p_state_digest: state_digest,
            checked_core_frame_domain_digest,
            aggregation_mode: PATH2_NATIVE_AGGREGATION_MODE_DIRECT,
        };
        let mut all_bytes = Vec::new();
        all_bytes.extend(path2_native_context_projection_v1_bytes(&context).unwrap());
        all_bytes.extend(path2_native_account_projection_v1_bytes(&account));
        all_bytes.extend(path2_native_spend_projection_v1_bytes(&spend).unwrap());
        all_bytes.extend(path2_native_lifecycle_projection_v1_bytes(&lifecycle));
        all_bytes.extend(path2_native_state_projection_v1_bytes(&state));
        all_bytes.extend(path2_native_transcript_projection_v1_bytes(&transcript).unwrap());

        for (label, sentinel) in [
            ("raw_pad_seed", repeated_digest(0xa1)),
            ("opening_tuple", repeated_digest(0xa2)),
            ("unmasked_projection", repeated_digest(0xa3)),
            ("gauge", repeated_digest(0xa4)),
            ("fallback_carrier", repeated_digest(0xa5)),
        ] {
            assert!(
                !contains_window(&all_bytes, &sentinel),
                "native projection preimage includes private sentinel {label}"
            );
        }
    }

    #[test]
    fn path2_native_projection_preimage_da_frames_roundtrip() {
        fn parse_frames(bytes: &[u8]) -> Vec<(Vec<u8>, Vec<u8>)> {
            assert!(bytes.starts_with(PATH2_NATIVE_PROJECTION_PREIMAGE_DA_DOMAIN.as_bytes()));
            let mut offset = PATH2_NATIVE_PROJECTION_PREIMAGE_DA_DOMAIN.len();
            let mut frames = Vec::new();
            while offset < bytes.len() {
                assert!(offset + 2 <= bytes.len(), "missing frame label length");
                let label_len = u16::from_le_bytes([bytes[offset], bytes[offset + 1]]) as usize;
                offset += 2;
                assert!(offset + label_len <= bytes.len(), "truncated frame label");
                let label = bytes[offset..offset + label_len].to_vec();
                offset += label_len;
                assert!(offset + 8 <= bytes.len(), "missing frame data length");
                let data_len = u64::from_le_bytes(
                    bytes[offset..offset + 8]
                        .try_into()
                        .expect("8-byte frame length"),
                ) as usize;
                offset += 8;
                assert!(offset + data_len <= bytes.len(), "truncated frame data");
                let data = bytes[offset..offset + data_len].to_vec();
                offset += data_len;
                frames.push((label, data));
            }
            frames
        }

        let bundle = native_projection_bundle_fixture();
        let bytes = path2_native_projection_preimage_da_v1_bytes(&bundle).unwrap();
        let frames = parse_frames(&bytes);
        let expected = [
            (
                b"context_projection".as_slice(),
                path2_native_context_projection_v1_bytes(&bundle.context).unwrap(),
            ),
            (
                b"account_projection".as_slice(),
                path2_native_account_projection_v1_bytes(&bundle.account),
            ),
            (
                b"spend_projection".as_slice(),
                path2_native_spend_projection_v1_bytes(&bundle.spend).unwrap(),
            ),
            (
                b"lifecycle_projection".as_slice(),
                path2_native_lifecycle_projection_v1_bytes(&bundle.lifecycle),
            ),
            (
                b"state_projection".as_slice(),
                path2_native_state_projection_v1_bytes(&bundle.state),
            ),
            (
                b"obstruction_flags_digest".as_slice(),
                bundle.obstruction_flags_digest.to_vec(),
            ),
            (b"message_digest".as_slice(), bundle.message_digest.to_vec()),
            (
                b"current_state_digest".as_slice(),
                bundle.current_state_digest.to_vec(),
            ),
            (
                b"proof_commitment".as_slice(),
                bundle.proof_commitment.to_vec(),
            ),
        ];
        assert_eq!(frames.len(), expected.len());
        for ((label, data), (expected_label, expected_data)) in frames.iter().zip(expected) {
            assert_eq!(label, expected_label);
            assert_eq!(data, &expected_data);
        }

        let expected_digest: [u8; DIGEST_BYTES] = Sha256::digest(&bytes).into();
        assert_eq!(
            path2_native_projection_preimage_da_digest_v1(&bundle).unwrap(),
            expected_digest
        );
    }

