    #[test]
    fn path2_native_consensus_carrier_preflight_reports_do_not_export_private_material() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let da_digest = path2_native_projection_preimage_da_digest_v1(&bundle).unwrap();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();
        let carrier = path2_native_consensus_carrier_v1_from_assembly(&assembly, da_digest);
        let carrier_digest = path2_native_consensus_carrier_v1_digest(&carrier).unwrap();

        let accepted_report =
            path2_native_consensus_carrier_preflight_report_v1(&carrier, &bundle, &proof_bytes);
        assert_eq!(
            accepted_report.schema,
            PATH2_NATIVE_CONSENSUS_PREFLIGHT_REPORT_SCHEMA
        );
        assert!(accepted_report.accepted);
        assert_eq!(accepted_report.rejection_code, None);
        assert_eq!(accepted_report.carrier_digest, Some(carrier_digest));
        assert_eq!(
            accepted_report.recomputed_native_boundary_digest,
            Some(assembly.native_boundary_digest)
        );

        let mut bad_carrier = carrier;
        bad_carrier.p_state_digest[0] ^= 1;
        let bad_carrier_report =
            path2_native_consensus_carrier_preflight_report_v1(&bad_carrier, &bundle, &proof_bytes);
        assert!(!bad_carrier_report.accepted);
        assert_eq!(
            bad_carrier_report.rejection_code,
            Some("reject_carrier_bundle_mismatch")
        );

        let mut bad_context = carrier;
        bad_context.carrier_version += 1;
        let bad_context_report =
            path2_native_consensus_carrier_preflight_report_v1(&bad_context, &bundle, &proof_bytes);
        assert!(!bad_context_report.accepted);
        assert_eq!(
            bad_context_report.rejection_code,
            Some("reject_invalid_carrier_context")
        );

        let mut bad_bundle = bundle;
        bad_bundle.context.verifier_family_id += 1;
        let bad_bundle_report =
            path2_native_consensus_carrier_preflight_report_v1(&carrier, &bad_bundle, &proof_bytes);
        assert!(!bad_bundle_report.accepted);
        assert_eq!(
            bad_bundle_report.rejection_code,
            Some("reject_projection_bundle_inconsistent")
        );

        let mut bad_da_carrier = carrier;
        bad_da_carrier.projection_preimage_da_digest[0] ^= 1;
        let bad_da_report = path2_native_consensus_carrier_preflight_report_v1(
            &bad_da_carrier,
            &bundle,
            &proof_bytes,
        );
        assert!(!bad_da_report.accepted);
        assert_eq!(
            bad_da_report.rejection_code,
            Some("reject_carrier_bundle_mismatch")
        );

        for report in [
            accepted_report,
            bad_carrier_report,
            bad_context_report,
            bad_bundle_report,
            bad_da_report,
        ] {
            let rendered = format!("{}\n{report:?}", serde_json::to_string(&report).unwrap());
            assert_no_active_native_private_material(&rendered);
            assert!(!rendered.contains("message_digest"));
            assert!(!rendered.contains("proof_commitment"));
            assert!(!rendered.contains("checked_core_proof"));
            assert!(!rendered.contains("proof_bytes"));
        }
    }

    #[test]
