    #[test]
    fn path2_prevalidated_slot_creation_frame_binding_kats_reject_mutations() {
        let (leaf, evidence, _certificate) = path2_creation_frame_binding_fixture();

        let mut bad_evidence = evidence;
        bad_evidence.slot_leaf_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 slot leaf digest mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.slot_authorization_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 slot authorization digest mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.account_identity_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 account id mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.public_key_identity[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 public-key identity mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.slot_id += 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 slot id mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.state_root_before[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 account state root mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.creation_verifier_version_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 creation verifier version mismatch"
        );

        let mut bad_evidence = evidence;
        bad_evidence.evidence_payload_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &bad_evidence)
                .unwrap_err(),
            "Path 2 prevalidation transcript digest mismatch"
        );

        let mut bad_leaf = leaf;
        bad_leaf.live_status_marker = 0;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&bad_leaf, &evidence)
                .unwrap_err(),
            "Path 2 slot leaf is not live"
        );

        let mut bad_leaf = leaf;
        bad_leaf.prevalidation_transcript_digest[0] ^= 1;
        let mut rebound_evidence = evidence;
        refresh_path2_leaf_digest_bindings(&bad_leaf, &mut rebound_evidence);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&bad_leaf, &rebound_evidence)
                .unwrap_err(),
            "Path 2 prevalidation transcript digest mismatch"
        );

        let mut batch_domain_evidence = evidence;
        batch_domain_evidence.evidence_domain = PATH2_SLOT_PREVALIDATE_BATCH_DOMAIN;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &batch_domain_evidence)
                .unwrap_err(),
            "Path 2 evidence domain mismatch"
        );
    }

    #[test]
    fn path2_prevalidation_transcript_digest_is_not_circular() {
        let (mut leaf, mut evidence, _certificate) = path2_creation_frame_binding_fixture();
        let original_transcript = leaf.prevalidation_transcript_digest;
        let original_leaf_digest = evidence.slot_leaf_digest;

        leaf.slot_id += 1;
        refresh_path2_leaf_digest_bindings(&leaf, &mut evidence);
        assert_eq!(leaf.prevalidation_transcript_digest, original_transcript);
        assert_ne!(evidence.slot_leaf_digest, original_leaf_digest);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &evidence).unwrap_err(),
            "Path 2 slot id mismatch"
        );

        evidence.slot_id = leaf.slot_id;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &evidence).unwrap_err(),
            "Path 2 prevalidation transcript digest mismatch"
        );

        evidence.account_identity_digest = leaf.account_id;
        evidence.public_key_identity = leaf.public_key_identity;
        evidence.slot_id = leaf.slot_id;
        evidence.state_root_before = leaf.account_state_root_before;
        evidence.creation_verifier_version_digest = leaf.verifier_version_digest;
        evidence.hidden_source_statement_digest = leaf.hidden_source_statement_digest;
        evidence.opening_commitment = leaf.opening_commitment;
        evidence.pad_seed_digest = leaf.pad_seed_digest;
        evidence.lifecycle_anchor = leaf.lifecycle_anchor;
        leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&leaf, &mut evidence);
        verify_path2_prevalidated_slot_creation_frame_bindings(&leaf, &evidence).unwrap();
    }

    #[test]
    fn path2_prevalidated_slot_creation_payload_kats_reject_missing_or_replayed_payloads() {
        let (leaf, evidence, certificate) = path2_creation_frame_binding_fixture();
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(&leaf, &evidence, None)
                .unwrap_err(),
            "Path 2 evidence payload unavailable"
        );

        let mut wrong_certificate = certificate;
        wrong_certificate.public_replay_payload_digest[0] ^= 1;
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(
                &leaf,
                &evidence,
                Some(&wrong_certificate)
            )
            .unwrap_err(),
            "Path 2 evidence payload digest mismatch"
        );

        let (mut other_leaf, mut other_evidence, _other_certificate) =
            path2_creation_frame_binding_fixture();
        other_leaf.account_id = test_digest("path2-other-account");
        other_evidence.account_identity_digest = other_leaf.account_id;
        other_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        other_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&other_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&other_leaf, &mut other_evidence);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(
                &other_leaf,
                &other_evidence,
                Some(&certificate)
            )
            .unwrap_err(),
            "Path 2 certificate account id mismatch"
        );

        let (mut other_leaf, mut other_evidence, _other_certificate) =
            path2_creation_frame_binding_fixture();
        other_leaf.public_key_identity = test_digest("path2-other-public-key");
        other_evidence.public_key_identity = other_leaf.public_key_identity;
        other_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        other_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&other_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&other_leaf, &mut other_evidence);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(
                &other_leaf,
                &other_evidence,
                Some(&certificate)
            )
            .unwrap_err(),
            "Path 2 certificate public-key identity mismatch"
        );

        let (mut other_leaf, mut other_evidence, _other_certificate) =
            path2_creation_frame_binding_fixture();
        other_leaf.slot_id += 1;
        other_evidence.slot_id = other_leaf.slot_id;
        other_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        other_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&other_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&other_leaf, &mut other_evidence);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(
                &other_leaf,
                &other_evidence,
                Some(&certificate)
            )
            .unwrap_err(),
            "Path 2 certificate slot id mismatch"
        );

        let (mut other_leaf, mut other_evidence, _other_certificate) =
            path2_creation_frame_binding_fixture();
        other_leaf.account_state_root_before = test_digest("path2-other-state-root");
        other_evidence.state_root_before = other_leaf.account_state_root_before;
        other_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        other_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&other_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&other_leaf, &mut other_evidence);
        assert_eq!(
            verify_path2_prevalidated_slot_creation_payload_bindings(
                &other_leaf,
                &other_evidence,
                Some(&certificate)
            )
            .unwrap_err(),
            "Path 2 certificate account state root mismatch"
        );
    }

    #[test]
    fn path2_prevalidated_slot_admission_namespace_rejects_duplicates() {
        let (leaf, _evidence, _certificate) = path2_creation_frame_binding_fixture();
        verify_path2_prevalidated_slot_admission_namespace(&[leaf]).unwrap();

        assert_eq!(
            verify_path2_prevalidated_slot_admission_namespace(&[leaf, leaf]).unwrap_err(),
            "Path 2 duplicate account slot admission"
        );

        let mut duplicate_pad_leaf = leaf;
        duplicate_pad_leaf.slot_id += 1;
        assert_eq!(
            verify_path2_prevalidated_slot_admission_namespace(&[leaf, duplicate_pad_leaf])
                .unwrap_err(),
            "Path 2 duplicate pad-seed digest admission"
        );
    }

    #[test]
    fn path2_public_certificate_debug_excludes_private_opening_material() {
        let (leaf, evidence, certificate) = path2_creation_frame_binding_fixture();
        verify_path2_prevalidated_slot_creation_payload_bindings(
            &leaf,
            &evidence,
            Some(&certificate),
        )
        .unwrap();
        let rendered = format!("{leaf:?} {evidence:?} {certificate:?}");
        assert!(rendered.contains("pad_seed_digest"));
        assert!(rendered.contains("public_replay_payload_digest"));
        assert_no_selected_projection_material(&rendered);
    }

    #[test]
    fn path2_public_admission_view_serializes_only_public_material() {
        let (leaf, evidence, certificate) = path2_creation_frame_binding_fixture();
        let view = path2_public_admission_view_v1(&leaf, &evidence, &certificate).unwrap();
        assert_eq!(view.schema, PATH2_PUBLIC_ADMISSION_VIEW_SCHEMA);
        assert_eq!(
            view.slot_leaf_digest,
            path2_prevalidated_slot_leaf_digest(&leaf).unwrap()
        );
        assert_eq!(
            view.slot_authorization_digest,
            path2_slot_authorization_digest(&leaf).unwrap()
        );
        let serialized =
            path2_public_admission_view_v1_json(&leaf, &evidence, &certificate).unwrap();
        assert!(serialized.contains(PATH2_PUBLIC_ADMISSION_VIEW_SCHEMA));
        assert!(serialized.contains("pad_seed_digest"));
        assert!(serialized.contains("public_replay_payload_digest"));
        assert!(serialized.contains("reviewed_active_lane_statement_digest"));
        assert_no_selected_projection_material(&serialized);

        let mut bad_evidence = evidence;
        bad_evidence.evidence_payload_digest[0] ^= 1;
        assert_eq!(
            path2_public_admission_view_v1_json(&leaf, &bad_evidence, &certificate).unwrap_err(),
            "Path 2 prevalidation transcript digest mismatch"
        );
    }

    #[test]
    fn path2_direct_creation_proof_payload_is_fail_closed_until_instantiated() {
        let (leaf, evidence, certificate) = path2_creation_frame_binding_fixture();
        let binding = path2_creation_proof_binding_v1(
            &leaf,
            test_digest("path2-packed-witness-commitment"),
            test_digest("path2-randomizer-commitment"),
            test_digest("path2-pad-source-commitment"),
            test_digest("path2-projection-relation-commitment"),
            test_digest("path2-gauge-commitment"),
            [0_u8; DIGEST_BYTES],
        );
        let payload = Path2DirectCreationProofPayloadV1 {
            schema: PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA,
            payload_version: 1,
            proof_kind: PATH2_DIRECT_CREATION_PROOF_KIND_UNINSTANTIATED,
            proof_system_id: test_digest("path2-uninstantiated-proof-system"),
            proof_binding_digest: binding.digest,
            hidden_source_statement_digest: leaf.hidden_source_statement_digest,
            relation_transcript_digest: certificate.relation_transcript_digest,
            payload_digest: certificate.public_replay_payload_digest,
            payload_byte_len: 0,
        };
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
            )
            .unwrap_err(),
            "Path 2 direct creation proof payload verifier is not implemented"
        );

        let mut wrong_digest = payload;
        wrong_digest.payload_digest[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &wrong_digest,
            )
            .unwrap_err(),
            "Path 2 direct creation proof payload digest mismatch"
        );

        let mut wrong_binding_payload = payload;
        wrong_binding_payload.proof_binding_digest[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &wrong_binding_payload,
            )
            .unwrap_err(),
            "Path 2 direct creation proof binding digest mismatch"
        );

        let mut rebound_binding = binding;
        rebound_binding.slot_id += 1;
        rebound_binding.digest = path2_creation_proof_binding_v1_digest(&rebound_binding);
        let mut rebound_payload = payload;
        rebound_payload.proof_binding_digest = rebound_binding.digest;
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &rebound_binding,
                &rebound_payload,
            )
            .unwrap_err(),
            "Path 2 creation proof binding leaf context mismatch"
        );

        let mut unsupported = payload;
        unsupported.proof_kind = 1;
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &unsupported,
            )
            .unwrap_err(),
            "Path 2 direct creation proof payload kind is unsupported"
        );
    }

    #[test]
    fn path2_transparent_descent_payload_boundary_binds_public_view_before_fail_closed() {
        let (mut leaf, mut evidence, mut certificate) = path2_creation_frame_binding_fixture();
        let binding = path2_creation_proof_binding_v1(
            &leaf,
            test_digest("path2-transparent-packed-witness-commitment"),
            test_digest("path2-transparent-randomizer-commitment"),
            test_digest("path2-transparent-pad-source-commitment"),
            test_digest("path2-transparent-projection-relation-commitment"),
            test_digest("path2-transparent-gauge-commitment"),
            test_digest("path2-transparent-aggregation-context"),
        );
        let leaf_context_digest =
            path2_prevalidated_slot_leaf_context_digest(&leaf, &evidence, &certificate).unwrap();
        let mut old_leaf_context_frame = Vec::new();
        append_frame(
            &mut old_leaf_context_frame,
            b"domain",
            PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA.as_bytes(),
        );
        append_frame(&mut old_leaf_context_frame, b"account_id", &leaf.account_id);
        append_frame(
            &mut old_leaf_context_frame,
            b"public_key_identity",
            &leaf.public_key_identity,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"slot_id",
            &leaf.slot_id.to_le_bytes(),
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"verifier_version_digest",
            &leaf.verifier_version_digest,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"account_state_root_before",
            &leaf.account_state_root_before,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"lifecycle_anchor",
            &leaf.lifecycle_anchor,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"live_status_marker",
            &[leaf.live_status_marker],
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"hidden_source_statement_digest",
            &leaf.hidden_source_statement_digest,
        );
        append_frame(
            &mut old_leaf_context_frame,
            b"relation_transcript_digest",
            &certificate.relation_transcript_digest,
        );
        let old_leaf_context_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(old_leaf_context_frame).into();
        assert_ne!(leaf_context_digest, old_leaf_context_digest);
        let matrix_domain_transcript_digest = path2_descent_sis_matrix_transcript_digest(
            PATH2_DESCENT_SIS_ROLE_TRANSCRIPT_COMMITMENT,
            64,
        )
        .unwrap();
        let masked_projection = [3_u16, 5, 7, 11, 13, 17];
        let public_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            binding.digest,
            matrix_domain_transcript_digest,
            masked_projection,
            binding.aggregation_context_digest,
            test_digest("path2-transparent-trace-root"),
            test_digest("path2-transparent-constraint-root"),
            3,
        )
        .unwrap();
        let public_view_digest =
            path2_transparent_descent_public_view_digest(&public_view).unwrap();
        assert_ne!(public_view_digest, [0_u8; DIGEST_BYTES]);
        let commitment_api = path2_transparent_commitment_api_v1(&public_view, &binding).unwrap();
        assert_eq!(
            commitment_api.schema,
            PATH2_TRANSPARENT_COMMITMENT_API_SCHEMA
        );
        assert_eq!(commitment_api.creation_proof_binding_digest, binding.digest);
        assert_eq!(
            commitment_api.native_role_root_commitment,
            binding.native_role_root_commitment
        );
        assert_eq!(
            commitment_api.role_handles[0].role_id,
            PATH2_TWO_VIEW_ROLE_PAD_SOURCE
        );
        assert_eq!(
            commitment_api.role_handles[0].role_handle,
            binding.pad_source_commitment
        );
        assert_eq!(
            commitment_api.role_handles[1].role_handle,
            binding.projection_relation_commitment
        );
        assert_eq!(
            commitment_api.role_handles[2].role_handle,
            binding.opening_tuple_commitment
        );
        assert_eq!(
            commitment_api.role_handles[3].role_handle,
            binding.packed_witness_commitment
        );
        assert_ne!(
            path2_transparent_commitment_api_v1_digest(&commitment_api, &public_view, &binding)
                .unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        let mut unauthenticated_role = commitment_api;
        unauthenticated_role.role_handles[0].authenticated_under_parent_root = false;
        assert_eq!(
            verify_path2_transparent_commitment_api(&unauthenticated_role, &public_view, &binding,)
                .unwrap_err(),
            "Path 2 transparent commitment API role handle is not parent-authenticated"
        );
        let mut duplicate_role = commitment_api;
        duplicate_role.role_handles[1].role_id = duplicate_role.role_handles[0].role_id;
        assert_eq!(
            verify_path2_transparent_commitment_api(&duplicate_role, &public_view, &binding)
                .unwrap_err(),
            "Path 2 transparent commitment API duplicate role handle"
        );
        let mut rebound_role_root_binding = binding;
        rebound_role_root_binding.native_role_root_commitment[0] ^= 1;
        rebound_role_root_binding.digest =
            path2_creation_proof_binding_v1_digest(&rebound_role_root_binding);
        let rebound_role_root_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            rebound_role_root_binding.digest,
            matrix_domain_transcript_digest,
            masked_projection,
            rebound_role_root_binding.aggregation_context_digest,
            test_digest("path2-transparent-trace-root"),
            test_digest("path2-transparent-constraint-root"),
            3,
        )
        .unwrap();
        assert_eq!(
            path2_transparent_commitment_api_v1(
                &rebound_role_root_view,
                &rebound_role_root_binding,
            )
            .unwrap_err(),
            "Path 2 transparent commitment API native role root mismatch"
        );
        let rebound_public_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            binding.digest,
            matrix_domain_transcript_digest,
            [19_u16, 23, 29, 31, 37, 41],
            binding.aggregation_context_digest,
            test_digest("path2-transparent-trace-root"),
            test_digest("path2-transparent-constraint-root"),
            3,
        )
        .unwrap();
        assert_ne!(
            public_view_digest,
            path2_transparent_descent_public_view_digest(&rebound_public_view).unwrap()
        );
        let query_opening_manifest =
            path2_transparent_query_opening_manifest_fixture_for_public_view(&public_view);
        let query_openings_digest =
            path2_transparent_query_opening_manifest_digest(&query_opening_manifest).unwrap();
        let merkle_paths_digest = test_digest("path2-transparent-merkle-paths");
        let consistency_messages_digest = test_digest("path2-transparent-consistency");
        let proof_bytes = path2_transparent_proof_bytes_envelope_v1_bytes(
            &public_view,
            &query_opening_manifest,
            &merkle_paths_digest,
            &consistency_messages_digest,
            b"path2-transparent-proof-body-placeholder",
        )
        .unwrap();
        let proof_bytes_digest = path2_transparent_proof_bytes_digest(&proof_bytes).unwrap();
        let bare_proof_bytes_digest: [u8; DIGEST_BYTES] = Sha256::digest(&proof_bytes).into();
        assert_ne!(proof_bytes_digest, bare_proof_bytes_digest);
        let payload_byte_len = proof_bytes.len() as u64;
        let payload_digest = path2_transparent_descent_proof_payload_digest(
            &public_view,
            payload_byte_len,
            &proof_bytes_digest,
            &query_openings_digest,
            &merkle_paths_digest,
            &consistency_messages_digest,
        )
        .unwrap();
        assert_eq!(
            path2_transparent_descent_proof_payload_digest(
                &public_view,
                0,
                &proof_bytes_digest,
                &query_openings_digest,
                &merkle_paths_digest,
                &consistency_messages_digest,
            )
            .unwrap_err(),
            "Path 2 transparent descent payload length is zero"
        );
        assert_eq!(
            path2_transparent_descent_proof_payload_digest(
                &public_view,
                PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as u64 + 1,
                &proof_bytes_digest,
                &query_openings_digest,
                &merkle_paths_digest,
                &consistency_messages_digest,
            )
            .unwrap_err(),
            "Path 2 transparent descent payload length exceeds active fallback threshold"
        );
        assert_eq!(
            path2_transparent_descent_proof_payload_digest(
                &public_view,
                payload_byte_len,
                &[0_u8; DIGEST_BYTES],
                &query_openings_digest,
                &merkle_paths_digest,
                &consistency_messages_digest,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof bytes digest is zero"
        );
        assert_eq!(
            path2_transparent_descent_proof_payload_digest(
                &public_view,
                payload_byte_len,
                &proof_bytes_digest,
                &query_openings_digest,
                &[0_u8; DIGEST_BYTES],
                &consistency_messages_digest,
            )
            .unwrap_err(),
            "Path 2 transparent descent merkle paths digest is zero"
        );
        assert_eq!(
            path2_transparent_descent_proof_payload_digest(
                &public_view,
                payload_byte_len,
                &proof_bytes_digest,
                &query_openings_digest,
                &merkle_paths_digest,
                &[0_u8; DIGEST_BYTES],
            )
            .unwrap_err(),
            "Path 2 transparent descent consistency messages digest is zero"
        );
        certificate.public_replay_payload_digest = payload_digest;
        evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&leaf, &mut evidence);

        let payload = Path2DirectCreationProofPayloadV1 {
            schema: PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA,
            payload_version: 1,
            proof_kind: PATH2_DIRECT_CREATION_PROOF_KIND_TRANSPARENT_DESCENT,
            proof_system_id: path2_transparent_descent_proof_system_id(),
            proof_binding_digest: binding.digest,
            hidden_source_statement_digest: leaf.hidden_source_statement_digest,
            relation_transcript_digest: certificate.relation_transcript_digest,
            payload_digest,
            payload_byte_len,
        };
        let transparent_payload = Path2TransparentDescentProofPayloadV1 {
            public_view,
            payload_digest,
            payload_byte_len,
            proof_bytes_digest,
            query_openings_digest,
            merkle_paths_digest,
            consistency_messages_digest,
        };

        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof verifier is not implemented"
        );
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &query_opening_manifest,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof verifier is not implemented"
        );
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_proof_bytes(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &query_opening_manifest,
                &proof_bytes,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof verifier is not implemented"
        );
        let rebound_payload_byte_len = payload_byte_len + 1;
        let rebound_payload_digest = path2_transparent_descent_proof_payload_digest(
            &public_view,
            rebound_payload_byte_len,
            &proof_bytes_digest,
            &query_openings_digest,
            &merkle_paths_digest,
            &consistency_messages_digest,
        )
        .unwrap();
        let mut length_rebound_certificate = certificate;
        length_rebound_certificate.public_replay_payload_digest = rebound_payload_digest;
        let mut length_rebound_evidence = evidence;
        length_rebound_evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&length_rebound_certificate);
        let mut length_rebound_leaf = leaf;
        length_rebound_leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&length_rebound_evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&length_rebound_leaf, &mut length_rebound_evidence);
        let mut length_rebound_payload = payload;
        length_rebound_payload.payload_digest = rebound_payload_digest;
        length_rebound_payload.payload_byte_len = rebound_payload_byte_len;
        let mut length_rebound_transparent_payload = transparent_payload;
        length_rebound_transparent_payload.payload_digest = rebound_payload_digest;
        length_rebound_transparent_payload.payload_byte_len = rebound_payload_byte_len;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_proof_bytes(
                &length_rebound_leaf,
                &length_rebound_evidence,
                &length_rebound_certificate,
                &binding,
                &length_rebound_payload,
                &length_rebound_transparent_payload,
                &query_opening_manifest,
                &proof_bytes,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof bytes length mismatch"
        );
        let decoded_envelope =
            decode_path2_transparent_proof_bytes_envelope_v1(&proof_bytes).unwrap();
        assert_eq!(
            decoded_envelope.schema,
            PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA
        );
        assert_eq!(
            decoded_envelope.version,
            PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_VERSION
        );
        assert_eq!(
            decoded_envelope.proof_system_id,
            public_view.proof_system_id
        );
        assert_eq!(decoded_envelope.relation_id, public_view.relation_id);
        assert_eq!(
            decoded_envelope.transparent_transcript_digest,
            public_view.transparent_transcript_digest
        );
        assert_eq!(decoded_envelope.merkle_paths_digest, merkle_paths_digest);
        assert_eq!(
            decoded_envelope.consistency_messages_digest,
            consistency_messages_digest
        );
        assert_eq!(
            decoded_envelope.proof_body_digest,
            path2_transparent_proof_body_digest(b"path2-transparent-proof-body-placeholder")
                .unwrap()
        );
        let bare_proof_body_digest: [u8; DIGEST_BYTES] =
            Sha256::digest(b"path2-transparent-proof-body-placeholder").into();
        assert_ne!(decoded_envelope.proof_body_digest, bare_proof_body_digest);
        assert_eq!(
            verify_path2_transparent_proof_bytes_envelope_v1(
                &public_view,
                &query_opening_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                &proof_bytes,
            )
            .unwrap(),
            decoded_envelope
        );
        assert_eq!(
            path2_transparent_proof_bytes_envelope_v1_bytes(
                &public_view,
                &query_opening_manifest,
                &[0_u8; DIGEST_BYTES],
                &consistency_messages_digest,
                b"path2-transparent-proof-body-placeholder",
            )
            .unwrap_err(),
            "Path 2 transparent proof merkle paths digest is zero"
        );
        assert_eq!(
            path2_transparent_proof_bytes_envelope_v1_bytes(
                &public_view,
                &query_opening_manifest,
                &merkle_paths_digest,
                &[0_u8; DIGEST_BYTES],
                b"path2-transparent-proof-body-placeholder",
            )
            .unwrap_err(),
            "Path 2 transparent proof consistency messages digest is zero"
        );
        let mut wrong_merkle_digest = merkle_paths_digest;
        wrong_merkle_digest[0] ^= 1;
        assert_eq!(
            verify_path2_transparent_proof_bytes_envelope_v1(
                &public_view,
                &query_opening_manifest,
                &wrong_merkle_digest,
                &consistency_messages_digest,
                &proof_bytes,
            )
            .unwrap_err(),
            "Path 2 transparent proof bytes envelope context mismatch"
        );
        let mut out_of_trace_manifest = query_opening_manifest.clone();
        for record in &mut out_of_trace_manifest.records {
            if record.query_index == 0 {
                record.row_index = public_view.trace_rows;
            }
        }
        assert_eq!(
            path2_transparent_proof_bytes_envelope_v1_bytes(
                &public_view,
                &out_of_trace_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                b"path2-transparent-proof-body-placeholder",
            )
            .unwrap_err(),
            "Path 2 transparent query opening row is outside trace"
        );
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &out_of_trace_manifest,
            )
            .unwrap_err(),
            "Path 2 transparent query opening row is outside trace"
        );
        assert_eq!(
            verify_path2_transparent_proof_bytes_envelope_v1(
                &public_view,
                &out_of_trace_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                &proof_bytes,
            )
            .unwrap_err(),
            "Path 2 transparent query opening row is outside trace"
        );
        assert_eq!(
            verify_path2_direct_creation_proof_payload_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof verifier is not implemented"
        );

        let mut bad_view_payload = transparent_payload;
        bad_view_payload.public_view.leaf_context_digest[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &bad_view_payload,
            )
            .unwrap_err(),
            "Path 2 transparent descent leaf context mismatch"
        );

        let mut bad_relation_payload = transparent_payload;
        bad_relation_payload.public_view.relation_id[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &bad_relation_payload,
            )
            .unwrap_err(),
            "Path 2 transparent relation id mismatch"
        );

        let mut bad_openings_payload = transparent_payload;
        bad_openings_payload.query_openings_digest[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &bad_openings_payload,
            )
            .unwrap_err(),
            "Path 2 transparent descent payload digest mismatch"
        );

        let mut wrong_proof_bytes = proof_bytes.clone();
        let last = wrong_proof_bytes.len() - 1;
        wrong_proof_bytes[last] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_proof_bytes(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &query_opening_manifest,
                &wrong_proof_bytes,
            )
            .unwrap_err(),
            "Path 2 transparent descent proof bytes digest mismatch"
        );
        assert_eq!(
            decode_path2_transparent_proof_bytes_envelope_v1(&wrong_proof_bytes).unwrap_err(),
            "Path 2 transparent proof body digest mismatch"
        );
        let mut truncated_proof_bytes = proof_bytes.clone();
        truncated_proof_bytes.pop();
        assert_eq!(
            decode_path2_transparent_proof_bytes_envelope_v1(&truncated_proof_bytes).unwrap_err(),
            "Path 2 transparent proof body length mismatch"
        );
        let mut rebound_envelope = proof_bytes.clone();
        let relation_id_offset =
            PATH2_TRANSPARENT_PROOF_BYTES_ENVELOPE_SCHEMA.len() + 2 + DIGEST_BYTES;
        rebound_envelope[relation_id_offset] ^= 1;
        assert_eq!(
            verify_path2_transparent_proof_bytes_envelope_v1(
                &public_view,
                &query_opening_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                &rebound_envelope,
            )
            .unwrap_err(),
            "Path 2 transparent proof bytes envelope context mismatch"
        );
        assert_eq!(
            path2_transparent_proof_bytes_envelope_v1_bytes(
                &public_view,
                &query_opening_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                &[],
            )
            .unwrap_err(),
            "Path 2 transparent proof body is empty"
        );
        let oversized_body_len = PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as usize
            - path2_transparent_proof_bytes_envelope_fixed_len()
            + 1;
        assert_eq!(
            path2_transparent_proof_bytes_envelope_v1_bytes(
                &public_view,
                &query_opening_manifest,
                &merkle_paths_digest,
                &consistency_messages_digest,
                &vec![0x42; oversized_body_len],
            )
            .unwrap_err(),
            "Path 2 transparent proof bytes exceed active fallback threshold"
        );
        let mut oversized_envelope = proof_bytes.clone();
        oversized_envelope.resize(
            PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES as usize + 1,
            0,
        );
        assert_eq!(
            decode_path2_transparent_proof_bytes_envelope_v1(&oversized_envelope).unwrap_err(),
            "Path 2 transparent proof bytes exceed active fallback threshold"
        );

        let mismatched_public_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            512,
            20,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            binding.digest,
            matrix_domain_transcript_digest,
            masked_projection,
            binding.aggregation_context_digest,
            test_digest("path2-transparent-other-trace-root"),
            test_digest("path2-transparent-other-constraint-root"),
            3,
        )
        .unwrap();
        let mismatched_manifest = path2_transparent_query_opening_manifest_fixture_for_public_view(
            &mismatched_public_view,
        );
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &mismatched_manifest,
            )
            .unwrap_err(),
            "Path 2 transparent descent query opening manifest context mismatch"
        );

        let mut rebound_manifest = query_opening_manifest.clone();
        rebound_manifest.records[0].component_digest[0] ^= 1;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &rebound_manifest,
            )
            .unwrap_err(),
            "Path 2 transparent descent query opening manifest digest mismatch"
        );

        let mut raw_hidden_manifest = query_opening_manifest.clone();
        raw_hidden_manifest.records[1].visibility_class =
            PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN;
        assert_eq!(
            verify_path2_direct_creation_transparent_descent_payload_boundary_with_query_manifest(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &transparent_payload,
                &raw_hidden_manifest,
            )
            .unwrap_err(),
            "Path 2 transparent query opening exposes hidden visibility class"
        );

        let serialized = serde_json::to_string(&transparent_payload).unwrap();
        assert!(serialized.contains("query_openings_digest"));
        assert_no_path2_transparent_private_material(&serialized);
    }

    #[test]
    fn path2_creation_proof_binding_digest_rejects_rebinding() {
        let (leaf, _evidence, _certificate) = path2_creation_frame_binding_fixture();
        let binding = path2_creation_proof_binding_v1(
            &leaf,
            test_digest("path2-packed-witness-commitment"),
            test_digest("path2-randomizer-commitment"),
            test_digest("path2-pad-source-commitment"),
            test_digest("path2-projection-relation-commitment"),
            test_digest("path2-gauge-commitment"),
            test_digest("path2-aggregation-context"),
        );
        assert_eq!(
            binding.digest,
            path2_creation_proof_binding_v1_digest(&binding)
        );
        assert!(
            path2_creation_proof_binding_v1_frame(&binding)
                .windows(PATH2_CREATION_PROOF_BINDING_SCHEMA.len())
                .any(|window| window == PATH2_CREATION_PROOF_BINDING_SCHEMA.as_bytes())
        );

        let mut mutations: Vec<(&str, Path2CreationProofBindingV1)> = Vec::new();

        let mut account = binding;
        account.account_id[0] ^= 1;
        mutations.push(("account_id", account));

        let mut public_key = binding;
        public_key.public_key_identity[0] ^= 1;
        mutations.push(("public_key_identity", public_key));

        let mut slot = binding;
        slot.slot_id += 1;
        mutations.push(("slot_id", slot));

        let mut verifier = binding;
        verifier.verifier_version_digest[0] ^= 1;
        mutations.push(("verifier_version_digest", verifier));

        let mut state_root = binding;
        state_root.account_state_root_before[0] ^= 1;
        mutations.push(("account_state_root_before", state_root));

        let mut lifecycle = binding;
        lifecycle.lifecycle_anchor[0] ^= 1;
        mutations.push(("lifecycle_anchor", lifecycle));

        let mut witness = binding;
        witness.packed_witness_commitment[0] ^= 1;
        mutations.push(("packed_witness_commitment", witness));

        let mut randomizer = binding;
        randomizer.randomizer_commitment[0] ^= 1;
        mutations.push(("randomizer_commitment", randomizer));

        let mut pad_source = binding;
        pad_source.pad_source_commitment[0] ^= 1;
        mutations.push(("pad_source_commitment", pad_source));

        let mut opening = binding;
        opening.opening_tuple_commitment[0] ^= 1;
        mutations.push(("opening_tuple_commitment", opening));

        let mut projection = binding;
        projection.projection_relation_commitment[0] ^= 1;
        mutations.push(("projection_relation_commitment", projection));

        let mut gauge = binding;
        gauge.gauge_commitment[0] ^= 1;
        mutations.push(("gauge_commitment", gauge));

        let mut role_root = binding;
        role_root.native_role_root_commitment[0] ^= 1;
        mutations.push(("native_role_root_commitment", role_root));

        let mut statement = binding;
        statement.creation_statement_digest[0] ^= 1;
        mutations.push(("creation_statement_digest", statement));

        let mut aggregation = binding;
        aggregation.aggregation_context_digest[0] ^= 1;
        mutations.push(("aggregation_context_digest", aggregation));

        for (label, mutated) in mutations {
            assert_ne!(
                binding.digest,
                path2_creation_proof_binding_v1_digest(&mutated),
                "Path 2 creation proof binding digest failed to bind {label}"
            );
        }
    }

    #[test]
    fn path2_prevalidated_slot_leaf_v2_binds_creation_proof_binding_digest() {
        let (leaf_v1, _evidence, _certificate) = path2_creation_frame_binding_fixture();
        let binding = path2_creation_proof_binding_v1(
            &leaf_v1,
            test_digest("path2-packed-witness-commitment"),
            test_digest("path2-randomizer-commitment"),
            test_digest("path2-pad-source-commitment"),
            test_digest("path2-projection-relation-commitment"),
            test_digest("path2-gauge-commitment"),
            test_digest("path2-aggregation-context"),
        );
        let leaf_v2 = path2_prevalidated_slot_leaf_v2_from_v1(&leaf_v1, binding.digest);
        let leaf_v2_bytes = path2_prevalidated_slot_leaf_v2_bytes(&leaf_v2).unwrap();

        assert_eq!(leaf_v2_bytes.len(), PATH2_PREVALIDATED_SLOT_LEAF_V2_BYTES);
        assert_eq!(
            PATH2_PREVALIDATED_SLOT_LEAF_V2_BYTES - PATH2_PREVALIDATED_SLOT_LEAF_V1_BYTES,
            DIGEST_BYTES
        );
        assert_eq!(
            &leaf_v2_bytes[..PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.len()],
            PATH2_PREVALIDATED_SLOT_LEAF_V2_DOMAIN.as_bytes()
        );
        assert_eq!(
            leaf_v2.creation_proof_binding_digest, binding.digest,
            "Path 2 v2 leaf must carry the proof-friendly binding digest"
        );
        assert_ne!(
            path2_prevalidated_slot_leaf_digest(&leaf_v1).unwrap(),
            path2_prevalidated_slot_leaf_v2_digest(&leaf_v2).unwrap()
        );
        assert_ne!(
            path2_slot_authorization_digest(&leaf_v1).unwrap(),
            path2_slot_authorization_v2_digest(&leaf_v2).unwrap()
        );
        assert_eq!(
            REVIEWED_FQ12_ACCOUNT_CARRIED_TRANSACTION_SIGNATURE_BYTES,
            258
        );

        let mut rebound_leaf = leaf_v2;
        rebound_leaf.creation_proof_binding_digest[0] ^= 1;
        assert_ne!(
            path2_prevalidated_slot_leaf_v2_digest(&leaf_v2).unwrap(),
            path2_prevalidated_slot_leaf_v2_digest(&rebound_leaf).unwrap()
        );
        assert_ne!(
            path2_slot_authorization_v2_digest(&leaf_v2).unwrap(),
            path2_slot_authorization_v2_digest(&rebound_leaf).unwrap()
        );
    }

    #[test]
    fn path2_toy_q_linear_creation_proof_accepts_and_rejects_relation_mutation() {
        let (leaf, evidence, mut certificate) = path2_creation_frame_binding_fixture();
        let pad_lanes = [11_u16, 13, 17, 19, 23, 29];
        let account_lanes = [101_u16, 103, 107, 109, 113, 127];
        let mut masked_projection = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
        for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
            masked_projection[lane] = add_mod(pad_lanes[lane], account_lanes[lane]);
        }
        let packed_witness_commitment = pack_reviewed_fq12_packed_witness_state18_from_parts(
            &[0_u16; REVIEWED_FQ12_ACCOUNT_CARRIED_PUBLIC_ROWS],
            &masked_projection,
        )
        .unwrap();
        let pad_blinding = 31_u16;
        let projection_blinding = 37_u16;
        let pad_commitment_value = path2_toy_q_linear_commitment_value(
            PATH2_TOY_Q_COMMITMENT_ROLE_PAD_SOURCE,
            &pad_lanes,
            pad_blinding,
        )
        .unwrap();
        let projection_commitment_value = path2_toy_q_linear_commitment_value(
            PATH2_TOY_Q_COMMITMENT_ROLE_PROJECTION_RELATION,
            &account_lanes,
            projection_blinding,
        )
        .unwrap();
        let binding = path2_creation_proof_binding_v1(
            &leaf,
            packed_witness_commitment,
            test_digest("path2-randomizer-commitment"),
            path2_toy_q_linear_commitment_bytes(
                PATH2_TOY_Q_COMMITMENT_ROLE_PAD_SOURCE,
                pad_commitment_value,
            )
            .unwrap(),
            path2_toy_q_linear_commitment_bytes(
                PATH2_TOY_Q_COMMITMENT_ROLE_PROJECTION_RELATION,
                projection_commitment_value,
            )
            .unwrap(),
            test_digest("path2-toy-q-linear-gauge-commitment"),
            [0_u8; DIGEST_BYTES],
        );
        certificate.public_replay_payload_digest =
            Sha256::digest(path2_creation_proof_binding_v1_frame(&binding)).into();
        let mut evidence = evidence;
        evidence.evidence_payload_digest =
            path2_direct_replayable_relation_certificate_digest(&certificate);
        let mut leaf = leaf;
        leaf.prevalidation_transcript_digest =
            path2_account_creation_evidence_transcript_digest(&evidence).unwrap();
        refresh_path2_leaf_digest_bindings(&leaf, &mut evidence);
        let payload = Path2DirectCreationProofPayloadV1 {
            schema: PATH2_DIRECT_CREATION_PROOF_PAYLOAD_SCHEMA,
            payload_version: 1,
            proof_kind: PATH2_DIRECT_CREATION_PROOF_KIND_TOY_Q_LINEAR,
            proof_system_id: test_digest("path2-toy-q-linear-proof-system"),
            proof_binding_digest: binding.digest,
            hidden_source_statement_digest: leaf.hidden_source_statement_digest,
            relation_transcript_digest: certificate.relation_transcript_digest,
            payload_digest: certificate.public_replay_payload_digest,
            payload_byte_len: 0,
        };
        let pad_nonce_lanes = [3_u16, 5, 7, 9, 11, 13];
        let mut projection_nonce_lanes = [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES];
        for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
            projection_nonce_lanes[lane] = (Q - pad_nonce_lanes[lane]) % Q;
        }
        let pad_blinding_nonce = 41_u16;
        let projection_blinding_nonce = 43_u16;
        let mut proof = Path2ToyQLinearCreationProofV1 {
            pad_commitment_nonce: path2_toy_q_linear_commitment_value(
                PATH2_TOY_Q_COMMITMENT_ROLE_PAD_SOURCE,
                &pad_nonce_lanes,
                pad_blinding_nonce,
            )
            .unwrap(),
            projection_commitment_nonce: path2_toy_q_linear_commitment_value(
                PATH2_TOY_Q_COMMITMENT_ROLE_PROJECTION_RELATION,
                &projection_nonce_lanes,
                projection_blinding_nonce,
            )
            .unwrap(),
            pad_lane_responses: [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
            projection_lane_responses: [0_u16; HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES],
            pad_blinding_response: 0,
            projection_blinding_response: 0,
        };
        let challenge =
            path2_toy_q_linear_challenge(&leaf, &binding, &payload, &proof, &masked_projection);
        for lane in 0..HIDDEN_SOURCE_FALLBACK_ACCOUNT_PROJECTION_LANES {
            proof.pad_lane_responses[lane] = add_mod(
                pad_nonce_lanes[lane],
                ((challenge as u32 * pad_lanes[lane] as u32) % Q as u32) as u16,
            );
            proof.projection_lane_responses[lane] = add_mod(
                projection_nonce_lanes[lane],
                ((challenge as u32 * account_lanes[lane] as u32) % Q as u32) as u16,
            );
        }
        proof.pad_blinding_response = add_mod(
            pad_blinding_nonce,
            ((challenge as u32 * pad_blinding as u32) % Q as u32) as u16,
        );
        proof.projection_blinding_response = add_mod(
            projection_blinding_nonce,
            ((challenge as u32 * projection_blinding as u32) % Q as u32) as u16,
        );

        verify_path2_direct_creation_toy_q_linear_proof_v1(
            &leaf,
            &evidence,
            &certificate,
            &binding,
            &payload,
            &proof,
        )
        .unwrap();

        let mut bad_proof = proof;
        bad_proof.pad_lane_responses[0] = add_mod(bad_proof.pad_lane_responses[0], 1);
        assert_eq!(
            verify_path2_direct_creation_toy_q_linear_proof_v1(
                &leaf,
                &evidence,
                &certificate,
                &binding,
                &payload,
                &bad_proof,
            )
            .unwrap_err(),
            "Path 2 toy q-linear masked projection relation mismatch"
        );

        let mut bad_binding = binding;
        bad_binding.projection_relation_commitment[7] = 1;
        bad_binding.digest = path2_creation_proof_binding_v1_digest(&bad_binding);
        let mut bad_payload = payload;
        bad_payload.proof_binding_digest = bad_binding.digest;
        assert_eq!(
            verify_path2_direct_creation_toy_q_linear_proof_v1(
                &leaf,
                &evidence,
                &certificate,
                &bad_binding,
                &bad_payload,
                &proof,
            )
            .unwrap_err(),
            "Path 2 toy q-linear commitment has nonzero padding"
        );
    }

    #[test]
    fn path2_direct_query_budget_keeps_batch_inactive() {
        let budget = path2_direct_query_budget_v1();
        assert_eq!(budget.schema, PATH2_DIRECT_QUERY_BUDGET_SCHEMA);
        assert_eq!(budget.mode, "direct_single_slot");
        assert_eq!(budget.target_security_bits, 128);
        assert_eq!(budget.deployment_quantum_hash_query_bound_log2, 16);
        assert_eq!(budget.deployment_classical_hash_query_bound_log2, 33);
        assert_eq!(budget.qrom_quadratic_loss_bits_at_deployment_bound, 32);
        assert_eq!(budget.transcript_term_bits_after_qrom_loss, 182);
        assert_eq!(budget.minimum_deployment_margin_bits, 53);
        assert!(budget.active_query_symbols.contains(&"q_leaf"));
        assert!(budget.active_query_symbols.contains(&"q_auth"));
        assert!(budget.active_query_symbols.contains(&"q_chal"));
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_trace_commit")
        );
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_query_row")
        );
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_merkle_open")
        );
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_consistency")
        );
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_extractor")
        );
        assert!(
            budget
                .active_query_symbols
                .contains(&"q_transparent_simulator")
        );
        assert_eq!(budget.inactive_query_symbols, ["q_batch"]);
        assert!(
            budget
                .direct_advantage_terms
                .iter()
                .all(|term| !term.contains("optional_aggregation"))
        );
        assert!(
            budget
                .optional_aggregation_terms
                .iter()
                .all(|term| term.contains("q_batch"))
        );
        let serialized = serde_json::to_string(&budget).unwrap();
        assert!(serialized.contains(PATH2_DIRECT_QUERY_BUDGET_SCHEMA));
        assert!(serialized.contains("q_transparent_trace_commit"));
        assert!(serialized.contains("q_transparent_query_row"));
        assert!(serialized.contains("q_transparent_merkle_open"));
        assert!(serialized.contains("\"inactive_query_symbols\":[\"q_batch\"]"));
    }

    #[test]
    fn path2_native_hash_qrom_review_tracks_public_transcript_assumptions() {
        let review = path2_native_hash_qrom_review_v1();
        assert_eq!(review.schema, PATH2_NATIVE_HASH_QROM_REVIEW_SCHEMA);
        assert_eq!(review.digest_bits, 256);
        assert_eq!(review.target_security_bits, 128);
        assert_eq!(review.deployment_quantum_hash_query_bound_log2, 16);
        assert_eq!(review.deployment_classical_hash_query_bound_log2, 33);
        assert_eq!(review.qrom_quadratic_loss_bits_at_deployment_bound, 32);
        assert_eq!(review.transcript_term_bits_after_qrom_loss, 182);
        assert!(
            review.transcript_term_bits_after_qrom_loss
                >= review.target_security_bits + review.minimum_deployment_margin_bits
        );
        assert_eq!(
            review.production_registry_entry_count as usize,
            production_registered_domain_schema_constants().len()
        );
        assert_eq!(
            review.consensus_carrier_bytes as usize,
            PATH2_NATIVE_CONSENSUS_CARRIER_BYTES
        );
        assert_eq!(
            review.consensus_carrier_body_bytes as usize,
            PATH2_NATIVE_CONSENSUS_CARRIER_BODY_BYTES
        );
        assert!(
            review
                .active_native_query_symbols
                .contains(&"q_native_public_key_identity")
        );
        assert!(
            review
                .active_native_query_symbols
                .contains(&"q_native_authorization_class")
        );
        assert!(
            review
                .active_native_query_symbols
                .contains(&"q_native_no_obstruction_flags")
        );
        assert!(
            review
                .active_native_query_symbols
                .contains(&"q_native_consensus_carrier")
        );
        assert!(
            review
                .active_native_query_symbols
                .contains(&"q_native_projection_preimage_da")
        );
        assert!(
            review
                .ordinary_hash_assumptions
                .iter()
                .all(|assumption| !assumption.contains("witness"))
        );
        assert!(
            review
                .hidden_witness_obligations_not_discharged_by_hash
                .iter()
                .any(|obligation| obligation.contains("checked-core"))
        );
        let rendered = serde_json::to_string(&review).unwrap();
        assert_no_active_native_private_material(&rendered);
        assert!(rendered.contains(PATH2_NATIVE_HASH_QROM_REVIEW_SCHEMA));
        assert!(rendered.contains("SHA-256"));
        assert!(rendered.contains("q_native_consensus_carrier"));
        assert!(rendered.contains("not_discharged_by_hash"));
    }

