    #[test]
    fn path2_native_verifier_pipeline_is_public_only_and_fail_closed_until_productized() {
        let bundle = native_projection_bundle_fixture();
        let proof_bytes = native_checked_core_proof_fixture();
        let da_digest = path2_native_projection_preimage_da_digest_v1(&bundle).unwrap();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &proof_bytes).unwrap();
        let carrier = path2_native_consensus_carrier_v1_from_assembly(&assembly, da_digest);
        let carrier_digest = path2_native_consensus_carrier_v1_digest(&carrier).unwrap();

        let verdict = verify_path2_native_deployment_pipeline_v1(&carrier, &bundle, &proof_bytes);
        assert_eq!(
            verdict.schema,
            PATH2_NATIVE_VERIFIER_PIPELINE_VERDICT_SCHEMA
        );
        assert!(verdict.public_boundary_accepted);
        assert!(!verdict.production_accepted);
        assert_eq!(
            verdict.rejection_code,
            Some("reject_active_native_pipeline_not_productized")
        );
        assert_eq!(verdict.consensus_carrier_digest, Some(carrier_digest));
        assert_eq!(
            verdict.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert!(verdict.verifier_preflight_report.accepted);
        assert!(!verdict.deployment_preflight.internal_deployment_ready);
        assert_ne!(
            path2_native_verifier_pipeline_verdict_v1_digest(&verdict).unwrap(),
            [0_u8; DIGEST_BYTES]
        );

        let mut bad_carrier = carrier;
        bad_carrier.p_spend_digest[0] ^= 1;
        let rejected =
            verify_path2_native_deployment_pipeline_v1(&bad_carrier, &bundle, &proof_bytes);
        assert!(!rejected.public_boundary_accepted);
        assert!(!rejected.production_accepted);
        assert_eq!(
            rejected.rejection_code,
            Some("reject_carrier_bundle_mismatch")
        );

        for rendered in [
            serde_json::to_string(&verdict).unwrap(),
            format!("{verdict:?}"),
            serde_json::to_string(&rejected).unwrap(),
            format!("{rejected:?}"),
        ] {
            assert_no_active_native_private_material(&rendered);
            assert!(!rendered.contains("message_digest"));
            assert!(!rendered.contains("proof_commitment"));
            assert!(!rendered.contains("checked_core_proof"));
            assert!(!rendered.contains("proof_bytes"));
        }
    }

