    #[test]
    fn path2_native_private_sha256_matches_sha2_and_zeroizes_workspace() {
        for len in [0_usize, 1, 31, 32, 55, 56, 63, 64, 65, 366, 448] {
            let mut input = vec![0_u8; len];
            for (idx, byte) in input.iter_mut().enumerate() {
                *byte = (idx as u8).wrapping_mul(17).wrapping_add(len as u8);
            }
            let expected: [u8; DIGEST_BYTES] = Sha256::digest(&input).into();
            let mut actual = [0_u8; DIGEST_BYTES];
            path2_native_private_sha256_digest_v1(&input, &mut actual);
            assert_eq!(actual, expected);
        }

        let source = include_str!("production_reference.rs");
        let start = source
            .find("fn path2_native_private_sha256_digest_v1(")
            .expect("private SHA-256 source start missing");
        let end = source[start..]
            .find("struct Path2NativeSignerDigestFrameV1")
            .expect("private SHA-256 source end missing")
            + start;
        let private_sha_source = &source[start..end];
        assert!(private_sha_source.contains("path2_native_zeroize_bytes_v1(workspace);"));
        assert!(private_sha_source.contains("ptr::write_volatile(workspace_ptr.add(idx), 0);"));
        assert!(private_sha_source.contains("ptr::read_volatile(data.as_ptr().add(idx))"));
        assert!(private_sha_source.contains("path2_native_zeroize_u32s_v1(&mut schedule);"));
        assert!(private_sha_source.contains("path2_native_zeroize_u32s_v1(&mut state);"));
        assert!(private_sha_source.contains("PATH2_NATIVE_SIGNER_PRIVATE_SHA256_WORKSPACE_BYTES"));
    }

