    #[test]
    fn path2_native_entropy_root_derives_domain_separated_secret_material() {
        let mut bundle = native_projection_bundle_fixture();
        let secret = path2_native_secret_material_from_entropy_root_v1(
            native_entropy_root_fixture("domain-separated"),
            &bundle,
        )
        .unwrap();
        assert_ne!(secret.authorization_local_seed, [0_u8; DIGEST_BYTES]);
        assert_ne!(secret.gauge_seed, [0_u8; DIGEST_BYTES]);
        assert_ne!(secret.randomizer_seed, [0_u8; DIGEST_BYTES]);
        assert_ne!(secret.wallet_recovery_seed, [0_u8; DIGEST_BYTES]);
        assert_ne!(secret.authorization_local_seed, secret.gauge_seed);
        assert_ne!(secret.authorization_local_seed, secret.randomizer_seed);
        assert_ne!(secret.gauge_seed, secret.wallet_recovery_seed);
        assert!(
            secret
                .proof_randomizer_syndrome
                .iter()
                .all(|value| *value < Q)
        );
        assert!(
            secret
                .proof_randomizer_syndrome
                .iter()
                .any(|value| *value != 0)
        );
        bundle.proof_commitment =
            pack_reviewed_fq12_account_carried_syndrome_digest(&secret.proof_randomizer_syndrome)
                .unwrap();
        path2_native_honest_constructor_from_secret_material_v1(&bundle, secret).unwrap();
    }

