    #[test]
    fn path2_domain_constants_are_disjoint_and_mode_separated() {
        let domains = path2_registered_domain_constants();
        let mut unique = BTreeSet::new();
        for domain in domains {
            assert!(unique.insert(domain), "duplicate Path 2 domain: {domain}");
            assert!(
                domain.starts_with("DESCENDER_"),
                "Path 2 domain lacks DESCENDER prefix: {domain}"
            );
        }
        for lhs in domains {
            for rhs in domains {
                if lhs == rhs {
                    continue;
                }
                assert!(
                    !lhs.starts_with(rhs) && !rhs.starts_with(lhs),
                    "Path 2 domain prefix collision: {lhs} / {rhs}"
                );
            }
        }
        assert_ne!(
            PATH2_SLOT_PREVALIDATE_SINGLE_DOMAIN,
            PATH2_SLOT_PREVALIDATE_BATCH_DOMAIN
        );
        assert_ne!(
            PATH2_SLOT_PREVALIDATE_SINGLE_DOMAIN,
            PATH2_SLOT_CONSUME_SINGLE_DOMAIN
        );
        assert_ne!(
            PATH2_SLOT_AUTHORIZATION_DOMAIN,
            PATH2_SLOT_CONSUME_SINGLE_DOMAIN
        );
        assert_ne!(
            PATH2_DESCENT_SIS_PAD_SOURCE_MATRIX_DOMAIN,
            PATH2_DESCENT_SIS_TRANSCRIPT_COMMITMENT_MATRIX_DOMAIN
        );
        assert_ne!(
            PATH2_TRANSPARENT_DESCENT_PROOF_DOMAIN,
            PATH2_TRANSPARENT_DESCENT_RELATION_DOMAIN
        );
        assert_ne!(
            PATH2_TRANSPARENT_DESCENT_PROOF_DOMAIN,
            PATH2_DESCENT_SIS_TRANSCRIPT_COMMITMENT_MATRIX_DOMAIN
        );
    }

    #[test]
    fn path2_descent_sis_matrix_domains_are_role_and_row_band_separated() {
        let roles = [
            PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
            PATH2_DESCENT_SIS_ROLE_PROJECTION_RELATION,
            PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE,
            PATH2_DESCENT_SIS_ROLE_TRANSCRIPT_COMMITMENT,
        ];
        let expected_columns = [
            PATH2_DESCENT_SIS_PAD_SOURCE_COLUMNS,
            PATH2_DESCENT_SIS_PROJECTION_RELATION_COLUMNS,
            PATH2_DESCENT_SIS_OPENING_TUPLE_COLUMNS,
            PATH2_DESCENT_SIS_TOTAL_COLUMNS,
        ];
        for (&role, &columns) in roles.iter().zip(expected_columns.iter()) {
            assert_eq!(path2_descent_sis_columns_for_role(role), Some(columns));
            for rows in PATH2_DESCENT_SIS_PRIMARY_ROW_BANDS {
                let first = path2_descent_sis_matrix_entry(role, rows, 0, 0).unwrap();
                let first_again = path2_descent_sis_matrix_entry(role, rows, 0, 0).unwrap();
                assert_eq!(first, first_again);
                assert!(first < Q);
                assert!(path2_descent_sis_matrix_entry(role, rows, rows, 0).is_err());
                assert!(path2_descent_sis_matrix_entry(role, rows, 0, columns).is_err());
                let digest = path2_descent_sis_matrix_transcript_digest(role, rows).unwrap();
                assert_ne!(digest, [0_u8; DIGEST_BYTES]);
                assert_eq!(
                    digest,
                    path2_descent_sis_matrix_transcript_digest(role, rows).unwrap()
                );
            }
        }

        let pad_48 =
            path2_descent_sis_matrix_entry(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 48, 0, 0).unwrap();
        let projection_48 =
            path2_descent_sis_matrix_entry(PATH2_DESCENT_SIS_ROLE_PROJECTION_RELATION, 48, 0, 0)
                .unwrap();
        let pad_64 =
            path2_descent_sis_matrix_entry(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 64, 0, 0).unwrap();
        assert_ne!(pad_48, projection_48);
        assert_ne!(pad_48, pad_64);
        assert_ne!(
            path2_descent_sis_matrix_transcript_digest(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 48)
                .unwrap(),
            path2_descent_sis_matrix_transcript_digest(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 64)
                .unwrap()
        );
        assert!(
            path2_descent_sis_matrix_entry(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 32, 0, 0,).is_err()
        );
        assert!(path2_descent_sis_matrix_entry(99, 48, 0, 0).is_err());
    }

    #[test]
    fn path2_descent_sis_hardness_sanity_rejects_wide_blinding_kernel_surfaces() {
        let pad_48 =
            path2_descent_sis_hardness_sanity(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE, 48).unwrap();
        assert_eq!(pad_48.columns, 36);
        assert_eq!(pad_48.rank, 36);
        assert_eq!(pad_48.kernel_dimension, 0);
        assert_eq!(
            pad_48.verdict,
            PATH2_DESCENT_SIS_SANITY_VERDICT_FULL_COLUMN_RANK_PRIVATE_ONLY
        );

        let projection_64 =
            path2_descent_sis_hardness_sanity(PATH2_DESCENT_SIS_ROLE_PROJECTION_RELATION, 64)
                .unwrap();
        assert_eq!(projection_64.columns, 36);
        assert_eq!(projection_64.rank, 36);
        assert_eq!(projection_64.kernel_dimension, 0);
        assert_eq!(
            projection_64.verdict,
            PATH2_DESCENT_SIS_SANITY_VERDICT_FULL_COLUMN_RANK_PRIVATE_ONLY
        );

        let opening_48 =
            path2_descent_sis_hardness_sanity(PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE, 48).unwrap();
        assert_eq!(opening_48.columns, 56);
        assert_eq!(opening_48.rank, 48);
        assert_eq!(opening_48.kernel_dimension, 8);
        assert!(opening_48.bound_to_gaussian_ratio.unwrap() > 3.0);
        assert_eq!(
            opening_48.verdict,
            PATH2_DESCENT_SIS_SANITY_VERDICT_BOUND_TOO_WIDE_FOR_SHORT_SIS
        );

        let opening_64 =
            path2_descent_sis_hardness_sanity(PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE, 64).unwrap();
        assert_eq!(opening_64.columns, 56);
        assert_eq!(opening_64.rank, 56);
        assert_eq!(opening_64.kernel_dimension, 0);
        assert_eq!(
            opening_64.verdict,
            PATH2_DESCENT_SIS_SANITY_VERDICT_FULL_COLUMN_RANK_PRIVATE_ONLY
        );

        for rows in PATH2_DESCENT_SIS_PRIMARY_ROW_BANDS {
            let transcript = path2_descent_sis_hardness_sanity(
                PATH2_DESCENT_SIS_ROLE_TRANSCRIPT_COMMITMENT,
                rows,
            )
            .unwrap();
            assert_eq!(transcript.columns, 128);
            assert_eq!(transcript.rank, rows);
            assert_eq!(transcript.kernel_dimension, 128 - rows);
            assert!(transcript.bound_to_gaussian_ratio.unwrap() > 100.0);
            assert_eq!(
                transcript.verdict,
                PATH2_DESCENT_SIS_SANITY_VERDICT_BOUND_TOO_WIDE_FOR_SHORT_SIS
            );
        }
    }

    #[test]
    fn path2_descent_sis_norm_range_policy_rejects_wraps_and_wrong_shapes() {
        let pad_layout = path2_descent_sis_role_layout(PATH2_DESCENT_SIS_ROLE_PAD_SOURCE).unwrap();
        assert!(pad_layout.validates_partition());
        assert_eq!(pad_layout.semantic_columns, 12);
        assert_eq!(pad_layout.blinding_columns, 24);
        assert_eq!(pad_layout.range_columns, 0);

        let mut pad_opening = vec![0_u16; pad_layout.columns];
        for slot in pad_opening.iter_mut().take(pad_layout.semantic_columns) {
            *slot = PATH2_DESCENT_SIS_SEMANTIC_DIGIT_MAX as u16;
        }
        for slot in pad_opening
            .iter_mut()
            .skip(pad_layout.semantic_columns)
            .take(pad_layout.blinding_columns)
        {
            *slot =
                path2_descent_sis_centered_to_residue(-PATH2_DESCENT_SIS_BLINDING_CENTERED_BOUND)
                    .unwrap();
        }
        verify_path2_descent_sis_opening_norm_range(
            PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
            &pad_opening,
        )
        .unwrap();

        let mut semantic_overflow = pad_opening.clone();
        semantic_overflow[0] = (PATH2_DESCENT_SIS_SEMANTIC_DIGIT_MAX + 1) as u16;
        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
                &semantic_overflow,
            )
            .unwrap_err(),
            "Path 2 descent/SIS opening coordinate exceeds selected bound"
        );

        let mut negative_semantic_digit = pad_opening.clone();
        negative_semantic_digit[0] = path2_descent_sis_centered_to_residue(-1).unwrap();
        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
                &negative_semantic_digit,
            )
            .unwrap_err(),
            "Path 2 descent/SIS semantic digit is negative"
        );

        let mut blinding_overflow = pad_opening.clone();
        blinding_overflow[pad_layout.semantic_columns] =
            path2_descent_sis_centered_to_residue(-(PATH2_DESCENT_SIS_BLINDING_CENTERED_BOUND + 1))
                .unwrap();
        assert!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
                &blinding_overflow,
            )
            .is_err()
        );

        let mut noncanonical = pad_opening.clone();
        noncanonical[0] = Q;
        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
                &noncanonical,
            )
            .unwrap_err(),
            "Path 2 descent/SIS opening residue is noncanonical"
        );

        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_PAD_SOURCE,
                &pad_opening[..pad_opening.len() - 1],
            )
            .unwrap_err(),
            "Path 2 descent/SIS opening has wrong column count"
        );
        assert!(verify_path2_descent_sis_opening_norm_range(99, &pad_opening).is_err());
    }

    #[test]
    fn path2_descent_sis_norm_range_policy_covers_range_digits() {
        let opening_layout =
            path2_descent_sis_role_layout(PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE).unwrap();
        assert!(opening_layout.validates_partition());
        assert_eq!(opening_layout.semantic_columns, 16);
        assert_eq!(opening_layout.blinding_columns, 32);
        assert_eq!(opening_layout.range_columns, 8);

        let mut opening = vec![0_u16; opening_layout.columns];
        for slot in opening.iter_mut().take(opening_layout.semantic_columns) {
            *slot = PATH2_DESCENT_SIS_SEMANTIC_DIGIT_MAX as u16;
        }
        for slot in opening
            .iter_mut()
            .skip(opening_layout.semantic_columns)
            .take(opening_layout.blinding_columns)
        {
            *slot =
                path2_descent_sis_centered_to_residue(PATH2_DESCENT_SIS_BLINDING_CENTERED_BOUND)
                    .unwrap();
        }
        for slot in opening
            .iter_mut()
            .skip(opening_layout.semantic_columns + opening_layout.blinding_columns)
        {
            *slot = PATH2_DESCENT_SIS_RANGE_DIGIT_MAX as u16;
        }
        verify_path2_descent_sis_opening_norm_range(PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE, &opening)
            .unwrap();

        let range_start = opening_layout.semantic_columns + opening_layout.blinding_columns;
        let mut negative_range_digit = opening.clone();
        negative_range_digit[range_start] = path2_descent_sis_centered_to_residue(-1).unwrap();
        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE,
                &negative_range_digit,
            )
            .unwrap_err(),
            "Path 2 descent/SIS range digit is negative"
        );

        let mut large_range_digit = opening;
        large_range_digit[range_start] = (PATH2_DESCENT_SIS_RANGE_DIGIT_MAX + 1) as u16;
        assert_eq!(
            verify_path2_descent_sis_opening_norm_range(
                PATH2_DESCENT_SIS_ROLE_OPENING_TUPLE,
                &large_range_digit,
            )
            .unwrap_err(),
            "Path 2 descent/SIS opening coordinate exceeds selected bound"
        );
    }

