    #[test]
    fn path2_transparent_proof_family_capability_pins_active_assumptions() {
        let capability = path2_transparent_proof_family_capability_v1().unwrap();
        verify_path2_transparent_proof_family_capability(&capability).unwrap();
        assert_eq!(
            capability.schema,
            PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_SCHEMA
        );
        assert_eq!(
            capability.profile_id,
            PATH2_TRANSPARENT_PROOF_FAMILY_CAPABILITY_PROFILE_ID
        );
        assert_eq!(
            capability.family,
            PATH2_TRANSPARENT_PROOF_FAMILY_ZK_MASKED_TRACE_IOP_NATIVE_BOUNDARY
        );
        assert_eq!(
            capability.relation_layout_digest,
            path2_transparent_relation_layout_v1_digest().unwrap()
        );
        assert_eq!(
            capability.trace_column_manifest_digest,
            path2_native_boundary_trace_column_manifest_v1_digest().unwrap()
        );
        assert_eq!(
            capability.query_schedule_digest,
            path2_transparent_query_schedule_v1_digest().unwrap()
        );
        assert_eq!(
            capability.trace_proof_family_interface_digest,
            path2_native_boundary_trace_proof_family_interface_v1_digest().unwrap()
        );
        assert_eq!(
            capability.column_profile,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1
        );
        assert_eq!(
            capability.active_witness_lane_floor,
            PATH2_NATIVE_BOUNDARY_TRACE_RANGE_ACCOUNT_LANE_FLOOR
        );
        assert_eq!(
            capability.native_boundary_relation_rows,
            PATH2_NATIVE_BOUNDARY_TRACE_RELATION_ROWS_WORKING
        );
        assert!(capability.parent_root_binding);
        assert!(capability.typed_role_subcommitments);
        assert!(capability.creation_binding_role_handles_bound);
        assert!(capability.inner_commitment_binding_break_exported);
        assert!(capability.full_trace_extractable);
        assert!(capability.full_witness_relation_knowledge);
        assert!(capability.hidden_column_zero_knowledge);
        assert!(capability.masked_query_no_export);
        assert!(capability.qrom_schedule_bound);
        assert!(capability.norm_range_soundness);
        assert!(capability.blinding_noise_bound_soundness);
        assert!(capability.role_authentication_material_simulatable);
        assert!(capability.mask_freshness);
        assert!(capability.no_raw_hidden_openings);
        assert!(capability.no_public_linear_role_commitments);
        assert_eq!(
            capability.fallback_threshold_bytes,
            PATH2_TRANSPARENT_PROOF_FAMILY_FALLBACK_THRESHOLD_BYTES
        );
        assert_ne!(
            path2_transparent_proof_family_capability_v1_digest().unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        assert_ne!(
            path2_transparent_descent_proof_system_id(),
            [0_u8; DIGEST_BYTES]
        );

        let mut sampled_only = capability.clone();
        sampled_only.full_trace_extractable = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&sampled_only).unwrap_err(),
            "Path 2 transparent proof-family capability missing full_trace_extractable"
        );

        let mut raw_openings = capability.clone();
        raw_openings.no_raw_hidden_openings = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&raw_openings).unwrap_err(),
            "Path 2 transparent proof-family capability missing no_raw_hidden_openings"
        );

        let mut no_role_subroots = capability.clone();
        no_role_subroots.typed_role_subcommitments = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_role_subroots).unwrap_err(),
            "Path 2 transparent proof-family capability missing typed_role_subcommitments"
        );

        let mut no_creation_binding_role_handles = capability.clone();
        no_creation_binding_role_handles.creation_binding_role_handles_bound = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_creation_binding_role_handles)
                .unwrap_err(),
            "Path 2 transparent proof-family capability missing creation_binding_role_handles_bound"
        );

        let mut no_inner_binding_break = capability.clone();
        no_inner_binding_break.inner_commitment_binding_break_exported = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_inner_binding_break).unwrap_err(),
            "Path 2 transparent proof-family capability missing inner_commitment_binding_break_exported"
        );

        let mut no_no_export = capability.clone();
        no_no_export.masked_query_no_export = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_no_export).unwrap_err(),
            "Path 2 transparent proof-family capability missing masked_query_no_export"
        );

        let mut no_role_auth_simulator = capability.clone();
        no_role_auth_simulator.role_authentication_material_simulatable = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_role_auth_simulator).unwrap_err(),
            "Path 2 transparent proof-family capability missing role_authentication_material_simulatable"
        );

        let mut no_mask_freshness = capability.clone();
        no_mask_freshness.mask_freshness = false;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&no_mask_freshness).unwrap_err(),
            "Path 2 transparent proof-family capability missing mask_freshness"
        );

        let mut wrong_family = capability.clone();
        wrong_family.family = "vanilla_merkle_fri_trace";
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&wrong_family).unwrap_err(),
            "Path 2 transparent proof-family capability family mismatch"
        );

        let mut semantic_core_only = capability.clone();
        semantic_core_only.active_witness_lane_floor =
            PATH2_TRANSPARENT_DESCENT_WITNESS_LANES as u16;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&semantic_core_only).unwrap_err(),
            "Path 2 transparent proof-family capability active witness lane floor mismatch"
        );

        let mut wrong_manifest = capability.clone();
        wrong_manifest.trace_column_manifest_digest[0] ^= 0x80;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&wrong_manifest).unwrap_err(),
            "Path 2 transparent proof-family capability trace column manifest mismatch"
        );

        let mut wrong_schedule = capability.clone();
        wrong_schedule.query_schedule_digest[0] ^= 0x80;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&wrong_schedule).unwrap_err(),
            "Path 2 transparent proof-family capability query schedule mismatch"
        );

        let mut wrong_interface = capability.clone();
        wrong_interface.trace_proof_family_interface_digest[0] ^= 0x80;
        assert_eq!(
            verify_path2_transparent_proof_family_capability(&wrong_interface).unwrap_err(),
            "Path 2 transparent proof-family capability trace proof interface mismatch"
        );
    }

    #[test]
    fn path2_transparent_query_opening_manifest_enforces_no_export_policy() {
        let public_view = path2_transparent_descent_public_view_v1(
            path2_transparent_descent_proof_system_id(),
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            test_digest("path2-query-manifest-leaf-context"),
            test_digest("path2-query-manifest-proof-binding"),
            test_digest("path2-query-manifest-matrix-domain"),
            [3_u16, 5, 7, 11, 13, 17],
            test_digest("path2-query-manifest-aggregation-context"),
            test_digest("path2-query-manifest-trace-root"),
            test_digest("path2-query-manifest-constraint-root"),
            3,
        )
        .unwrap();
        let manifest =
            path2_transparent_query_opening_manifest_fixture_for_public_view(&public_view);
        verify_path2_transparent_descent_public_view(&public_view).unwrap();
        verify_path2_transparent_query_opening_manifest(&manifest).unwrap();
        verify_path2_transparent_query_opening_manifest_for_public_view(&public_view, &manifest)
            .unwrap();
        let scheduled_row = path2_transparent_query_row_index(&public_view, 0).unwrap();
        assert_eq!(manifest.records[0].row_index, scheduled_row);
        assert!(scheduled_row < public_view.trace_rows);
        assert_eq!(
            path2_transparent_query_row_index(&public_view, public_view.query_count).unwrap_err(),
            "Path 2 transparent query row index outside schedule"
        );
        assert_eq!(
            manifest.schema,
            PATH2_TRANSPARENT_QUERY_OPENING_MANIFEST_SCHEMA
        );
        assert_eq!(
            manifest.column_profile,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1
        );
        assert_ne!(
            path2_transparent_query_opening_manifest_digest(&manifest).unwrap(),
            [0_u8; DIGEST_BYTES]
        );
        let serialized = serde_json::to_string(&manifest).unwrap();
        assert!(serialized.contains(PATH2_TRANSPARENT_QUERY_OPENING_MANIFEST_SCHEMA));
        assert!(serialized.contains("component_digest"));
        assert_no_path2_transparent_private_material(&serialized);

        let mut wrong_query_row = manifest.clone();
        let wrong_row = (scheduled_row + 1) & (public_view.trace_rows - 1);
        for record in &mut wrong_query_row.records {
            if record.query_index == 0 {
                record.row_index = wrong_row;
            }
        }
        verify_path2_transparent_query_opening_manifest(&wrong_query_row).unwrap();
        assert_eq!(
            verify_path2_transparent_query_opening_manifest_for_public_view(
                &public_view,
                &wrong_query_row,
            )
            .unwrap_err(),
            "Path 2 transparent query opening row does not match schedule"
        );

        let mut rebound_mask_domain = manifest.clone();
        rebound_mask_domain.records[1].mask_domain_digest[0] ^= 1;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest_for_public_view(
                &public_view,
                &rebound_mask_domain,
            )
            .unwrap_err(),
            "Path 2 transparent query opening mask domain digest mismatch"
        );

        let mut rebound_mask_domain_id = manifest.clone();
        rebound_mask_domain_id.records[1].mask_domain_id +=
            PATH2_TWO_VIEW_COLUMN_PROFILE_ENTRY_COUNT as u16;
        rebound_mask_domain_id.records[1].mask_domain_digest =
            path2_transparent_query_opening_mask_domain_digest(
                &public_view,
                &rebound_mask_domain_id.records[1],
            )
            .unwrap();
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&rebound_mask_domain_id).unwrap_err(),
            "Path 2 transparent query opening mask domain id mismatch"
        );

        let mut stale_public_view_context = public_view;
        stale_public_view_context.leaf_context_digest[0] ^= 1;
        assert_eq!(
            path2_transparent_query_opening_mask_domain_digest(
                &stale_public_view_context,
                &manifest.records[1],
            )
            .unwrap_err(),
            "Path 2 transparent transcript digest mismatch"
        );
        assert_eq!(
            verify_path2_transparent_query_opening_manifest_for_public_view(
                &stale_public_view_context,
                &manifest,
            )
            .unwrap_err(),
            "Path 2 transparent transcript digest mismatch"
        );

        let mut truncated = manifest.clone();
        truncated.records.pop();
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&truncated).unwrap_err(),
            "Path 2 transparent query opening manifest count mismatch"
        );

        let mut unsupported_query_count = manifest.clone();
        unsupported_query_count.query_count = 12;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&unsupported_query_count).unwrap_err(),
            "Path 2 transparent proof query count is outside active schedule"
        );

        let mut duplicate_role = manifest.clone();
        duplicate_role.records[2].role_id = duplicate_role.records[1].role_id;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&duplicate_role).unwrap_err(),
            "Path 2 transparent query opening duplicate query role"
        );

        let mut permuted = manifest.clone();
        permuted.records.swap(1, 2);
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&permuted).unwrap_err(),
            "Path 2 transparent query opening manifest order mismatch"
        );

        let mut row_mismatch = manifest.clone();
        row_mismatch.records[2].row_index += 1;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&row_mismatch).unwrap_err(),
            "Path 2 transparent query opening row mismatch"
        );

        let mut hidden_column = manifest.clone();
        let packed_entry =
            path2_two_view_column_profile_entry(PATH2_TWO_VIEW_ROLE_PACKED_WITNESS).unwrap();
        hidden_column.records[1].column_set_id = packed_entry.hidden_column_set_id;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&hidden_column).unwrap_err(),
            "Path 2 transparent query opening uses hidden column set"
        );

        let mut raw_hidden = manifest.clone();
        raw_hidden.records[1].visibility_class = PATH2_TWO_VIEW_VISIBILITY_EXTRACTOR_HIDDEN;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&raw_hidden).unwrap_err(),
            "Path 2 transparent query opening exposes hidden visibility class"
        );

        let mut unmasked_hidden = manifest.clone();
        unmasked_hidden.records[1].visibility_class = PATH2_TWO_VIEW_VISIBILITY_PUBLIC;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&unmasked_hidden).unwrap_err(),
            "Path 2 transparent query opening hidden role is not masked"
        );

        let mut duplicate_mask = manifest.clone();
        duplicate_mask.records[3].mask_domain_id = duplicate_mask.records[1].mask_domain_id;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&duplicate_mask).unwrap_err(),
            "Path 2 transparent query opening mask domain id mismatch"
        );

        let mut unknown_role = manifest.clone();
        unknown_role.records[0].role_id = 0xff;
        assert_eq!(
            verify_path2_transparent_query_opening_manifest(&unknown_role).unwrap_err(),
            "Path 2 transparent query opening unknown role"
        );
    }

    #[test]
    fn path2_transparent_descent_public_view_serializes_only_public_material() {
        let proof_system_id = [1_u8; DIGEST_BYTES];
        let leaf_context_digest = [2_u8; DIGEST_BYTES];
        let creation_proof_binding_digest = [3_u8; DIGEST_BYTES];
        let matrix_domain_transcript_digest = [4_u8; DIGEST_BYTES];
        let aggregation_context_digest = [5_u8; DIGEST_BYTES];
        let trace_commitment_root = [6_u8; DIGEST_BYTES];
        let constraint_commitment_root = [7_u8; DIGEST_BYTES];
        let masked_projection = [1_u16, 2, 3, 4, 5, 6];
        let view = path2_transparent_descent_public_view_v1(
            proof_system_id,
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            creation_proof_binding_digest,
            matrix_domain_transcript_digest,
            masked_projection,
            aggregation_context_digest,
            trace_commitment_root,
            constraint_commitment_root,
            0,
        )
        .unwrap();
        assert_eq!(view.schema, PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA);
        assert_eq!(view.relation_id, path2_transparent_descent_relation_id());
        assert_eq!(
            view.transparent_transcript_digest,
            path2_transparent_descent_transcript_digest(
                &proof_system_id,
                256,
                16,
                PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
                &leaf_context_digest,
                &creation_proof_binding_digest,
                &matrix_domain_transcript_digest,
                &masked_projection,
                &aggregation_context_digest,
                &trace_commitment_root,
                &constraint_commitment_root,
                0,
            )
            .unwrap()
        );
        let serialized = path2_transparent_descent_public_view_v1_json(
            proof_system_id,
            256,
            16,
            PATH2_TWO_VIEW_COLUMN_PROFILE_MASKED_BASE128_V1,
            leaf_context_digest,
            creation_proof_binding_digest,
            matrix_domain_transcript_digest,
            masked_projection,
            aggregation_context_digest,
            trace_commitment_root,
            constraint_commitment_root,
            0,
        )
        .unwrap();
        assert!(serialized.contains(PATH2_TRANSPARENT_PUBLIC_VIEW_SCHEMA));
        assert!(serialized.contains("masked_projection"));
        assert!(serialized.contains("transparent_transcript_digest"));
        assert_no_path2_transparent_private_material(&serialized);
    }

