    #[test]
    fn selected_projection_materializers_are_not_public_pre_spend_api() {
        let source = std::fs::read_to_string(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/production_reference.rs"),
        )
        .unwrap();
        let forbidden_name_terms = [
            "selected_material",
            "selected_projection_material",
            "projection_material",
            "pre_spend",
        ];
        let forbidden_return_terms = [
            "ProductionReviewedFq12MaskedState18PackedWitnessOpening",
            "HiddenSourceFallbackProjectionHiddenMaterialFrameReplayInput",
            "HiddenSourceFallbackProjectionAccountWitnessOpening",
            "HiddenSourceFallbackProjectionHiddenMaterialReplayInput",
        ];
        let allowed_public_functions = [
            "reviewed_fq12_packed_witness_state18_projection_opening",
            "reviewed_fq12_packed_witness_state18_projection_masks",
            "reviewed_fq12_pack_masked_witness_state18_from_parts",
            "reviewed_fq12_masked_packed_witness_state18_projection_opening",
            "reviewed_fq12_masked_state18_packed_witness_opening_frame",
            "reviewed_fq12_masked_state18_packed_witness_opening_digest",
            "reviewed_fq12_masked_state18_packed_witness_opening",
            "validate_reviewed_fq12_masked_state18_packed_witness_opening",
            "hidden_source_fallback_projection_values_from_hidden_material",
            "verify_hidden_source_fallback_hidden_material_projection_or_export",
            "verify_hidden_source_fallback_hidden_material_frame_projection_or_export",
        ];
        let mut violations = Vec::new();
        for line in source.lines() {
            let trimmed = line.trim();
            if !trimmed.starts_with("pub fn ") {
                continue;
            }
            if allowed_public_functions
                .iter()
                .any(|allowed| trimmed.contains(allowed))
            {
                continue;
            }
            let exposes_forbidden_name = forbidden_name_terms
                .iter()
                .any(|term| trimmed.contains(term));
            let exposes_forbidden_return = forbidden_return_terms
                .iter()
                .any(|term| trimmed.contains(term));
            if exposes_forbidden_name || exposes_forbidden_return {
                violations.push(trimmed.to_string());
            }
        }
        assert!(
            violations.is_empty(),
            "public pre-spend selected projection materializers found: {violations:?}"
        );
    }

    #[test]
    fn sign_with_account_binding_checks_slot_and_randomizer() {
        let (account, signature) = sample_account_and_signature();
        let slot = account.get_slot(0).unwrap();
        let signed = sign_with_account_binding(slot, |slot_id, witness_commitment| {
            assert_eq!(slot_id, 0);
            assert_eq!(witness_commitment, slot.commitment().witness_commitment());
            Ok(signature.clone())
        })
        .unwrap();
        assert_eq!(signed, signature);

        assert_eq!(
            sign_with_account_binding(slot, |_slot_id, _witness_commitment| {
                let mut mismatched = signature.clone();
                let mut bytes = mismatched.as_bytes().to_vec();
                bytes[..SLOT_ID_BYTES].copy_from_slice(&1_u32.to_le_bytes());
                mismatched = ProductionSignature::new(bytes);
                Ok(mismatched)
            })
            .unwrap_err(),
            "signature slot id mismatch"
        );

        assert_eq!(
            sign_with_account_binding(slot, |_slot_id, _witness_commitment| {
                let mut bytes = signature.as_bytes().to_vec();
                let proof_start = STATEFUL_TRANSACTION_SIGNATURE_BYTES;
                bytes[proof_start] ^= 1;
                Ok(ProductionSignature::new(bytes))
            })
            .unwrap_err(),
            "account randomizer commitment does not match proof commitment"
        );
    }

