    #[test]
    fn path2_reviewed_fq12_hidden_source_payload_binding_carries_native_boundary() {
        let fixture = masked_projection_fixture();
        let mut bundle = native_projection_bundle_fixture();
        bundle.lifecycle.slot_id = fixture.slot.slot_id() as u64;
        bundle.state.account_state_root_before = test_digest("payload-binding-state-root");
        bundle.lifecycle.lifecycle_anchor = test_digest("payload-binding-lifecycle-anchor");
        let checked_core_proof_bytes = path2_native_checked_core_proof_from_bundle_v1(&bundle)
            .expect("fixture checked-core proof");

        let mut leaf = Path2PrevalidatedSlotLeafV1 {
            frame_version: PATH2_PREVALIDATED_SLOT_LEAF_FRAME_VERSION,
            profile_version_digest: test_digest("payload-binding-profile"),
            account_id: bundle.account.account_id,
            public_key_identity: bundle.account.public_key_identity,
            slot_id: bundle.lifecycle.slot_id,
            verifier_version_digest: test_digest("payload-binding-verifier"),
            account_state_root_before: bundle.state.account_state_root_before,
            opening_commitment: fixture.slot.hidden_source_opening_commitment(),
            pad_seed_digest: fixture.slot.pad_seed_digest(),
            hidden_source_statement_digest: [0_u8; DIGEST_BYTES],
            prevalidation_transcript_digest: test_digest("payload-binding-prevalidation"),
            lifecycle_anchor: bundle.lifecycle.lifecycle_anchor,
            live_status_marker: PATH2_PREVALIDATED_SLOT_LIVE_STATUS_MARKER,
        };
        let creation_statement =
            path2_creation_hidden_source_statement_v1_from_reviewed(&leaf, &fixture.statement);
        leaf.hidden_source_statement_digest = creation_statement.digest;

        let binding = path2_reviewed_fq12_hidden_source_payload_binding_v1(
            &leaf,
            test_digest("payload-binding-creation-proof-binding"),
            &bundle,
            &checked_core_proof_bytes,
            &fixture.statement,
            &fixture.opening,
            &fixture.carrier,
        )
        .unwrap();
        let assembly = assemble_path2_native_boundary_v1(&bundle, &checked_core_proof_bytes)
            .expect("fixture native boundary assembly");
        assert_eq!(
            binding.native_boundary_digest,
            assembly.native_boundary_digest
        );
        assert_eq!(binding.slot_id, leaf.slot_id);
        assert_eq!(
            binding.hidden_source_statement_digest,
            leaf.hidden_source_statement_digest
        );
        assert_eq!(binding.opening_commitment, leaf.opening_commitment);
        assert_eq!(binding.pad_seed_digest, leaf.pad_seed_digest);
        assert_eq!(
            binding.checked_core_frame_digest,
            path2_native_checked_core_frame_v1_digest(&assembly.checked_core_frame).unwrap()
        );
        assert_eq!(binding.checked_core_proof_bytes_digest, {
            let digest: [u8; DIGEST_BYTES] = Sha256::digest(checked_core_proof_bytes).into();
            digest
        });
        assert_eq!(
            path2_reviewed_fq12_hidden_source_payload_binding_v1_digest(&binding).unwrap(),
            binding.payload_digest
        );
        verify_path2_reviewed_fq12_hidden_source_payload_binding_v1(
            &binding,
            &leaf,
            &bundle,
            &checked_core_proof_bytes,
            &fixture.statement,
            &fixture.opening,
            &fixture.carrier,
        )
        .unwrap();

        let mut rebound = binding;
        rebound.native_boundary_digest[0] ^= 1;
        rebound.payload_digest =
            path2_reviewed_fq12_hidden_source_payload_binding_v1_digest(&rebound).unwrap();
        assert_eq!(
            verify_path2_reviewed_fq12_hidden_source_payload_binding_v1(
                &rebound,
                &leaf,
                &bundle,
                &checked_core_proof_bytes,
                &fixture.statement,
                &fixture.opening,
                &fixture.carrier,
            )
            .unwrap_err(),
            "Path 2 payload binding mismatch"
        );

        let mut wrong_slot_bundle = bundle;
        wrong_slot_bundle.lifecycle.slot_id += 1;
        assert_eq!(
            path2_reviewed_fq12_hidden_source_payload_binding_v1(
                &leaf,
                test_digest("payload-binding-creation-proof-binding"),
                &wrong_slot_bundle,
                &checked_core_proof_bytes,
                &fixture.statement,
                &fixture.opening,
                &fixture.carrier,
            )
            .unwrap_err(),
            "Path 2 payload binding slot id mismatch"
        );
    }

