    #[test]
    fn spent_slot_ledger_file_store_roundtrips_records() {
        let path = std::env::temp_dir().join(format!(
            "descender-spent-ledger-{}-{}.json",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let store = ProductionSpentSlotLedgerFileStore::new(&path);
        assert_eq!(store.path(), path.as_path());
        assert!(store.load_ledger().unwrap().is_none());

        let public_key = ProductionPublicKey::new(vec![0_u8; PK_BYTES]).unwrap();
        let (account, signature) = sample_account_and_signature();
        let manager = ProductionAccountLifecycleManager::new(account).unwrap();
        let checked = verify_account_binding(manager.account(), &signature).unwrap();
        let mut ledger = ProductionSpentSlotLedger::new();
        ledger
            .record_checked_signature(&public_key, &checked, 7, "accepted verification")
            .unwrap();
        store.save_ledger(&ledger).unwrap();

        let restored = store.load_ledger().unwrap().unwrap();
        assert_eq!(restored.len(), 1);
        let key = ProductionSpentSlotLedger::key(&public_key, 0);
        assert!(restored.is_spent(&key));
        assert_eq!(
            restored
                .require_unspent(&public_key, 0)
                .unwrap_err()
                .reason(),
            "slot is already in spent ledger"
        );
        let record = restored.records().next().unwrap();
        assert_eq!(record.snapshot_sequence, 7);
        assert_eq!(record.source, "accepted verification");

        let _ = std::fs::remove_file(path);
    }

